/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180702-6","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"区民委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"第４７号議案 品川区印鑑条例の一部を改正する条例","agenda":"第４７号議案 品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"新たに印鑑登録証をつくる人というのは、全員一元化されて１つのカードになってしまうのかというところを確認させてほしいと求めました。そして、情報が芋づる式的に得られるようになってしまうということになるのか、そこのところを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"申し出があった場合ということで、今ご説明したとおりですけれども、申し出があった場合に限って、一元化をすると。印鑑登録の情報をそこに埋め込むということで、芋づる式的に情報が引き出されるとか、そういうことは決してございません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"申請書自体が、１つになって出されるような形にならないかというところを危惧しておりまして、そこのところを確認させてほしいと求めました。そうすると、マイナンバーの情報が出てくるということはないということでよろしいかということと、空き部分というのがどのくらいあるのか尋ねました。","respondent":"提坂戸籍住民課長","answer":"その場合、一元化できるということをご説明させていただいて、１００円安く印鑑証明書が取れるということもご説明させていただいた上で。希望される方については、印鑑登録の申請書とは別に、利用届という書類を一筆書いていただく予定です。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"希望者の方はカードを一元化できるということで、万が一、それを一元化した後に、やはりもとに戻したいということもできるのか、伺いたいと思います。大体何割ぐらい空いているとか、どのくらい使っているというのがもしわかれば、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"その際は、既に登録しているということで、手数料はいただきません。まだまだ活用の部分がかなりあるということで、区役所でもまだまだ活用の余地があると思いますので、かなりの空きはあると考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"確認","question":"窓口が混雑しているというのは、印鑑登録証明書の発行が原因になっているのか、そこのところを伺いたいと思います。カードの一元化をすると、その認識が正しいかというところの確認と、ほかに登録者にとって今までとの変更点があれば伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"登録内容の変更のところで、第９条の２の第３項のところで、ここの部分については本人申請に限る旨を規定させていただいたものです。それから、すみません、もう１点。","id":"exchange-004"},{"speaker":"のだて委員","kind":"意見","question":"登録した内容の変更が代理人ではできなくなるのかということと、ほかに変更点があるかどうかということですとの意見を述べました。","respondent":"提坂戸籍住民課長","answer":"登録内容の変更につきましては、今申し上げたとおり、本人申請に限るです。一元化の手続については大きな変更はございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"印鑑登録原票のほうも伺いたいのですが、また、原票の電子化で区民への影響はあるのかを伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"区の委託しているベンダーのほうで２４時間、監視システムということを行ってございまして、セキュリティ対策は万全と考えています。ダウンした場合も、バックアップのデータを保管しておりますので、その辺の対応も万全になっております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"バックアップもあるということですが、そのバックアップは、委託している監視システムのところでされているということか尋ねました。","respondent":"提坂戸籍住民課長","answer":"失礼しました。そちらでも保管していますし、区でも参照系データというデータをもってございまして、万が一のダウンに備えてあります。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜこう日本は印鑑を重視する文化なのか、教えていただきたいのが１点と、安全性は改めて担保されるのでしょうかということ。やはり公という意味で印鑑証明等があるわけですから、生活安全担当課長にお伺いしたいのですが、わかる範囲で教えていただけますか。","respondent":"提坂戸籍住民課長、菅生活安全担当課長","answer":"各自治体で印鑑登録の制度を実施していて、さまざまな契約書に押してある判と同一の印鑑だということで、日本での潮流になってきたです。印鑑登録証に限ったことではないですけれども、コールセンターがございまして… これは警視庁捜査二課が担当しているということを把握しておりますが、捜査の進展状況というのは、私のほうでは把握はしておりません。関係者が多数いるということですので、今後捜査が進展するものと考えております。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"２点、安全性はきちんと担保されるのかということをお伺いしているので、そこをはっきりお話してほしいと求めました。こういう施策に対してどういうお考えか、現場にいた方としてどう思われるか、感想でいいのでお伺いしたいと思っています。","respondent":"提坂戸籍住民課長、菅生活安全担当課長","answer":"４桁の暗証番号を入力していただいて、印鑑証明をお出しするということなので、安全性は確保されていると考えています。紛失した場合は、マイナンバーカードのコールセンターと警察に早急に届け出をしていただきますので… やはり区の施策として、いろいろなセキュリティに関する施策というのは非常に難しいのかなと感じております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問","question":"印鑑登録原票の電子化について伺いたいのですけれども、原票を磁気ディスク化することによって、今カードを持っている方に関して、またそのカードが変わるとか、そういうこともあるのか、それとも今のままで、事務作業上のことが変化するというだけなのかということを説明を求めました。","respondent":"提坂戸籍住民課長","answer":"印鑑登録原票の電子化については、あくまでも内部の事務作業を変えるということでございまして、印鑑登録されているお客様の印鑑登録証を変えるとか、そういうことではございません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"個人番号カードと印鑑登録証の一元化についてなのですけれども、コンビニ交付の利用促進を図ると改正理由に書かれています。現状を教えていただきたいのと、もう少しそこら辺を詳しく教えていただきたいのですけれども、お願いします。","respondent":"提坂戸籍住民課長","answer":"安全性、セキュリティの関係ですけれども、コールセンターのご説明が足りなくて申し訳ございませんでした。２４時間３６５日、ご本人からの盗難とか紛失のご連絡を受けて、悪用を防止するという形で安全性を担保していると考えています。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認をさせていただきたいのが、手数料は要らないということだったかどうかの確認と、電子化するための費用というのがどのくらいかかるのか。窓口の混雑緩和とか、推し進めていって、どのくらいまでこれを広げていきたいというものがあるのかというのを教えてもらいたいと思います。","respondent":"提坂戸籍住民課長","answer":"今はマイナンバーカードの普及率が、人口に対して約１５％弱ぐらいですけれども、昨年１年間で約１万件の伸びがございました。今後は１万件、区民の方の４分の１とか５分の１ぐらいの普及率を目指して、窓口の混雑緩和を図っていきたいと考えています。","id":"exchange-012"},{"speaker":"大倉委員","kind":"質問","question":"区民の利便性というところで、いろいろなところでそういうことができないといけないのかなと思っているので、その辺についての今後の考え方を説明を求めました。","respondent":"提坂戸籍住民課長","answer":"先ほど申し上げた６カ所の地域センターに限らせていただいておりまして、こちらについては今後変更する予定は、今のところ考えてございません。それでも、区内で６カ所、本庁を入れると７カ所ありますので、区民の方の利便性は保たれると考えています。","id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"コールセンターに２４時間電話してもらえれば、その辺はどうやって知ったらいいのでしょうかということを教えていただきたい。難しいのかなと思うので、その周知について、どのような点があるか説明を求めました。","respondent":"提坂戸籍住民課長","answer":"ご本人にマイナンバーカードをお渡しする際に、コールセンターの連絡先とか、その辺も含めてお知らせしています。今後、コンビニ交付とかマイナンバーカードの普及を図る広報をするときに、その辺もあわせて周知を図ってまいりたいと考えております。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"質問","question":"その辺のお考えをひとつ教えてください。もう１個は、その辺のところをもう一度、詳しく説明を求めました。","respondent":"提坂戸籍住民課長","answer":"説明をさせていただいた上で、どれぐらいの件数が出るかは、正直申し上げて読めないところがあります。安全性の担保につきましても、説明をし尽くさせていただいた上でお受けしますので、安全性は担保されると考えています。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問","question":"こういうことには、なぜこうなのか、理由を簡単に言っていただいたほうが、最もわかりやすい気がします。その点だけ説明を求めました。","respondent":"提坂戸籍住民課長","answer":"６地域センター以外の７地域センターでも印鑑登録をやりたいとか、現行の体制で十分対応できると考えてございまして、６地域センターで行わせていただくのは問題ないと考えています。","id":"exchange-016"},{"speaker":"浅野副委員長","kind":"質問","question":"今回、印鑑登録証の件ということで、若干聞きそびれたところもあるので、そういうのも教えてほしいと求めました。費用がかかった部分とか、そういうものがあれば、少し教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"約３０年前ですけれども、印鑑登録原票についても内容変更があったら、かなり課題となってきたところです。スペースを削減するということと、その作業を減らすということで、課題を解決していこうと考えているところです。","id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"光ディスクですか、どういうことかなと思ったのですけれども、大体認識はできました。それとも専用の形で情報を保存するのか、どのような形で対応されていくのか、その安全性についての考え方を教えてほしいと求めました。","respondent":"提坂戸籍住民課長","answer":"先ほどもご説明させていただいたのですけれども、データの監視センターで常に２４時間３６５日監視をしていくということと、万全と考えています。","id":"exchange-018"},{"speaker":"浅野副委員長","kind":"意見","question":"いろいろと調製というのはどういう形で行われているのか、２３区外でも、今回やっていくというふうにされていると思います。区民の中の情報が損失しないような取組みを、さらに進めていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのご答弁の中で、ほかの委員とのやりとりの中で、マイナンバーの普及率が１５％弱というお話を伺ったと思うのですけれども、区内での普及率だったり、ここ何年間かの推移とかそういうのは、今もし数字があったら教えていただきたいなと思うのですけれども。","respondent":"提坂戸籍住民課長","answer":"約５万６,０００人いらっしゃいまして、平成２８年度末で三万七、八千人ぐらいの普及がございました。差し引くと平成２９年度１年間と５月末までで、１万数千人の申請があったということで、着実にマイナンバーカードの普及は進んでいると考えています。","id":"exchange-020"},{"speaker":"のだて委員","kind":"意見","question":"犯罪にも利用されておりますので、この制度は廃止にこそすべきであって、普及させるべきではないと思います。先ほどのご答弁の中でも、空き容量がかなり余っているというところで、さらなる利用拡大への第一歩であるということで、これについては反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"印鑑登録原票の電子化については、流れとして賛成したいのですが、個人番号カード、マイナンバーと、印鑑登録証の一元化については、やはり情報漏えいの危険性が高まることなどが考えられることと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-02","title":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"振り込め詐欺などの例は、どうして件数や被害額が倍以上になってしまったのか、区の認識を伺いたいと思います。もう少しほかに、この自動通話録音機を設置する効果について、あれば伺いたいと思います。","respondent":"菅生活安全担当課長","answer":"設置する効果ですけれども、設置した方からは、そういった効果もあるのかなと思っています。この自動通話録音機を設置しているということを犯人側が認識することで、警戒しているなということを知らしめるという効果もあると考えております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"情報が行き渡っていないという話もありましたけれども、そこのところは区としても、さらに注意喚起をしてほしいと求めました。被害をどう防ぐかと考えたときに、その対策の一助になると思いますので、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問","question":"補正予算になったのは、被害発生状況についてなのですけれども、これは固定電話に限った被害状況の数字なのかということを聞きたいです。区内で被害が出ているところの地域性とかはあるのか、もしもわかれば、これも説明を求めました。","respondent":"菅生活安全担当課長","answer":"１月から５月までの８３件につきましては、架空請求詐欺ですとか、必ずしも自宅の固定電話にかかってきた被害だけというわけではございません。警察署単位でいきますと、大崎署管内では８件、それから荏原警察署管内では２９件という状況になっているものです。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"どうやって貸していくかというところをお聞かせいただきたいと思うのと、区民の財産が１億６,０００万円なくなるというところでいうと、その辺の考え方について説明を求めました。","respondent":"菅生活安全担当課長","answer":"これまでも６５歳以上の高齢者の希望者ということでございまして、これは各警察署とも連携しながら、設置を促進していくということにしております。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問","question":"それはわかるのですが、納期の問題はありますが、コスト的には非常に効果があるのではないかなと思うのです。効果があるわけですから、今後どうやっていくかというところだけ、最後に教えてもらえれば。","respondent":"菅生活安全担当課長","answer":"次から次へと犯人側が手口を変えてくるですので、そういった手口を広く区民の方々に広報しながら、注意喚起を図っていきたいと考えております。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"自動通話録音機の周知はどのようにされていたのでしょうか。すみません、そこだけ確認させてください。","respondent":"菅生活安全担当課長","answer":"区のホームページでも周知をしていましたが、広報紙でも自動通話録音機を入荷次第、また掲載することにしております。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"当事者の６５歳以上の方たちに、確実にというか、届くような周知方法というのは、どのようにされているのかというのを伺いたくて、ホームページもなかなか開いたりしないのかなとも思うので、どのような工夫がされているのか、そこだけ聞かせてください。","respondent":"菅生活安全担当課長","answer":"各警察署で実施をしております区の高齢者を対象とした防犯講話といったところでも、民生委員協議会におきましても、高齢者の見守りをしている委員の方々から高齢者の方にこの紹介をしていただくということをしております。","id":"exchange-029"},{"speaker":"浅野副委員長","kind":"質問","question":"少しどころか、区民の財産を守るという形で、これも同時に進めていかなければならないなと思っています。ほとんど質問は出てしまったのですけれども、１点だけお伺いしたいのが、教えてほしいと求めました。","respondent":"菅生活安全担当課長","answer":"貸与にした経緯といいますのは、平成２７年に東京都が最初にこの自動通話録音機を購入して、このときから貸与という形にしております。貸与ということで、一旦、都内を出られるときにはご返却いただくという形をとっております。","id":"exchange-030"},{"speaker":"浅野副委員長","kind":"質問","question":"貸与ということなので、確かに戻さなければならないという状況になるかと思うのですけれども、知らない間に転居した場合、どうしようもないかなと思うのですけれども、この場合まで追いかけてというのは、転居先がわからない限りは難しいかなと思いますけれども、この点についてはいかがか尋ねました。","respondent":"菅生活安全担当課長","answer":"最初に貸与するときに、一応説明書といいますか、取り決めといいますか、他の区に転居するときには返却してくださいということは説明をしておりますので、その辺は、信じるしかないと考えているところです。","id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"電話番号がわかるわけですから、担当の方が電話１本入れて、一番もったいないではないですか。１カ月後ぐらいに１回電話を入れて、きちんと稼働しているかという確認はするべきだと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"菅生活安全担当課長","answer":"警察署によりましては、ご自宅まで伺って設置の補助をしたりとか、ご自宅までお伺いして設置の補助とか説明をするということをしております。実際に取りつけていただいてから、本当にその機能がきちんと使えるかどうかは、今後対応していきたいと考えております。","id":"exchange-032"},{"speaker":"田中委員","kind":"確認","question":"お引っ越しされた場合とかの返却率というか、今どのぐらいきちんと返ってきているのかなというのを確認したいのですけれども、どうなのでしょうか。わかる範囲で説明を求めました。","respondent":"菅生活安全担当課長","answer":"そういった形で返却されているというのが、平成２９年度でいきますと、大体１０台程度返却をされている状況です。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2812#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":22397,"voices":96}},{"id":"h30-20180702-7","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"厚生委員会","time":"午前１０時００分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"第５３号議案のほうの現行で言うホテル営業、旅館営業、簡易宿所営業、下宿営業と４つあるのですけれども、これは区内に何軒、幾つあるかということがわかれば教えていただけますか。","respondent":"鈴木生活衛生課長","answer":"平成２９年度の数字になります。旅館業の中でホテルが４５軒、旅館営業が２２軒、簡易宿所が１７軒、下宿は今、０軒になっております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"第５４号議案のほうは、この技術的助言というのはどういうことなのか、区にとっては重みがあるものなのでしょうか。その辺を説明を求めました。","respondent":"鈴木生活衛生課長","answer":"国の技術的助言に当たる要領ですが、これは具体的な衛生管理または指導をする上で必要な内容を記しているものなので、負担というよりは、具体的な実務に役に立つ基準になるものを示しているものだというふうに認識しております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"ある程度、区で変えるところを選べるというか、選定していけるのかを伺います。","respondent":"鈴木生活衛生課長","answer":"実務上はこれに準じたものにするというのが基本的な考え方になりますので、ほかの各区、保健所も含めて同様の考え方で改正をしているものです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、区はこの要領によってこの条例を大きく変えているわけですけれども、改正内容のところに、「旅館業法等の改正に伴い」というふうにあるのですけれども、この「等」の中身はどのようなものがあるのか、どのような中身なのか伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"法令等の中に含まれるものですが、第５４号議案の説明資料の１番の改正理由にありますように、旅館業法、旅館業法施行令の政令、旅館業法施行規則の省令、それと管理要領、法律ではありませんが、衛生等の管理要領、これを含めて「等」という表現にしております。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この施行令、施行規則、これがそれぞれ中身がどういうものなのか簡単に教えてほしいと求めました。そしてこれ、すごく民泊に近づけている感じがするのですけれども、民泊との違いはどういうところなのかを説明を求めました。","respondent":"鈴木生活衛生課長","answer":"基本的には先ほどまとめた４項目が主な改正の内容で、その項目ごとに具体的な規定の文言がたくさんあるものが全て変わっていくという考え方です。住宅宿泊事業法のほうは届出ということで、規制の強さや規定される宿泊施設の内容についても異なるものです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどご説明された資料でわかったのですけれども、一番下に「戸建て住宅や集合住宅の１室を活用するなど、これは何を意味しているのか。これは民泊のことではないのですかと思ったのですけれども、この旅館業の条例の改正の中に入っているのはなぜなのかを伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"戸建て住宅や集合住宅の１室の活用は、これは住宅宿泊事業法、民泊とは違いまして、旅館業法における簡易宿所のものです。実際に６月１５日に住宅宿泊事業法が施行されて、３月から引き続き届出を受けておりますが、そちらの規定ということになります。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっとわからなかったのですけれども、旅館業で申請するものが、戸建て住宅や集合住宅の１室を活用してできることになっているということですか。何もなしに戸建て住宅や集合住宅の１室を活用して、新たな宿泊形態ができる形に今はなっているから、この独自規定を設けたのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"旅館業法のほうでも、簡易宿所という営業形態は、先ほどの手数料条例にもありましたように、もともとあるものです。簡易宿所のような戸建てとか集合住宅の一室を活用するという形態も出てきているという意味でございまして、民泊のことを差すわけではございません。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"旅館業法ですからそうですね。品川での見通しをどうお持ちかなと、来ているということなのですけれども、こういった規制が緩和されたもとでのホテルや旅館が増えていくのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういう観点からこの規制改革推進会議というのですか、ホテル・旅館は、建てられる設置地域が限られてきているのですね。民泊よりも制限がされているかと思うのですけれども、改めて、旅館とホテルの用途地域を教えていただきたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、これもこの条例に合わせて、きっと緩いものに緩和されていくのかと思うのですけれども、この中に用途地域もあるのです。旅館・ホテルが建てられる地域を教えてもらいたいということだったのですが、もう１回、用途地域を伺いたいです。","respondent":"鈴木生活衛生課長","answer":"先ほどからご説明しておりますように、国の動きのところの丸ポチの３つ目の後段ですが、設備の基準は緩和です。ですので、営業関係、そもそもの許可を取ったりだとか、用途地域の変更はございません。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"確認","question":"今現在、ホテル・旅館が建てられるところはどこなのかということを確認したかったのですけれども、それはわかりませんか。〔「ここに資料があるだろう、持っているだろう」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは複雑で、聞けたらいいなと思って伺ったのです、すみません。で建築のほうに聞いてみますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林委員","kind":"提案","question":"しっかりとした基準を持って、区もチェック体制も含めて、この条例を提案しているのですというところの担保のところ。規制緩和されたけれども、旅館業法の目的に沿って品川区の条例もつくられていくのですと、安心できるご説明をいただきたいと思うのですけれどもとの意見を述べました。","respondent":"鈴木生活衛生課長","answer":"それから実務上の監視業務、指導業務についても、それにのっとってしっかりとやっていくです。","id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"そこの確認と、今後の品川区の検査体制といいますか、ここら辺もしっかり行っていくというところも担保をとっておきたいと思います。","respondent":"鈴木生活衛生課長","answer":"ただし、全く新規のものが策定されてまだ来ていないという段階ではございませんので、しっかりと基準は従来どおりやってまいりたいと思います。よりしっかりと監視業務、指導業務を続けながら、区民の方の安全や安心を守っていきたいと考えております。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"手数料条例のときに、平成２９年度とおっしゃっていたのですけれども、平成３０年に入ってから簡易宿所の申請はどのぐらい出ているのですか。もしわかれば、４月以降、状況を教えてもらいたいと思います。","respondent":"鈴木生活衛生課長","answer":"４月以降、簡易宿所は、私の手元の決裁を通過した件数で記憶しているのは、現在、２件です。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"４番のところで関連規則の改正というところでは、条例の施行規則は改正するということでご説明がありましたけれども、例えば帳場は今度なくしますね。〔「ＩＣＴでもいいということ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その点が１点お聞かせいただきたいのと、１週間に、工業専用地域というところは不可地域というふうになっているのです。そこのところから１１０ｍ離れていれば可能ですという、そういうふうなことになるのか、そこの確認だけお願いしたいと思います。","respondent":"鈴木生活衛生課長","answer":"要綱の改正ですが、ご指摘のとおり、条例施行規則等を改正した後に、それに合わせた改正が必要な部分については、今後、作業を進めていく予定です。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"こういうふうに客室は４０ルクス以上とか、調理場を設置することとか、そういうことで考えていいということなのでしょうか。今までここに規定されていたものを、なくなったものに対してはチェックはされないという、そういうことになるのかということで説明を求めました。","respondent":"鈴木生活衛生課長","answer":"先ほどからご説明しているように、具体的な数値ではなくて、質の担保ということで定性で規定をしておりますので、そこのチェックは行います。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今まで基準として数値的に確認をされてきた、例えば１人当たり３.３m2とか、そういうふうなことに対してのチェックも具体的な数値としてはチェックをしないということになるということの確認だけさせてください。","respondent":"鈴木生活衛生課長","answer":"ご指摘のとおり、数字的なチェックではなくて、設備が衛生や安全を確保できる状態にあるかどうか、法の表現に合わせた設備になっているかというチェックになるです。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"たとえ１日であっても、お客さんの命と財産を預かってお泊めするのが宿泊サービスであると。ですので、それを緩和する、こうした皆さんの思いとも逆行するし、そのとおりだと思いますので、共産党はこれに反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"}]},{"id":"topic-02","title":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４４号議案 平成３０年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"心身障害者医療費助成制度システム改修について伺いたいのですが、この資料で目的のところの最後のほうに、障害者福祉システムの改修を行ってこの制度を進めていくということなのですけれども、障害者福祉システムというのは、どこにあるもので、どういうものなのか伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"委員お尋ねの障害者福祉システムは、障害者福祉課の中にございまして、主に福祉係、こちらの医療費助成制度あるいは手当等を管理しているシステムです。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして内部障害は３級までと、精神障害者保健福祉手帳１級所持者が新たに対象になったということなのですが、それぞれの人数を伺いたいです。そして、そのうち申請をみずからしてマル障を受けている人は何人かということを知りたいと思うのですが、いかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"精神障害者については、全てまとまってしまっているのですが、手帳の保持者としましては２,０７５人となっております。そのうち１級で、現在のマル障の対象者につきましては５５人の方が対象です。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今回の新たな対象の精神障害者保健福祉手帳の１級で、マル障の対象になる方が５５人。そうすると、手帳所持者はもうちょっといるということか尋ねました。","respondent":"松山障害者福祉課長","answer":"今回、１級の方が追加されますので、先ほど申した数字は２級、ほかの等級の方も含めてということになります。現在１級の方が５５人で、新たに平成３１年１月１日から開始されますので、その間に新たに申請される方が追加される可能性はあります。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"今までの１・２級の方とか、愛の手帳１・２度の方は、品川区申請ではないのですか。品川区にて受け付けられてはいないのか尋ねました。","respondent":"松山障害者福祉課長","answer":"精神の手帳の申請は各保健センターなのですけれども、今回、こちらの医療費助成制度につきましては障害者福祉課ということで、東京都からは５５人というご報告が来ています。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひマル障の受けている方の数も把握していただけたらと思うのですけれども、そうすると、今回対象になられる方は、この自己負担のところです、住民税非課税者の方は自己負担がなしですけれども、皆さん自己負担なしの方、ある方もいるのか、ここを伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"もちろん住民税課税の方は１割負担です。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"意見","question":"１割負担なのですけれども、今回の新たな対象者になる精神障害者保健福祉手帳１級の方の中で住民税課税者、要は、自己負担が発生する方はいるのかどうかということですとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"まだそこまで詳細には把握してはございません。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"確認","question":"直接本人にしっかりと周知がされたのかどうか、区は確認しているでしょうか。伺います。","respondent":"松山障害者福祉課長","answer":"こちら、補助率は１０分の１０ということで、これは東京都のほうでの補助金が一律こちらの対象の補助金を活用してくださいです。個別に周知されたのかにつきましては、東京都から個別に発送を対象者の方全員に６月中旬に周知をされているという連絡は東京都から受けております。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"障害者包括支援相談体制の構築検討についてというところで伺いたいのですけれども、今日、そこから補正にしていこうとなった理由を伺いたいのです。この補正はどういった理由で、どういう項目でというか、補正が組まれたのかを伺いたいです。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、相談支援体制は、いち早く構築する必要があるということは認識しておりました。この度、関係機関との調整の見込みが立ったというところで、いち早く相談支援体制をつくり上げるために補正を上げさせていただいた次第です。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、本予算のときはまだ関係機関との調整がついていなかった、それがついたということでの補正予算ということですね。資料のところの目的に、そういうことからではなく、地域共生社会の実現のためというところからのこの体制の構築ということの意味を説明を求めました。","respondent":"松山障害者福祉課長","answer":"高齢化が進んでいるということで、高齢者、障害者という分野を超えて一体的な相談支援が欲しいというようなお声もいただいております。いろいろな課題に対して、世帯丸ごと対応できるような形で地域の相談支援体制を目指してつくっていこうというものです。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この業者はどういったところなのか、もう決まっているのか、決まっていれば教えてほしいと求めました。これは区としてもやられているのか、区がやるべきだと思うのですけれども、そこはいかがか尋ねました。","respondent":"松山障害者福祉課長","answer":"業者につきましては、やはり高齢者、障害者それぞれの専門的知識を備えた業者に委託しようと考えております。２点目につきましては、区は全く業者に投げるわけではなくて、一緒に検討していくというものです。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どういうところなのか、どういうところなのかを、例えば言えるのであれば教えていただきたいです。","respondent":"松山障害者福祉課長","answer":"まだ本当に決まってはおりませんので、ただし、品川区の高齢者の在宅介護支援システムの実情、あるいは障害者の今の実情をきちんと踏まえてできる事業者を考えております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"やっぱりこういう評価分析、また現状把握、課題整理をしていく業者がすごく重要になってくると思うのです。そして評価検討をしていくべきだと思うのですけれども、誰が、どのように検討して出てきている補正予算なのかを伺いたいです。","respondent":"松山障害者福祉課長","answer":"こちらのイメージ図につきましては、特に業者がということではなく、区のほうできちんと部の中で、高齢と障害部門が一緒になって話し合って、こういうイメージを持って具体的にやっていきましょうというところで決まったものです。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"それがどういう形で検討して、しっかりと区の、そして課の中にはあるのか尋ねました。","respondent":"松山障害者福祉課長、石田（秀）委員長","answer":"このように障害特性に応じた支援を充実を図るとともに、平成２８年度から高齢障害ということで検討を進めてきております。それを部の中で検討したところ、やはり高齢者の在宅介護支援システムというのは… それを踏まえて、明日、正副案を出します。それはそれとしてとめるものではありませんが、この後やるということも踏まえて、ご質問していただければと思います。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"しかも、そういった検討の中身も区がしたものが私たちのもとには出てきていないわけですから。業者に投げて、そうした自立支援協議会、また当事者の皆さんとの関係での現状把握や課題整理はどのようにされているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"今はこのイメージのところにあるように、福栄会とグローと品福という３つしか実質動いていないですけれども、品川区にはあります。そうした稼働していない指定特定相談支援事業所にも、今あるのですから、その辺はどのように考えてますか尋ねました。","respondent":"松山障害者福祉課長","answer":"あるいは地域自立支援協議会の方々のご意見を聞きながら、今後、詳細については進めていこうです。実績がない民間の事業者につきましても、どのようにしたら稼働できるのかというのは働きかけていく予定です。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"２３区で最低レベルですので、ぜひ当事者、そしてこれからの自立支援協議会でもっと議論して進めていくべきではないかと思います。そうすると、この品川地区の場合も相談支援事業をする事業所はどこになるというふうなイメージなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"こんの委員","kind":"確認","question":"イメージを持つために確認をしたいと思いますけれども、１つは、今までそれぞれに対応されていたのが。そうしたときに、例えばどういうケースを想定されて、こういうことができてきたのかという確認です。","respondent":"松山障害者福祉課長","answer":"その方も要支援で、６０代の障害者のお子さんがいる、そういったケースはかなり地域には多いです。在宅介護支援センターの中で一体的な相談ができるということは、ある意味、ワンストップの相談ができるということもメリットがあります。","id":"exchange-037"},{"speaker":"こんの委員","kind":"確認","question":"もう１つが、他の自治体と少し比べたことで確認をしたいのですが、これは区として置いてある。その連携と、ここが違うというところで全国初というふうに理解していいのか、そこら辺のところをもう少し教えていただけますか尋ねました。","respondent":"松山障害者福祉課長","answer":"やはり品川区の場合、直轄で地域包括支援センターを持っているというところで、こちらの在宅介護支援システムという全国的にもないシステムです。そちらにつきましては、ほとんど前例がないです。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうか品川区に地域包括支援センターを置いているということは、課題も、しっかりそこら辺のところを集めた上でこれを進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"意見","question":"高齢ではない方がどういうふうに理解をしていくか、表現の問題なのだけれども、そこの仕切りがどうなっているか。言葉の問題なのだけれどもとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"確かに高齢者の在宅介護支援センターというところに若い方もどうなのかというところなのですが、地域の方が行きやすくなるだろうかということを考えますと、これからの検討課題の１つではあるかというふうに思っております。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"意見","question":"若い人も全て受けるという部分でいいというふうに判断したのか、それともさっきのご答弁が、ケアプランをつくるというほうに入ってしまったから、そこがどうかなとの意見を述べました。","respondent":"松山障害者福祉課長","answer":"おそらく対象像という、障害者のケアプランをつくる対象者についてのご質問だと思います。高齢者福祉課といかに在宅介護支援センターとヒアリングをし、今後、検討課題にはなってくるかと思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうことからすると、１２０人くらいが対象者になるのではないかと思うのですけれども、その確認をさせていただきたいのが１点です。１級、２級の手帳保持者数はご答弁いただいたのですけれども、そのマル障が何人ぐらいいるかという数を教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"東京都から来ているのは、おそらく更新ということ、２年ごとなので更新があるのですが、１年間のということになろうかと思います。医療費助成のことなのですが、平成２９年度末で対象者が２,５８９人、そのうち申請件数としては１,９９２人の方がご申請いただいております。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"２年目の人も対象になるということで、１２０人ぐらいが対象ということで考えていいということなのかの確認と、その仕組みだけ教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"先ほどの委員ご指摘のとおり、１２０人ぐらいが対象だです。全額東京都の負担になっております。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"わかりました。もう１つ、１,２５０万円が予算になっていますけれども、どういう内訳になっているのかということを１点お聞かせほしいと求めました。","respondent":"松山障害者福祉課長","answer":"分析のあたりで４２０万円ほど、研修体制や研修プログラムを立案するサポートもしていただきますので、それが４００万円ほどになっております。その他は成果報告書等々になっております。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"この検討事項が1)相談支援の現状把握、2)情報共有支援、3)研修・スケジュール等を含めた相談支援体制整備案の策定ですよね。相談支援員を養成していく、そういうプログラムをつくる経費が４００万円という、そういうことなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員のお尋ねのものは、東京都の養成研修、必須研修のかわりになる研修ではないのかというご質問だと思います。ただ単に在宅介護支援センターに新しい相談支援員を配置するだけで、拠点相談支援センターから相談員を派遣して研修を行うですとか、あるいは。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ということは、品川区の体制の中でどういうふうにしてスムーズにいくために研修をするかというプログラムをつくっていくのに４００万円という。〔「その前にやることがある」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"やっぱり当事者を入れた自立支援協議会などでやっていくべきなのではないかと思うのですけれども、そこら辺のところは、改めて伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"高齢障害の部分についても課題があることは認識しておりまして、平成２８年度から高齢障害のことを検討しております。研修等につきましては、先ほどのものは一事例でございまして、まだまだ詳細につきましては、これから検討を進めるという段階です。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどちょっとお伺いしたのは、団体の皆さんからも要望されていることですので、今後に向けて検討してほしいと求めました。そこら辺とのかかわり、そして相談支援部会との検討のかかわりというあたりはどうなってここになったのかというあたりを説明を求めました。","respondent":"松山障害者福祉課長","answer":"今後も自立支援協議会に参加している当事者の方、あるいは地域の方々のご意見を伺いながら、詳細については決めてまいります。こちらの相談支援体制については、相談支援部会につきましては、相談支援マニュアルの作成に向けて議論を進めていきたいと考えております。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どうあるべきなのかという、どのような要望があるのかというふうなことをしっかりと聞いていただいて、その中でどういう形を求めているか。これをどういうふうに現実のものとして実現できるかという形での、最後、お聞かせいただけたらと思います。","respondent":"永尾福祉部長","answer":"偏りのないような相談支援ができるようにしていくということを、今年度、検討するということです。今年いろいろ検討される所管事務調査という説明がございましたけれども、そういうときでの検討のご意見等を入れながら、検討して。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"心身障害者のほうのマル障の対象が広がったというのはすごく求められていたものですし、進めていくべきなのですけれども、やっぱり図が出てきていて。ですので、そうした立場から、この補正予算には反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-03","title":"第４９号議案 品川区立在宅サービスセンター条例の一部を改正する条例","agenda":"第４９号議案 品川区立在宅サービスセンター条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"特養ホームとショートステイのほうの定員の変化はあるのでしょうか。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"定員７２名ですが、特養のフロアも居ながら工事のスペースとして活用する予定がありますので、今の予定では５６名に縮小する予定です。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、７２人の特養が５６名になっていくと、１６名の方はどういう形になるのか。要は、今現在、戸越台を使われているショートステイの方が今までどおり利用したいときに利用できるような利用状況になるのかということを伺います。","respondent":"寺嶋高齢者福祉課長","answer":"この辺は全庁的にも検討したところですけれども、そう簡単に見つかるものではありませんし、最大限見積もったものが５６という数字。２年間の間、最も効率よく使えるように法人も今検討しているということで、計画上はショートは大々的には受付をすることはしないということ。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"確認","question":"行き場がなくて困るような状況はないということで確認させてください。そういうところの改修というか、そういった計画は何か組まれていたり、考えがあるのか伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"１点目、今のご利用者が困るようなことにはならないということは、それは万全を期して対応するよう、区も法人も考えているところです。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今の時点では、来年、再来年とか、近いうちに改修を予定または計画するようなところは、今のところはないということか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"福栄会の施設につきましては、既に去年、今年でやっているところです。荏原のほうは今年度から空調関係を中心に大きな工事が入るという予定はしている、今、そういう予定で進めているところです。","id":"exchange-054"}]},{"id":"topic-04","title":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第５０号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"どうしてこの第３８条が削除されて第２２条にそのまま移っていくのか、２月のところを見て、よりわかりやすい資料になるなと思うのです。税法上の特別控除がここには適用されていないのだなと思ったのですけれども、では、適用されているものは、いろいろあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"石田（ち）委員","kind":"質問","question":"３項ができたということで、この２項などは、整備していくというものになっていくのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"「努めなければならない」というふうに２項、品川区はいち早く認知症対策係という係を設置して、やっているというふうに捉えているところです。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"巡回・夜間のところで、実際にこの生活援助のみの研修課程で、品川区でも研修はされているのでしょうか。その点をお聞かせいただきたいのと、それから、今までの研修課程はどう違うのかというあたりも教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"というのも、まだ研修を実際に実施している機関が今現在存在していないので、まだこういった職種の方はいないということです。例えば介護における尊厳の保持・自立支援とか、予定では、国から示された新しい資格の研修は５９時間というふうになっておりますので。","id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"もし５９時間で生活援助のみというふうなことでの新たな資格のヘルパーができてきた場合は、総合事業の生活援助だけの方がいらっしゃいますよね。そういうところで働くというふうなことが想定されるのか、その点だけお聞かせいただけたらと思いますとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"１点目ですが、１３０時間受ければ、その後の「筆記試験による修了評価を実施すること」というふうに一応注釈では書かれております。新しい資格のほうは０.５時間、３０分程度という、示されております。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"(2)の部分ですけれども、今、定期巡回から夜間、これの区の訪問介護の方の充足率といいますか、訪問介護員は足りているか、足りていないかというところは、今、どのような感じで推移しているかだけとの意見を述べました。","respondent":"寺嶋高齢者福祉課長","answer":"実績につきましては、例えば定期巡回の実績で、平成２９年度の実利用者数としては２８名となっております。夜間対応につきましては、８５名という実人員が実績になっているということで、ケアマネとプランの中で相談して対応できているです。","id":"exchange-059"},{"speaker":"若林委員","kind":"質問・要望","question":"このサービスはまた充実をさせていくという大事な２つの事業だと思いますので、従事する方がもっと増えてほしいというのはあると思います。生活援助を受けているので、逆にまた積極的にアピールできるようなところがあれば、お知らせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"最初の研修に対して、その分を差し引いて研修を受けることが可能だというふうな書き込みをされていることが大半だと認識しておりますので。すみません、最新情報がありましたら、またお伝えしたいと思いますけれども、そのように理解しております。","id":"exchange-060"},{"speaker":"若林委員","kind":"意見","question":"私もそのようにほかの資料を見ている中で見ましたので、また一層の充実をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":47445,"voices":196}},{"id":"h30-20180702-8","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"建設委員会","time":"午前１０時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を91件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"自民党・子ども未来は、前例にのっとりまして、冒頭撮影のみということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"意見","question":"前例のとおり、頭撮りということで、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"松永副委員長","kind":"意見","question":"私たちの会派も、前例どおり、冒頭のみの撮影でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"第５５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第５５号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"いわゆる１９番地の超高層再開発が計画中なのですけれども、どういうふうに条例化されるものなのか、伺いたいというのが１点です。それと、あと、Ｄ地区の上の部分だけ、この幅が太くなっていると思うのですけれども、その理由を伺いたいと思います。","respondent":"長尾建築課長","answer":"こちらの幅につきましては、計画線から３０ｍの範囲内で、地区計画図書の中に位置づけているものと同じ内容となっております。もともとの用途地域が近隣商業地域となっておりまして、こちらの範囲と一致させることで、整合をとっているものとなっております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"１点目のほうですけれども、条例化の予定、見通しというのはどうなのかというのをお伺いします。そうしたお宅に対する支援策というのは何かあるのか、伺いたいと思います。","respondent":"長尾建築課長、東野まちづくり立体化担当課長、高梨木密整備推進課長","answer":"地区計画の中で位置づけている建物の高さの制限であるとか、容積率にかかわる制限については、条例化する予定はございません。２９号線と重複する部分につきましては、再開発の中で整備していく。そこについては、公共施設管理者負担金という形での整備を考えてあります。５ｍ台の後半、今回の拡幅で敷地面積が削られて建て替えが不可能になるお宅というものは生じないというふうに所管としては考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは別に条例で決めるというものではないということなのですか。生け垣にしていくというときに、助成制度があったかと思うのですが、その現状について改めてこの場でお伺いしたいと考えています。","respondent":"長尾建築課長、溝口公園課長","answer":"今回の５丁目１９番街区に関しましては、また、地区計画の中で制限がかかっております。今回、条例化するものにつきましては３つの制限ということで、今回は３つ制限をかけるというものになっております。 平成２９年度の実績といたしましては、４件となっておりまして、延長としては２３.５ｍやっております。長年続けている事業ですので、引き続き防災性の向上と緑化促進に向けて取り組んでいきたいと考えているものです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"高さ制限、最高限度をつけたり、そういう変更があるわけですよね。どういうところで担保されるものなのかというのがわからないので、もう少しわかりやすく教えていただけると幸いです。","respondent":"鈴木都市計画課長","answer":"今、建築課長が説明した３つについて制限として定めるものでございまして、再開発についてはまた別の都市計画で手続を踏んで進めていくというものです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"この区分けがあるのでしょうかということ、Ａ地区は、補助２９号線から飛び出たところにあるのですよね。一つの敷地を細分化して建物が建てられるという傾向があるものですから、次に、同様に制限がかかっている地域があるのか。","respondent":"高梨木密整備推進課長","answer":"説明といたしましては、戸越公園と文庫の森から一定距離の部分をまず１つの地域区分として、この紫色の地区が定められているものです。建築課のほうからご説明をしていますが、冒頭ご説明させていただいたとおり、効力を発揮しています。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"３０年、４０年までもつかどうかわかりませんが、ご理解をいただくというのは難しいところになると思うのです。なので、それに対してのお考えをほしいと求めました。","respondent":"高梨木密整備推進課長","answer":"なかなか専門的な知識がないと道路のネットワーク等を考えて線が引けないであるとか、皆さんを支援していきたいと考えております。ですので、各課題に沿ったやり方というところを、地域の現状に合わせて進めていきたいと考えております。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"要望も含めてですが、まちづくりを進めていく中で、結構簡単に道路の線を引っ張るのですよね。６０m2という制限も、やはり民地ですから、それでもうけたほうがいいよという形になってしまう可能性がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"細分化のところだけお伺いをしたいのですが、今年の３月から都市計画としては有効になっているというご説明がありましたが、お伺いをしたいと思います。","respondent":"高梨木密整備推進課長","answer":"都市計画の案の説明会ということで、同年１１月２８日に、１２２名の参加があったものです。この地区計画と補助２９号線沿道の都市計画変更、それと、戸越５丁目１９番街区の再開発に係る都市計画をあわせての説明会となっております。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"一緒に先ほどお聞きすればよかったのですけれども、その中で、細分化の防止策に関して、どちらかというと、嫌だという意見は出たのかどうか、伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"説明会の中では、６０m2に関する賛成、反対というようなストレートな意見はありませんでした。ただ、内容の一つとして、密集化を防ぐ意味での制限なのねという趣旨でのご意見ということでは、発言はあったと記憶をしています。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まさにそういうものをつくらないという趣旨ですから、私有権の大原則を曲げているわけですから、その方も説明会に出たとは言っていました。細分化はできないのですということは、これはぜひ皆さんに周知をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"高梨木密整備推進課長","answer":"品川区、まちを挙げて取り組んでいかなければいけない、そういった区民の決意のあらわれなのかなと所管としては考えております。機会を捉えて、制度の周知と、都市計画の内容の周知も行っていきたいと考えています。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"この条例が仮に成立したとして、施行はいつぐらいになるのか尋ねました。","respondent":"長尾建築課長","answer":"配付資料に記載しておりますが、施行期日は、公布の日からとしております。公布の日から、これから新しく建てる建物が施行期日以降で着工するものについては、この条例が適用されるということになります。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問・要望","question":"結構強力な私権の制限になりますので、成立後、引き続き影響のある住民に周知をぜひお願いしたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認だけさせていただきたいと思うのですけれども、今回の地区計画と同種同様な場所はどこですかという質問に対して、ご説明ほしいと求めました。","respondent":"長尾建築課長","answer":"小山台一丁目地区につきましては、新旧対照表の別表第１に記載がありますとおり、特定建築物地区整備計画という地区計画の種類になっております。先ほど同種同様のというふうなご説明をしましたところにつきましては、事例として挙げたものとなっております。","id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"この２つの意味合いを、そこのところが知りたかったもので、ご答弁をお願いしたいとの意見を述べました。","respondent":"長尾建築課長","answer":"概要としましては、地区の防災性を向上することに適している地区計画の種類となっております。防災性の部分だけに特化しておらず、いろいろな種類の制限がかけられるようなタイプの地区計画となっております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"意見","question":"商店街を削るなど、地域環境の破壊につながる２９号線を前提とし、それを推進するための超高層再開発であるＤ地区を含むものであります。賛成ができませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-03","title":"第７２号議案、専決処分の承認を求めること","agenda":"第７２号議案、専決処分の承認を求めること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"そもそも滞納が発生した状況というのですか、どのように把握しているのか、もう少し聞かせてほしいと求めました。","respondent":"森住宅課長","answer":"滞納についてですけれども、平成２１年２月１５日に、７０３号室の上の階との間で漏水事件が発生いたしました。平成２５年ですけれども、退去されるまで５万円程度の使用料を払われていたというところで、その差額が滞納使用料という形になっております。","id":"exchange-019"},{"speaker":"あくつ委員","kind":"確認","question":"裁判所から１カ月以内に訴訟を起こすよう指導があったというお話があったのですが、品川区に優先する債権があるということで通知があったというところで、それについて不存在の確認の訴訟を起こしなさいよという促しがあったということか尋ねました。","respondent":"森住宅課長","answer":"それに対して、１カ月以内に訴えを起こしてくださいと。それに対して裁判所のほうで判断しますというお話がございました。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"細かいところまでは内容がわからないのですが、これは個人的にいろいろお話を伺いたいと思います。品川区としては、一般的に詐害行為取消権のようなものでこの不存在を求めることとなったという訳ですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-04","title":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"この２つについて、会派としてもトイレの改修ということは要望をずっとしてきましたので、その上で２点ほどお伺いしたいと思います。１年ぐらいかかるのかなと思うのですけれども、この２点、お伺いしたいと思います。","respondent":"溝口公園課長","answer":"戸越台公園、この戸越銀座に近接する４カ所の公園のトイレの洋式化を図っていきたいと考えて、補正予算を組ませていただいております。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"それと、あと、小さいお子さんが座れる椅子とかはつくのかどうか。ベビーチェアというのですか、そういうものが全てにつくと期待をしているのですけれども、いかがか尋ねました。","respondent":"溝口公園課長","answer":"誰でもトイレの設置につきましては、あと、西大井の公衆便所についてはしっかりと設置して。ほかのところにつきましては、今後、詳細な設計を進めていく中で、できる限り対応していくところは対応していきたいと考えているところです。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"要望です。ほかのところも、可能であればでいいので、ぜひベビーチェアのほうは設置を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"大沢委員","kind":"確認","question":"確認だけ。誰でもトイレの中で、オストメイトの方が利用できるような環境は整っているのか尋ねました。","respondent":"溝口公園課長","answer":"誰でもトイレにつきましては、オストメイトに対応した形で整備を進めておりますので、誰でもトイレがついたところについては、オストメイトをご利用の方もご利用できるような形の整備を進めていきたいと考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"スピード感という話もありましたが、１カ所の和式トイレを洋式化する際のおおよその改修費用というのは、幾らぐらいかかるのでしょうか。それと、今後の現存する和式トイレはどうしていくおつもりなのか、区の考え方があれば、教えてほしいと求めました。","respondent":"溝口公園課長","answer":"あくまでも今回、補正で急遽組んだ予算になっておりますので、どこまで東京都が対応できるのかわからないという状況です。１００％はなかなかいかないですが、少しでも１００％に近づけるような形で、トイレの洋式化に今後も取り組んでいきたいと考えているところです。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、西大井の公衆便所は、現時点でも誰でもトイレなのか尋ねました。","respondent":"溝口公園課長","answer":"車椅子対応のところはあるのですけれども、オストメイトがついておりませんので、誰でもトイレまではいかない。あくまでも身障者対応までのトイレになっておりますので、ベビーチェアとか、誰もが使いやすい誰でもトイレの整備ができると考えているものです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"確認","question":"誰でもトイレという表示が出ているのですが、これは今回、先を見越してというあれなのですかね。その辺、後で確認をお願いします。","respondent":"溝口公園課長","answer":"私ども公園課が管理しているところでいきますと、やはりオストメイトまで対応できて、誰でもトイレとして誰もが使えるような形になります。","id":"exchange-028"},{"speaker":"松永副委員長","kind":"確認","question":"私から１点だけ確認をお願いします。この工事、来年ぐらいに工事が始まる予定ということをお伺いして、その間、仮設のトイレ等が設置される予定はあるのか、それだけ質問します。","respondent":"溝口公園課長","answer":"西大井の公衆便所につきましては、駅のトイレと兼ねているところもあります。今後設計を進めていく中で、そういったところを含めてしっかり設計を進めながら検討して、進めていきたいと考えているところです。","id":"exchange-029"}]},{"id":"topic-05","title":"平成３０年請願第１３号、都心・品川上空新飛行ルートの撤回を国交省に求める請願","agenda":"平成３０年請願第１３号、都心・品川上空新飛行ルートの撤回を国交省に求める請願","exchanges":[{"speaker":"筒井委員","kind":"質問・要望","question":"先日の一般質問において、自民党会派および公明党会派からも厳しい質問が出て、これは非常に頼もしいことだと考えております。区のほうに再三要望してきたのですけれども、この点、国から何か回答がありましたか尋ねました。","respondent":"鈴木都市計画課長","answer":"そういった具体的な内容、特に観光面での品川区内への効果というところを具体的に示してくださいという話に対しての答えは、まだ返ってきていないです。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"先日の一般質問でも、区のご答弁は、やはり経済効果はもちろんのこと、騒音対策や落下物対策についても具体策がないと。逆に、どの程度の対策の十分さだったら、区としては納得することができると言えるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"落下物に関してはゼロですが、その中身を今示すべき当事者というのが、事業を進めている国のほうです。今、これがいかに海外も含めた航空会社が取り組んで、やはりもう少し具体的に実効性の面も含めて示していただきたいというのが今の状況です。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０２０年までに８万回の発着枠拡大を実現すると述べているわけですけれども、まず伺いたいのですが、区としてはそのようにお考えでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"国に品川区に対して丁寧な説明をしていただきたいというところを再三申し上げているとおり、当然ながら、地域の不安払拭の対象が品川区であるということ、そこに住む地域の方々ということは間違いないところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"区議会公明党は、国交省に対して品川区上空を飛行しないルート案の再考を強く求めていきたいと表明されました。もう少し伺いたいのは、区としては何をどう重く受けとめたのかというのを、もう少し伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区民の方の不安というものは、今回の新ルート案を十分理解したというところには至っていないというところは、区のほうでもしっかり認識しています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう異議を唱える一歩手前というか、ほとんど異議を唱えているようなものだと思うのですが、そういう質問がありました。今のルートの再考を求めていきたいという宣言というか、そこら辺については、区はどのように重く受けとめていらっしゃるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"区民の声を重く受けとめて、あるいは議会の声を重く受けとめて、その不安解消をいかにしっかりと果たしていただけるかです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"区議会第一会派と第二会派をはじめとして表明し始めているというのは、もっと重く正面から受けとめていただきたいと思っているのです。計画の撤回を求めるということの１点求めているのですが、ぜひご意見を聞かせていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"後ほど意見があるということですかね。ご本人からも……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"安藤委員、これ、請願審査なのですけれども、それは明日所管質問でやるのですか。一般質問に関することの態度をもう一回表明しろと先ほどからおっしゃっていますけれども、そういうことなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"いかがでしょうかと、やはり一般質問で私は、ぜひご意見があれば聞かせていただきたいという思いで質問させていただいたのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問をさせていただきたいのですけれども、事実関係の確認というところで、共感する部分は確かにあります。若干事実の関係でもう一回確認をしたいのですけれども、これは所管が行革特別委員会のときにも確認をさせていただいたのですが、説明を求めました。","respondent":"鈴木都市計画課長、小林環境課長","answer":"さきの行革委員会の中でもご説明いたしましたが、年間というか、その中で羽田の不動産価値低下につながるような声はお受けしていないです。具体的に、大阪の伊丹空港のほうでも、航空機騒音の一因のみをもって… 現在６カ所、大気測定局を設置して、特に最近では改善傾向になっているというのが現状かと考えています。飛行機由来というのが大体１５０分の１程度と言われているところでございまして、今後、情報として今つかんでいるところです。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"それを間違った形で引用して、１,０００万、２,０００万下がるよという報道がありました。一般質問のときにも申し上げたのですが、これはやはり価値が下がってしまうというか、しっかりした話が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"意見","question":"ちょっと発言が遮られてしまったのですが、そういう議論の価値を下げてしまうようなことは、これは避けるべきだと私は考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問・要望","question":"それを区としてはどういう認識を持っておられるでしょうか。国交省ですから、国はそういう状況で、国政の中ではそうなってくるのでしょうけれども、東京都はどうなるのか。","respondent":"鈴木都市計画課長","answer":"やはり地域への丁寧な説明と、あるいは落下物防止対策についての具体的な取り組み、これを求めたものです。この請願の中に出ています８割以上の区民の声ですが、不安が払拭できていないという声が多いということは認識していますが、把握してございません。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、品川区としてどうするのかといったときに、もうそろそろ決断しなければいけない時期にあるのではないでしょうか。なので、それを品川区は態度としてどうするのですかという話だと思うのです。","respondent":"鈴木都市計画課長","answer":"これまで国のほうで４回の説明会、国のほうでは、第５期のフェーズの説明も行うというところは聞いてあります。質問を受けながらそれに答える教室型の説明会ですとか、これからやはりさらに区のほうでも強くこういった説明会の実施について求めていきたいです。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、この８割以上ということも本当ですかと私は思います。ならば、品川区の中での総意というものをどうやってこれからつくっていくのでしょうかという話です。","respondent":"たけうち委員長","answer":"３回目ですので、すみません。では、続けてください。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"要望になります。ここは、ただ、それを踏まえた形で、品川区の態度をどうしていくべきなのかということだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"貴重なご意見を拝聴し、また、ご答弁を伺わせていただきました。確認だけさせてほしいと求めましたけれども、国の事業なので、どのようにそのことをお考えでありますか尋ねました。","respondent":"鈴木都市計画課長","answer":"この新ルート案、機能強化の取り組みですが、これはまさに国策でございまして、最終的には、国のほうが決定をするというところだと思います。都市計画の再開発等を進めるときに、手続き上のそういったところはなく、最終的には国のほうが決定を行うです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"質問・要望","question":"一番被害をこうむる品川区ですから、３日とか２日とか短い期間ではなく、教室型説明会などをぜひ行っていただきたいと。同じような行動をとって、この問題に取り組んでいただきたいのですけれども、いかがでしょうかということ。","respondent":"鈴木都市計画課長","answer":"国のほうの検討の過程では、さまざまな内容の検討がされて、それも説明がされてあります。丁寧な説明と、段階ごとの計画の説明を受けたものでございまして、これは当然やっていきたいです。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひやっていきたいのですけれども、その点、どうお考えなのでしょうか。区民はどう感じているのかということを国に対して強くアピールするために、その点、もう一度ご答弁をお願いいたします。","respondent":"鈴木都市計画課長","answer":"その場で国のほうが説明を、やはりそこは国が検討過程も明確にして、しっかりあわせて説明していただくべき内容ではないかと考えています。教室型の説明会ですとか、あるいは区内に常設の展示説明ブースの設置ですとか、強く求めていきたいと考えています。","id":"exchange-048"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひやっていただきたいのですけれども、情報発信拠点の常設とか、教室型説明会とか、区が再三求めているにもかかわらず、やっていただけない。撤回を求める表明をせざるを得ないと私は考えているのですけれども、今後それが改まるということはあり得るのか、どうお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"区も丁寧な説明を強く今まで求めてきたわけですが、納得しかねるですので、やはり地域への説明については具体化するようにしっかり求めていきたいと。","id":"exchange-049"},{"speaker":"筒井委員","kind":"質問","question":"このままだと納得しかねるということを、国に伝えると。そういった理解でよろしいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"このままやはり何もやっていただけなければ納得できませんというのは、しっかり伝えたいと思います。その上で、丁寧な説明を具体的に行っていただける方法を国のほうで提示していただいて、実際行っていただけるように取り組んでいきたいです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"２点伺いたいのですけれども、どういう集まりで、伺いたいというのが１点です。今後２０２０年までの具体化に向けては、２０２０年の実施まであと少しなわけですから、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"それからあと、これは国のほうも説明してきているところですが、先ほどの協議会をいつ開くというようなところの具体的な話は全くございません。今、口頭で担当者レベルで聞いているのは、次のフェーズの説明会を行う予定だです。","id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"何のために集まって、どういうことを目指しているのか、そこはもう一度聞かせていただきたいというのがあります。そこだけ最後にお願いします。","respondent":"鈴木都市計画課長","answer":"何かの目的、何かに向かって、連絡会一丸となって何かを取りまとめていこうということでその会を行っているわけではございません。","id":"exchange-052"},{"speaker":"安藤委員","kind":"提案","question":"何とかしてほしいという思いが入って大変重いものですから、ぜひその理由も述べていただきたいと私は思いますし、お願いしたいと。少なくとも一致できるこの２点で、ぜひ委員長にそういった提案をしたいのですけれども、いかがか尋ねました。","respondent":"たけうち委員長","answer":"請願審査でかなりの時間をかけていて、そういう別の話をされても今すぐに決められないと思いますので、後ほど正副で検討します。自民党・子ども未来。","id":"exchange-053"},{"speaker":"大沢委員","kind":"確認","question":"請願内容の前文については、先ほど一つ一つの事象を確認させていただきました。その事実確認の上で、不安という心情に対しては、大いに共感をするところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私どもの質問の書き起こしですかね、念のため役所側の答弁を確認いたしますと、区としましても納得できるものではございません。現段階においては説明を求めていくというところでのご答弁をいただいていますので、撤回を国に求めるということ自体が、果たしてどうなのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"安藤委員","kind":"提案","question":"地元の理解を得てということを言っているわけですから、区民の皆さんの思いを受けて、しっかり区議会が表明するということが大事だと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問・要望","question":"決定機関が国であるということもありまして、新飛行ルートの撤回をということに関しては、不採択といたします。国に対して改めて教室型説明会などの周知策をとるよう要望していただきたいと考えておりますので、その辺、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"「新飛行ルートの撤回を国交省に求める請願」と書いてあるので、国交省に求めたいのですという請願なのです。これは特別委員会で、行革の中で、２年ですか、３年ですか、議論されて、今回、所管が変わりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"無視するのかどうかは最終的に国が決めることで、反対する働きかけ、撤回を求めるということ自体は認められると考えております。現時点の技術では不可能、無理なものですから、区の納得ラインではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"西本委員","kind":"意見","question":"本日結論を出すということの決定がありましたが、この趣旨というのは、非常に私は賛同するところがありますので、本来は継続的に審議をしていきたいところでありますが、採択という形でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"}]},{"id":"topic-06","title":"平成３０年陳情第９号、大森駅前住宅前駐輪場移設の具体的な検討についての陳情","agenda":"平成３０年陳情第９号、大森駅前住宅前駐輪場移設の具体的な検討についての陳情","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"その中でちょっと幾つか確認をさせていただきたいのですけれども、今回の陳情の中で、ここについてのお考えを伺いたいと思います。はそこを伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"段階的な移設の検討というよりも、それである程度の結論を出したいとは思っておりますけれども、まだそういった段階にはないということで考えております。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２点目に陳情の要旨の２番目には、そういうご要望があるのですけれども、今後利用状況についてどういう形で見きわめをされていくのか。期限とかどれぐらいのスパンでこの動きについて見ていくのか、区のお考えを伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"期間につきましては、分析をするには１年ぐらいのスパンの利用状況を勘案しなければならないと思っています。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問","question":"済みません、１年というのは何から１年ということですか。この陳情から１年ということなのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"４月２９日に大森駅水神口の駐輪場の整備が全て完了し、供用を開始していますので、そこから１年と考えています。","id":"exchange-063"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、そうするとめどとしては来年の春ぐらいには大体の状況が見えてくる。その上で、この今の移設のところについても、その分析を踏まえて考えていく、こういうことでよろしいのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"そうですね。１年ぐらいを見て、その利用状況等を踏まえてそういったことを検討していきたいと思います。","id":"exchange-064"},{"speaker":"大沢委員","kind":"質問","question":"いただいた資料の右下のほうに利用状況とありますが、その横に放置状況ということでおのおのパーセンテージが出ているわけですけれども、おおむね大体どれぐらいになったらかじを切るというような数値目標というのはおありなのか説明を求めました。","respondent":"古郡交通安全担当課長","answer":"数値については、いまだ状況の分析が終わっていませんので、数値に関してはちょっとまだお答えはできないような状況です。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"確認","question":"何回も質問して申しわけない。たしかもう５年くらいだったと思うのですけれども、これはどのタイミングで切りかわるのか、確認をさせてください。","respondent":"古郡交通安全担当課長","answer":"指定管理委託をしておりますので、５年間継続で、平成２９年度にやっておりますので、そこから５年になります。５年ごとでやっておりますので、そこでまたかわるということです。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、平成２９年度に切りかわったのですか。ちょっとごめんなさい、確認させてください。","respondent":"古郡交通安全担当課長","answer":"〔「平成２９年からか。平成２５年からではなくて」と呼ぶ者あり〕 平成２８年度に決定をしまして、平成２９年度からですので、平成２９年度から５年間指定管理者ということです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"地下式の台数ですね、2)番と3)番ということで写真が分かれていると思うのですけれども、内訳を教えてほしいと求めました。利用状況を直近のものでいいのですが、パーセンテージというのですか、それも今お伺いしたところでわかれば説明を求めました。","respondent":"古郡交通安全担当課長","answer":"当日利用については４４４台が公園を含めてとめられるような状況となっております。日立前が１３２％、全体で１６５台、全体でいきますと７４％です。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"当日だけではなくて、そちらのほうのパーセンテージは大体どれぐらいなのかと伺ったので、ちょっと後でわかれば教えてほしいと求めました。資料の右下のほうの説明で、2)番、これの理由は品川区としてはどのように分析をしているのか伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"駐輪場全体の台数ですが、先ほど説明した部分と定期利用などをあわせて１,２４７台となっております。この減少した理由というのが、平置きの駐輪場の開設に伴ってそちらのほうに流れているものだとは思ってはおります。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"１点お伺いしたいと思います。陳情にも書いているのですけれども、区としてはこれらの周辺住環境にとっての問題点についてどのように認識をしているのかもあわせてお伺いします。","respondent":"古郡交通安全担当課長","answer":"安全上に関しては、自転車が高速度で走行することで危ないということですので、パイプ柵を設置して走行抑制を図っている状況です。ですので、今後もそういった形で自転車の走行に関して広報・啓発活動を行ってまいりたいと思います。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"もう少し使いやすいように整えて、そういう環境をつくっていくということも必要なのではないかと思うのですけれども、いかがでしょうか。３点目ですが、こういうのはどういうふうに区としては影響というのですか、それを調査・把握していくお考えなのか伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"マンションの建設の動向なのですが、平成２６年４月から平成３０年６月までの間に、この南大井と勝島で２９棟、３,１８５戸ができております。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問・要望","question":"もともと一定の幅があった歩道なので、そういった行動をとる自転車もあると思うのです。ですから、ちょっとこういった区民の声と実態というのをぜひ正面から受けとめていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"西本委員","kind":"確認","question":"この陳情の中の理由の２段落目でしょうか、周辺保育園の園児たち、近くのホテルに向かう旅行者などの安全を脅かしております」という文言があります。ここに書かれているようなそういうものに関してはいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"歩道に関しては３.５ｍ以上確保しておりますので大変広くなっております。安全を脅かすというか、歩道は３.５ｍと広くなっておりますので、それについては確保されていると認識をしております。","id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"ということは、これは「脅かしております」というのは違うということの認識でよろしいでしょうか。区は、いや、そういうことではないですよという認識でよろしいか尋ねました。","respondent":"古郡交通安全担当課長","answer":"区のほうにそこが危険で看板を設置してくれだとかそういった苦情等はありませんので、そういった認識です。","id":"exchange-074"},{"speaker":"西本委員","kind":"確認","question":"それ以上に、周りの環境を見たときに、様子を見なければいけない時期というのは１年以上必要なのではないでしょうか。やはり人口の増え方を見ないとなかなかこれは撤去していいかどうかという判断にはならないのではないかと思うのですが、１年で十分か尋ねました。","respondent":"古郡交通安全担当課長","answer":"１年で判断するというのではなくて、１年間で利用状況を把握しながら今後検討していくですので、ですので１年で利用状況を見て、また人口の動向だとかそういったものを加味しながら検討していくという形になりますので、今現在では判断がつかないというような状況です。","id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"そこにとめなければいけないわけですから。あ、逆に放置自転車を促すような形になってしまうのではないかと思いますので、その辺の見立てについてはいかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"委員ご指摘のとおり、やはり放置状況だとか収容し切れない状況を生まないように、それを慎重に検討していきたい。分析をして、利用がないからといって直ちに撤去できるかというと、やはりそれは難しいのかなというところで考えております。","id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としては、個人の感性によるかもしれないのですが、美観について損なっているとお考えなのでしょうか。美観が損なわれているという区民のお声というのは入っているのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"ですので、整然と自転車が並んでいるような状況ですので、美観を損ねているという考えはございません。〔「そういう声は入っていますか」と呼ぶ者あり〕 そういった美観を損ねているという声は陳情者の方からは入っておりますが、そのほかの方から入ってはおりません。","id":"exchange-077"},{"speaker":"筒井委員","kind":"質問・要望","question":"もう一度そのあたり総合的に１年間ないし１年以上の分析でこの点もぜひ確認していっていただきたいと考えております。今区が始めているシェアサイクルがせっかくありますので、この近辺にシェアサイクルのポートをつくって、この点区はいかがお考えか尋ねました。","respondent":"今井土木管理課長","answer":"ただ、今後公園等の改修、または近隣の公有地等の確認を含めて、ぜひ駅周辺に置きたいと考えています。引き続き大森駅に限らず駅周辺のポート設置について取り組んでまいります。","id":"exchange-078"},{"speaker":"筒井委員","kind":"質問・要望","question":"いろいろ分析やシェアサイクル等ほかの代替手段とかあらゆる方法でこうした駐輪場の問題にぜひ取り組んでいっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"確認","question":"何でこういう質問をするかというと、大森駅水神口駐輪場はできたばかりですから別にそれは構わないのですが、この駐輪場をもう一回その考え方。そこからいわゆる全体の整備が一応終わったからそこから１年間見たいと、こういうことでいいのかどうか、もう一回整理させてください。","respondent":"古郡交通安全担当課長","answer":"平成２４年から変わっておりませんので、ＮＣＤ（日本コンピュータ・ダイナミクス）というところでやっておりますので、そこは変わっておりません。〔「いつまでですか」と呼ぶ者あり〕 平成２９年度から平成３３年度まで５年間となっております。１年間という期間については、４月２９日から開設をしておりまして、それから１年間ということで考えております。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"済みません、先ほど質疑の中で陳情の要旨の２番目に関連して、「歩道上以外への適切な場所への次期増設計画」というところで、民地を含め云々という話があったのですが、そこら辺がよく聞き取れなかったというのもあるのですが、もう少し教えてほしいと求めました。","respondent":"古郡交通安全担当課長","answer":"大森駅周辺については、用地がないということで、民地も含めて今後探していって検討していきたいです。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"ですから、数値なども示して近隣の状況などもきちんとしたデータもそろえて少なくとも説明する必要があるのではないかと。そうでなくても品川区としてはやはり１年なら１年と期限を区切って具体的に、説明会なのかわかりませんが、いかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"結論を先延ばしにしているわけではなくて、回答の中でも整備後の利用状況を勘案しながら十分検討していきますということですので。やはりそういったものを判断しながら、１年ぐらいは利用状況を見てどれだけ収容できるのかというところで検討してまいりたいと考えております。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"なおかつ私も伺いましたけれども、その検討結果を示してほしいと求めましたが、いかがでしょうか。再度確認したいと思います。","respondent":"古郡交通安全担当課長","answer":"１年後ということで検討はしていきたいということで考えておりますので、その状況によってその場その場で判断をしていきたいとは考えております。","id":"exchange-083"},{"speaker":"松永副委員長","kind":"質問","question":"私から１点だけなのですけれども、先ほどのご説明の中で利用状況、放置状況、安全面、今後についてそれぞれ先ほどの議論の中で理解いたしました。近隣住民の方々に対しての周知、説明等というのは今まで行われてきたのかどうかというのをお聞きしたいと思います。","respondent":"古郡交通安全担当課長","answer":"付近の住民の方に関しては、設置の段階ではある程度説明をしている、水神口に駐輪場を設置する段階では丁寧な説明を行っている状況です。整備をやりますよと住民の方々には説明をしているという状況があります。","id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"理由はいいですかちょっと。段階的にでも開始をすること」、これも今精査中ですから、まだ時期尚早であるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど答弁をお伺いしますと、１年間ぐらい状況を見てこれから分析をされるということで、これは一定の期間は必要だと思います。私どももご本人の皆様からもしっかりお話を伺いましてその思いは受けとめたつもりでありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"安藤委員","kind":"意見","question":"部分的、段階的にという意味では北側のほうなどはやはり移設というのは可能だと思いますし、妥当だと思います。これは採択をすべきものだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"松永副委員長","kind":"質問・要望","question":"理由といたしましては、放置状況では平成２７年度より若干ではありますが増加傾向にあるという分析が出ております。その中で、要望になるのですけれども、今後も近隣住民と情報共有をしっかりとしていただくようお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"理由とそれから意見ですけれども、先ほどの質問の中でも今後の動向をしっかり見ていただきたいということです。ですので、動向に合わせて、状況に合わせた形での対処を全体的にもう少し見ていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして利用状況が今後どうなるのかということ、１年ないし１年以上かかってしまうおそれがあると、今回は不採択ということにします。なるべく早い分析結果を出していただき、この住民の方々に丁寧な説明と理解を持っていただくようなご努力を何とぞよろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-07","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"６月２９日の自民党の石田秀男議員の一般質問で、計画案の一部変更をということで質問がありました。区のご答弁が、具体的にどのような配慮というのがなされるのか、どういうお考えなのかをぜひ聞かせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":62534,"voices":245}},{"id":"h30-20180702-9","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"文教委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"第４８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第４８号議案、品川区放課後児童健全育成事業の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが、数年に１回なのかはわからないのですが、提示というのはされるのですかね。更新がされていなくて、要はきちんと更新をしていますよというのを常に確認するような体制になるということなのかどうかだけ説明を求めました。","respondent":"高山子ども育成課長","answer":"この支援員になるには研修を受けていただくということになりますので、放課後児童支援員として仕事につくことができるというような類いのものです。そういう意味で申しますと更新について毎年の確認ということは、この資格においては必要がないということになります。","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"そのほかにどういう職にある方たちが対象になっているのかをちょっと確認しておきたいのと、すまいるスクール、いわゆるすまいるスクールですよね。免許状を有する者であってほしいと、当然条例がそうですから、改めてちょっとその辺の確認をしておきたいと思います。","respondent":"高山子ども育成課長","answer":"特別支援学校でありますとか、あるいは養護教諭、こういった方々もこの範囲に含まれるという解釈が示されております。当初平成２７年のこの放課後児童支援員の資格制度が発足して以降、区の職員をまず早急に受けさせるということで、区の職員については受けさせました。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれとして伺っておきたいと思うのですけれども、例えば受講料というのは、経済的にかかりますよね。そういうものが民間の方々については自己負担なのか、会社負担なのか、ちょっとそのあたりはどういうふうになるのか教えてほしいと求めました。","respondent":"高山子ども育成課長","answer":"放課後児童支援員の講習料につきましては、特に事業者の側においてそれを負担されるというような状況はございません。とはいいましても、長い目で見て放課後児童指導の質が上がるという点においては、事業者の協力は得られているという状況です。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"この平成３０年３月３０日の改正省令の第４６号の中にこれが書かれているのですけれども、これ以外のところで何か変化があるのか。「５年以上放課後児童健全育成事業に従事した者であって、これはどういうことなのか、これが影響するのかどうか説明を求めました。","respondent":"高山子ども育成課長","answer":"そうしたいわゆる中学を卒業して５年以上の経験を有する方も今後対象となっていくということは区においては妥当であろうというふうに考えているとこ…したがいまして、今回の条例改正の範囲外ではありますが、あわせて規則においても改正を予定しています。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"規則はどこを見たらわかるのでしょうか。規則も変わっていくということなのですね。","respondent":"高山子ども育成課長","answer":"今回の条例改正に合わせまして、規則においても改正いたしますので、現状においての表現とは今後変わっていくということで、条例と合わせたタイミングで施行していくというふうに考えてあります。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"提案","question":"ということで、規則も変わっていくけれども、今回提案があるのはここの条例の部分であるという説明でよろしいのですかね。はい、わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"}]},{"id":"topic-02","title":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第４４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"病児保育のところです。病児保育にかかわる基準がちょっとわからないので教えていただきたいと思うのですが、この辺の基準も大もとがあるのかどうか説明を求めました。","respondent":"佐藤保育課長","answer":"定員は８人予定ですので、看護師１人と保育士３人が必要になるです。実施スペースの関係ですが、保育室は児童１人当たり１.９８m2以上、観察室は３.３m2以上の基準があります。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なかなか今の厳しい状況の中で求められているというところで、今人員配置を伺ったら、わかっていたら説明を求めました。","respondent":"佐藤保育課長","answer":"重篤なお子さんは基本的に対象外ですので、ちょっと熱が高いとか、そういった大きなトラブルにつながったということは今のところ聞いてはおりません。お子さんは熱があるという状況で、比較的静かにしていますので、保育士の方も見守っている運営をしていると聞いております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"最後です。病児保育にかかる費用というか、保護者の負担と、あと補助のところを説明を求めました。","respondent":"佐藤保育課長","answer":"ランニングの関係だと思いますが、保護者の方が利用しましたら、１日につき２,０００円のご負担をいただいております。区からの運営事業者に対する運営支援といたしましては、保育士と看護師の人件費相当から算出してお支払いをしているところです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"次に、保育の研修のところと、事務内容の標準化のところをお伺いします。ちょっと現状がどういうふうになっていて、どう変化をするのかというのを具体的に教えていただきたいのと、ちょっとここを説明を求めました。","respondent":"佐藤保育課長","answer":"先ほどご説明いたしました国が示す８分野の研修のほうに再編して、過不足のほうを今回検討して、保育士の研修の参加と質の向上を図っていくです。専門の講師を呼んでいるというところで、この辺の体制をもって区内全部の保育園の保育士の質の維持向上を図っていくです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"今のところなのですが、右肩に大きな丸で「全保育園保育士」と書いてある、これの意味に対して行っていくという理解でいいのですか。すみません。","respondent":"佐藤保育課長","answer":"答弁がわかりにくくて申しわけありません。体制といたしましては、今ご説明した内容で、この体制をもって右に矢印がありまして、区内全部の保育園の保育士に働きかけるです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"左の８項目の内容というのは、ちょっとそこを教えていただきたいのと、その辺の思いをちょっと聞かせていただきたいのが二つ目。事務内容の標準化の委託のところなのですが、これはどういうところに、どのような対応で委託がされるのか、ちょっと中身について説明を求めました。","respondent":"佐藤保育課長","answer":"事務内容の標準化委託の内容ですが、例えば不要書類の作成をしていないかとか、むだな作業をしていないかというところを全部洗い出して検討すると。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どう集約してここに持っていっているのかというのと、これは今どうなっているのか、これとはつながっていかないものなのか説明を求めました。","respondent":"佐藤保育課長","answer":"やはり基本的にワードとかエクセルとか、給食の賄いであったり、その辺もあわせて今回の委託の中で検討していきたいと考えております。２点目のご質問のファイリングシステム等々とのつながりというところですが、そこも含めて標準化を図っていきたいと考えております。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"副園長とか、考えて組み立てていく中身で大変な部分もあるので、その辺もぜひ現場の声を入れて委託につなげていただきたいなと思うのが１点です。今伺ったら引き継がれていないというか、活かされるものにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"国のいわゆる指針に沿って８分野に再編するということですが、「のびしなプロフェッショナルスクール」というふうに銘打ってやられるわけですよね。もしそういうのがあるのであれば教えていただきたいのと、そんなに変わらなくなってしまうので、その辺はどのようになっているのか説明を求めました。","respondent":"佐藤保育課長","answer":"特別支援の関係と保護者支援、全国基準でも比較検討できますし、区としての目玉も明確に出すというところで進めていきたいと考えております。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"１分野当たり１５時間、今現状４年後とありましたけれども、そこを説明を求めました。","respondent":"佐藤保育課長","answer":"保護者支援に関しましては、１日の保護者とのかかわりであったり、さまざま課題を抱えている方に関する対応に関しても研修は行っているところです。今回、補正予算をお願いするにあたりまして、品川区としてはかなり保育士の人材育成に力を入れているというふうに認識しています。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"ちょっと病児保育について伺いたいのですけれども、全体的には１６人、そのところはちょっと意見を言っておきたいなというふうに思っています。そういう保育園の保育士、品川区の保育士の方々が、そこをどういうふうに見ているのかもあわせて伺いたいと思います。","respondent":"佐藤保育課長","answer":"不足分に関しましては、子ども・子育て計画に沿って今回補正が出ますけれども、地域バランスを考えて病児保育室の開室を進めてまいります。電算の効率化とか、さまざまな手法を使って、今後保育士の健康管理に努めていきたいと考えています。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"急な発熱だとかがありがちですから、今あるのかどうかちょっと私も不勉強でわからないのですけれども、そういう認識を持っています。そこの改善を強く求めたいと考えていますし、そういうことについて区はどういうふうに考えているのかを伺って、終わりにしたいと思います。","respondent":"佐藤保育課長","answer":"保育士の年次有給休暇の取得は７.８日というところで、今後も適切にお話を聞きながら、でき得る対策を行っていきたいと思います。部分休業をとっている職員もおりますので、その辺の休暇もあわせてどういう状況かというのを把握していきたいというふうに考えております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"年休すら７.８日しかとれないという状況は、なかなかこれは相当きつい勤務実態がある職場環境だというふうに私は思っています。子どもが豊かに育つ、豊かに育てられる、そういう状況を一日も早くつくっていただきたいということをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"平成３０年請願第１２号、大崎図書館の解体は止め、新たな図書館として再生させることを求める請願","agenda":"平成３０年請願第１２号、大崎図書館の解体は止め、新たな図書館として再生させることを求める請願","exchanges":[{"speaker":"南委員","kind":"質問","question":"改めて大崎二丁目にある大崎図書館を解体する理由、先ほど補修とか改修が追いつかないという話でしたけれども、解体する理由、そして築何年か、そのあたりを説明を求めました。","respondent":"横山品川図書館長","answer":"解体の理由と申しますか、移転の理由と申しましては、改修について補修が追いつかないということと、またＳＨＩＰへの連携です。築年数につきましては、３４年になるところです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"老朽化というふうには説明されませんでしたが、老朽化をしているということではないのですかね、その認識。築３４年ということですから、そのあたりのこと、区の認識を改めて整理したいと思いますので説明を求めました。","respondent":"横山品川図書館長","answer":"地下の書庫は修理ができないような、部品が手に入らないような状態の不具合がでて、動かないような箇所がございました。２階廊下全体が雨漏りをして、そういう意味で改修するのが難しく、移転をするほうが望ましいという結論に至ったところです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、老朽化というふうにずっと今まで説明されてきましたけれども、もう一つの理由として、２９号線、移転、これがあるのではないか。その点についてはどうなのか尋ねました。","respondent":"横山品川図書館長","answer":"先ほどからご説明しました老朽化による改修が追いつかないという部分とともに、そういう意味では、移転のチャンスだったというのも一方です。","id":"exchange-022"},{"speaker":"南委員","kind":"確認","question":"この２９号線があったのではないかと思っていて、ずっとこの間もそういう立場で質問もしてまいりまして、そこをちょっと再確認したいと思います。だから、そういう点についての認識がどうなのかと、先ほどの２９号線の関係のところの答弁をお願いしたいと思います。","respondent":"横山品川図書館長","answer":"そちらについては病院との連携で新しい図書環境が図れる見込みがあるということ、またＳＨＩＰとの連携に近接な地域であるという条件を示されました。そういう意味ではほかの地区でこのように３箇所に設けられて、結果的には恵まれた状況を確保できたものだと認識しています。","id":"exchange-023"},{"speaker":"南委員","kind":"質問","question":"ですから、教育委員会が２９号線のことを知らないで了解するということがあったとしたら、建設が始まっていったのだろうというふうに思うわけです。その点についてはどうなのか尋ねました。","respondent":"本城教育次長","answer":"２９号線の関係につきましては、認識のところも含めてですが、どういう形になるか今も協議中だということです。そういうような状況で、移転自体の理由は繰り返しになりますが、品川図書館長が説明したとおりです。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"やはり、２９号線が通ることを想定してこういう対応をとっているのではないのですか。あそこの施設はまだ残っているから、そういう判断にするべきだというふうに思うのですけれども、それはどうか尋ねました。","respondent":"本城教育次長","answer":"そういったところを総合的に判断して、教育委員会としてはかりまして、そのような形で条例の中にも大崎図書館分館も含めた形でご提案をした経緯です。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"しかも、芳水小学校のところは、上が体育館ですか。それと、こういう考え方にはならないというふうに思うので、そこについてはどういうふうに思うのかを改めて伺いたいと思います。","respondent":"横山品川図書館長","answer":"開架の、それは６月にオープンしました大崎図書館で、西口からですと２０分ぐらい歩いていただくようになるのです。図書館の環境を維持する標準というので、図書館として利用するのに不都合がないような環境は整備するようなことで工事を進めする予定です。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"申し上げたいと思いますが、そういう地域に存在していただくことが一番いいわけですから、それはそれとして図書館機能を十分果たしていただいて。張り紙１枚というのは、本当に信じられないので、それを伺いたいと思います。","respondent":"横山品川図書館長","answer":"例えば地下の書庫の改修だけでもそれ以上の金額がかかるような見込みが出てきているような状況が見られた中で、先ほど申しましたように。それぞれにご説明をさせていただいて、図書館としては精いっぱいのご説明をさせていただいた中で、このような運びになったです。","id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"最後に一言。ＳＨＩＰとの関連というのはどこをどう見て品川図書館長がおっしゃったかわからないけれども、とんでもないと、終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「平成２７年４月より大崎図書館ユーザーの会として、大崎二丁目の大崎図書館の存続を求めてお願いをしてまいりました。この辺、私はここが一番大事だなと思っているのですけれども、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"町会、各町会長には丁寧に説明させていただき、町会長のほうから会員の方にご説明をしていただくようなことをお願い申し上げたところです。解体については、区民の方へのご説明等はするような運びだというふうに聞いております。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"今行政にこの住民の方々、利用者の方々が意見を聞いてほしいというので、この議会にこの請願が出されたのですよ。何か空中を飛んでいるだけで、説得力が全くないなと思っているのですが、その辺はいかがか尋ねました。","respondent":"横山品川図書館長","answer":"分館ができて、小さいながらも小学校と連携しながら新しい展開をしていくというところで環境を保持し、前を向いていただければ非常にありがたいなと。そういうところを一緒に受けとめていただいて、次に進めればいいなと考えています。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"地方自治法第２４４条に書かれている公の施設なのですけれども、この中身をどう受けとめていらっしゃるのかなというのを今日伺いたいのです。ここの部分に私は大いに反するのが今回の品川区のやり方であると思っているのですが、この点はいかがか尋ねました。","respondent":"横山品川図書館長","answer":"山手線の内側に初めてできた施設として、住民以外の方にも喜ばれるような施設になったと思います。区としては施設を増やさないという方針に、区としての姿勢をおくみ取りいただければありがたいなと思ってあります。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりここをもう一度きちんと受けとめて、区全体で再考していってほしいと求めましたが、最後にいかがか尋ねました。","respondent":"横山品川図書館長","answer":"そういう意味では、大崎地区には３拠点というような形で品川区内の中でも図書環境としてはかなり重点を置かれたような位置づけになってあります。この中で、もう１拠点というのは、今の状況ではあまり現実的ではないと考えております。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本当にこの大崎二丁目から北品川五丁目に行くというのは大変なことなのです。この地域の活用度合い、今後のまちがどう発展していくかはわかりませんけれども、再考をぜひしていただきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"違っていたら直してほしいのですけれども、建設中の芳水小学校でしょうか、地域の方からの要望で。これが実現したというふうに伺っているのですが、間違っていないか、もう４年前の話なので説明を求めました。","respondent":"横山品川図書館長","answer":"松原傅吉さんが私財を投げ打って図書館を建てていただいたというのはすごく認識しておりますので、何とかその思いを残せないかということで。そちらについても決して忘れているわけではなく、コーナーになるかどうかはわかりませんが、できないかということで努力をしています。","id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"当然隣にあったものが１０軒先に行ったら不便になるわけですから、この３９万区民の要望をどういうふうに捉えていくかというのは行政の仕事、ただ。これは要望ですけれども、その辺は地域の方のお思いをくんでしっかり進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"いいと思うのですけれども、そういう運営で。どういう態度をとったのかについての理由、それはぜひ述べていただけるようにはからってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"渡部委員","kind":"意見","question":"それについて今後どうするかというのは、またじっくり考えていけばいいところだと思います。この請願に対しましては、本日結論を出すで不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"つる委員","kind":"提案","question":"ですから、そうした活動にも当然資する形で、機能充実ということでは一定貢献されているのかなという理解もあります。何の本を探そうかなという思いをめぐらしながら図書館に行くという楽しみをつくったらどうですかという提案をさせていただいていましたので、あるとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"意見","question":"ぜひ文化的な交流の拠点として公の施設、ここを再生してほしいという願いは、私は当然であると思っています。このことに強く抗議をして、この請願に対しては採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今まであった施設がなくなるわけですから、そこが一つのビジネス拠点となっている中での図書の連携というのは、非常にいいことなのかなと。それは要望でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これまで何年か文教委員会に所属させていただいて、こういった地域の方々のご意見を伺って、さらに行政の方の説明も伺ってきました。今後のそれぞれの運営にかかっていると思うので、ぜひ区民の皆さんの期待に応えるような運営をしていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4944#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":37511,"voices":109}},{"id":"h30-20180702-5","meetingId":"h30-cm07","date":"2018年7月2日","dateIso":"2018-07-02","committee":"総務委員会","time":"午前１０時００分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"第５８号議案、戸越台複合施設大規模改修工事請負契約、(6)第５９号議案、戸越台複合施設大規模改修機械設備工事請負契約および(7)第６０号議案…","agenda":"第５８号議案、戸越台複合施設大規模改修工事請負契約、(6)第５９号議案、戸越台複合施設大規模改修機械設備工事請負契約および(7)第６０号議案…","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"個別にどうこうという質問ではなく、入札全体に関して質問させていただきたいのですが、入札不調とか工期の遅れとかがあったのかどうなのか。工期に関して、今、既に着工されている施設もあろうかと思いますので、それも含めて、現状を教えていただきたいということで、お願いします。","respondent":"立木経理課長","answer":"その後、またそれとは別に再度入札したものが１３件ございまして、不調廃案となったものは２５件となっています。大きく遅れて工期が延びているというものは、今のところ、聞いてございません。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そうなってくると、竣工時期は決まっているわけですから、何かがあったときにはスケジュールが前倒しになってくるわけですよね。４月１日から着工できるような体制をとるということも１つの手法で、いかがですかという、２点をお伺いします。","respondent":"立木経理課長","answer":"は入札される企業が予定価格の中でどの程度見ていただけるかという部分もありますが、きっちり予定価格、工事の積算の部分の中では。余裕を持たせた工期という部分に関しましては、しっかり所管に伝えながら、契約の方も準備を進めていろいろやっていきたいと考えています。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"必ず補正予算でつけているわけですから、そこはしっかり確認をして、東京都の積算では５００万円しか見られていないと。工期の設定などそういう部分も踏まえて、健康で元気にそこの職場の業務が遂行できるように取り組んでほしいと求めましたので、要望いたします。","respondent":"立木経理課長","answer":"積算単価につきましては、きちんと市場の動向とかを見極めながら、きちんと私どものほうでしっかり検討させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"意見","question":"行政から発信していくのも、私は、必要だと思うのです。今後、そういう人たちを育ててもいかなければいけないと思うので、しっかりお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"工期が３年半ないし４年と長いだけに、契約上ではどう位置づけているのか、伺いたいと思います。もう１点、今回の手法が一番合理的だということなのかどうか、その検討経過についても伺いたいと思います。","respondent":"小林施設整備課長","answer":"それぞれが居ながら、引っ越しも含めて、いろいろな方面から、いろいろな方策、いろいろなところを検討しました。今回、工期が約４４カ月と長期にわたっていると思うのですけれども、それぞれの要望に沿って工事をまとめてきたです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"要望ですけれども、介護施設を利用されている方、また、学校等を利用されている方、保護者の方に十分理解を求めて、できるだけ影響が伴わないように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"この工事によって、減価償却というよりは、どれだけ建物自体の耐用年数が延びるのか、使えるような状況になるのか、教えてください。この建物がいつごろできたのかも、参考に説明を求めました。","respondent":"小林施設整備課長","answer":"逆に言うと、大規模改修というのは２０年ぐらいを目安にやっていく。先ほどの、２点の質問については、約２０年おきに大規模改修が望ましいです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"もう１点。３０年、４０年もちますよというような計画を立てた上で工事を行うと思うのですが、その辺について説明を求めました。","respondent":"小林施設整備課長","answer":"まずはいろいろな工事手法を検討したときに、まず一番に考えたのは、全面的な建て替えとなれば工期はもっとかかる。そういういろいろなことを検討して、最終的には居ながら工事をとったということで、このような大規模工事を選んだというところです。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"避難に対するさまざまな方策等は、完璧にできているのでしょうか。その２点だけ説明を求めました。","respondent":"小林施設整備課長","answer":"それから、避難経路、これも工事をするわけですので、それが第一の優先。避難経路ができなくて工事が着工できるかといったら、それはできませんので、避難経路を確保しながら工事をしていくです。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"どういうふうに案分して考えていくのか、基本的なところを教えていただけると、。","respondent":"小林施設整備課長","answer":"工事の案分というか、それは、共用で使っている、分けられないものについては、基本的には面積案分だとか、そういうのでやっております。学校しかないものとか、そういう分けられるものについては、基本的にはそれぞれのところに振り分けております。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"では、概ね予算を立てる段階で、案分ができる程度のところまでは詰められてから予算が立ってというふうに、いつもそういうふうに流れていくと考えてよろしいのか尋ねました。","respondent":"小林施設整備課長","answer":"面積は見積もりの段階で床面積が出ますので、共用で使っているものについては、案分で見積もり金額を出しております。先ほど言いましたが、分けられるものについては分けて、それぞれのところの科目で見積もるというところです。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"承知しているのですけれども、この段階で大体それぞれの所管でこれぐらいというざっくりした金額とか、そういうものも出せないのでしょうか。予算の点検などを考えると、そのほうが私たちの役割を果たす上でもありがたいのですけれども、いかがか尋ねました。","respondent":"小林施設整備課長","answer":"面積で案分し、それぞれの所管に返すのですけれども、基本的に分けられるものについては分けてやっていきます。ただ、今言ったように、面積案分で原則やりますので、そちらで見積もり金額を施設整備課から各所管にお知らせするというところです。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大規模な改修工事ということで、平成３４年まで工事が続きますが、工事のことで１点だけお聞きいたします。４方向、足場をどういうふうにやっていくのか、工事の搬入や運搬も含めてお知らせほしいと求めました。","respondent":"小林施設整備課長","answer":"そういうのも学校と特養と打ち合わせをしながら、工事エリアを決めて、やっていきます。いつやっていくかとか、そういうことも打ち合わせをして、今後、工事を進めていくというところです。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、平成３４年まで工事が続くわけですから、足場もずっとかけっぱなしと理解してよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"基本的に約４４カ月、特養は２フロアあきをつくって、工事期間の４４カ月というのはほとんど内部改修の時間です。外壁につきましては、４４カ月の間、足場をずっとつけるというわけではなくて、終われば当然そのときから撤去していくです。","id":"exchange-014"},{"speaker":"いながわ委員","kind":"質問・要望","question":"賛成です。ぜひ私が質問した内容を、経理課長のみならず、施設整備課長も共有の問題意識を持っていただいて、取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"第５６号議案、中小企業センター空調設備改修第二期その他機械設備工事請負契約","agenda":"第５６号議案、中小企業センター空調設備改修第二期その他機械設備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"教えていただきたいのですけれども、契約を結ぶときに、第一期と第二期に分けるときと分けないときというのは、どういう根拠に基づいているのか。先ほどの戸越台複合施設の工事は分けずに、この後の芳水小の工事は第一期、第二期と分けるのですけれども、その考え方を教えていただけますか。","respondent":"小林施設整備課長","answer":"先ほどの戸越台複合施設につきましては、関連するところがあり過ぎて、工事を分けることができませんでした。４４カ月を一連でやらないと、居ながら工事ができないという判断をしました。","id":"exchange-016"}]},{"id":"topic-03","title":"ピック・パラリンピック施設周辺道路整備工事（その１）請負契約、第６６号議案、オリンピック・パラリンピック施設周辺道路整備工事（その２）請負契約、第６７号議案…","agenda":"ピック・パラリンピック施設周辺道路整備工事（その１）請負契約、第６６号議案、オリンピック・パラリンピック施設周辺道路整備工事（その２）請負契約、第６７号議案…","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですけれども、オリンピック・パラリンピック施設周辺工事というのは、東京都からの受託事業になるのか尋ねました。","respondent":"多並道路課長","answer":"この事業の位置づけですけれども、区がみずから無電柱化事業を進めるものです。都と国の考え方で、オリンピック会場周辺の無電柱化を進めることについては、このような連携をしながら進める事業の位置づけです。","id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そのビジョンをお聞かせいただきたいなと。簡単で構わないので。","respondent":"多並道路課長","answer":"品川区として無電柱化の基本方針策定に向けた委託を行っていく予定で、この中で検討に向けて、進めているところです。今後についても、国の計画を見ながら、区として、これからの進め方について、計画を立てていきたいです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"第６５号議案の説明でありましたが、どういうことを担保するための仕組みなのか、ご説明をほしいと求めました。あわせて、第６７号議案のエレベーター設置ですけれども、随意契約となっておりますが、その理由を伺いたいと思います。","respondent":"立木経理課長","answer":"２点目の第６７号議案の契約方法についてですが、こちらは東京モノレールと協定を結んでおります。あくまでも東京モノレールの駅の部分ですので、そういったことから随意契約という形を、とらせていただいているものです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"第６７号議案のエレベーターのほうですけれども、工事そのものは必要だと考えています。それを区の工事としてやる理由について、ご説明ほしいと求めました。","respondent":"多並道路課長","answer":"私から、先ほどの補足という形でご説明します。そういう関係で、東京モノレールと協定を結んで実施することが一番妥当だろうということで、今回は随意契約とさせていただいているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"その関係性はわからなくもないのですけれども、東京モノレール自身のお金で駅を改修するのではなくて、区の工事としてやる理由が何かなと思いまして、そこを伺いたいです。","respondent":"多並道路課長","answer":"今ある駅舎に行くために東京モノレールがもともと設置しているエレベーターがありますけれども、今回のエレベーター整備につきましては。そういう内容の工事ということで、今回の契約については、区の負担分の契約としています。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"というのは、何で鈴中工業はその１を受けなかったのか。ここで外される必要があったのか疑問に思うのですが、説明を求めました。","respondent":"立木経理課長","answer":"説明が足らず、申しわけございません。先に開札があり、そちらがとれた場合には、その１が２番目なのですけれども、そちらは自動的に無効にしています。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"区としてより電線地中化をしなければいけない道路があるはずですから、やはりこれは補助金があるからこっちを優先するということなのでしょうか。説明を求めました。","respondent":"多並道路課長","answer":"もちろん先ほどご説明させていただいたオリンピック会場周辺の無電柱化が大きな目的ですけれども、防災上も非常に重要な道路となっています。優先順位、いろいろ考えながら計画を立てていきたいと思っているところです。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認をさせてほしいと求めました。ここは一括して同じ業者に対しての工事ということではなくて、別々に入札を出しているのはどうしてなのか教えていただけますか。","respondent":"多並道路課長","answer":"このような観点から、東京都でも標準的な工事の基準の期間を持っておりまして、それを踏まえ、今回の工事を計画いたしました。どうしても２分割にしないと工事が終わらないと考えまして、それで現場を２つにして、同時施工しながら進めていくという計画とさせていただきました。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"賛成なのですけれども、１つだけ要望です。結論としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問","question":"こちらの工事ですけれども、戸越台中のときは１カ所あけて特養ホームを持ってきて、また直して戻るという話がありましたけれども、こちらの荏原複合施設の場合は、こちらも居ながら工事になるのかなと思うのですが、利用者への影響に対する対応はどのように行っているのか、伺いたいと思います。","respondent":"小林施設整備課長","answer":"こちらも、居ながら工事でありますので各所管と打ち合わせをしながら、なるべく支障のないように工事を進めていくスケジュールを立てていきます。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"議案の内容とちょっと違うのですが、せっかく建物の配置図を出していただいたのですけれども、古い地図なので、平塚小学校とか平塚中学校が載っていて、せっかくいろいろ努力されているので、新しいものにかえてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"第４５号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第４５号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今回の変更で、災害派遣手当自体に何か変更があるのかどうか、その点だけ確認したいと思います。","respondent":"黒田人事課長","answer":"今回、旅館業法の改正に伴う文言修正だけですので、そのほかにつきまして改正等があるものではございません。","id":"exchange-028"}]},{"id":"topic-05","title":"第４６号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４６号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"問題があるのではないかと思うのですけれども、その点について、理由と見解を伺いたいと思います。この点については反対なのですけれども、区内ではどういう影響があるのか、伺いたいと思います。","respondent":"伊東税務課長","answer":"営業所得というところを見て拾ってみますと、大体１万人弱、９,８００人ぐらいいるのではないかと考えるところです。ということで、大体９,８００万円ぐらいの税の減が考えられるかなと考えているところです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、振りかえないと増税になってしまいますので、その意味では、こういう調整も必要なのかなとは思います。勤労世帯や中間所得層への増税となるため、この点は進めるべきではないと、意見だけ述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"中塚委員","kind":"意見","question":"５つ目の軽自動車税にかかわるものについては、品川区内に日赤の病院はありませんけれども、必要な対応だと思います。以上の点から総じて賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"}]},{"id":"topic-06","title":"議案質疑を行います。 次に、(15)の第６８号議案 防災行政無線設備更新工事請負契約","agenda":"議案質疑を行います。 次に、(15)の第６８号議案 防災行政無線設備更新工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですけれども、今年３４カ所ですが、全体では何カ所あるのか。それと、干渉し合ってしまい聞こえづらいという質問をしていると思いますが、そういう改善がきちんとされているのかどうなのか質問いたします。","respondent":"古巻防災課長","answer":"子局の数ですけれども、現在１３５局ございまして、これにつきましては全部更新をしていくという予定です。そういったことも含めて、今のところ２３局増設する方向で検討しておりますので、最終的には１５６局で運用するという予定で。","id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、お考えがあるかどうか。なければないでいいです。","respondent":"古巻防災課長","answer":"同様の考え方で個別の防災ラジオであったり、防災行政無線の音声というよりは、情報がきちんと区民の方皆様に届くような形での更新を考えていく。スピーカー自体の直接的な更新ではないですけれども、そういった周辺の技術も含めて更新をしていきたいと考えております。","id":"exchange-033"},{"speaker":"新妻副委員長","kind":"質問","question":"資料に設備数は３４カ所と書かれておりますが、前にも会派から申し上げさせていただいたことがあったと思うのですけれども、大井町の駅周辺は、人が多く集まる割には聞こえにくいという課題があるのかなと思っておりまして、この大井町駅周辺の聞こえにくさの改善は、いつの段階でされるのか尋ねました。","respondent":"古巻防災課長","answer":"今年度新設をする場所につきましては、主に港湾部を予定しておりまして、大井町駅の入り口になるかと思いますけれども、そちらの更新については、平成３１年度の予定で、今計画を立てているところです。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年防災無線、行政無線に対しては、いろいろ区民の方から様々な要望が来ています。その時に情報をどうやって得るのだと、電源が切れてテレビも何もだめになる、私は早急に抜本的な対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-07","title":"第６９号議案 しながわ区民公園南側ゾーン改修工事請負契約および第７０号議案 しながわ区民公園水処理施設改修工事請負契約","agenda":"第６９号議案 しながわ区民公園南側ゾーン改修工事請負契約および第７０号議案 しながわ区民公園水処理施設改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"それは去年もそうでしたので、あとは水族館に訪れるお客様に対しても不便がないようにやっていただきたいと、これは要望です。私の質問の中で、その辺は何か一言あるのであれば、ほしいと求めました。","respondent":"溝口公園課長","answer":"ご意見でいただいた部分については十分配慮しながら、工事を進めていきたいと考えています。そういったものをしっかり受けとめて、工事現場内での事故がないように、しっかりと対応していきたいと考えております。","id":"exchange-036"},{"speaker":"いながわ委員","kind":"質問","question":"こういうのがあったほうがいいのではないですかというのは、予算がどうこうとかではなく、よりよい職場環境をぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"それから、さらに基本的な質問で申し訳ないです。同じく工事内容の便益設備工３基というのは、言葉の意味がわからないので、説明を求めました。","respondent":"溝口公園課長","answer":"それと、２点目の便益施設です。そういった中で手を洗ったり足を洗ったりすることができる施設を今回３基新たにつくりますので、それを工事内容に挙げさせていただいたものです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"だれでもトイレと言っておきながら、その辺についてはぜひ当事者の方たちが使えるということを確認して、進めてほしいと求めました。いや、なかなか難しいとは思ったのですが、とりあえずはまずは当事者の方たちが使いやすいような整備がきちんと行われることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"水処理施設改修工事ですが、これはたびたびやらなければいけないのかなとは思うのですが、大体何年ごとに改修工事をするようになるのですか。浄化したりするのでしょうから、さらに何年ごとにこういう大きな改修工事をするようになっているのでしょうか、説明を求めました。","respondent":"溝口公園課長","answer":"当初つくってからもう３０年以上経過しておりますので、能力が落ちてきております。今回効率化を図るためにも新しいものを思い切ってつくることと、あとポンプですとかそういった主要な機械も減らすことができたものです。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"取り換えながら、常時やっていかなくてはいけない。その辺をどれだけ費用がかかるかというのを大まかでお聞きしたのですが、わかる範囲で説明を求めました。","respondent":"溝口公園課長","answer":"そういった中で、やはり日ごろのメンテナンス、管理といったものが大切になっております。そういったものを適正にやることによって、今回新たに水施設を少しでも長期に使えるようにしていきたいと考えているものです。","id":"exchange-041"},{"speaker":"吉田委員","kind":"確認","question":"先ほどトイレの話をしながら１点聞き忘れました。それをユニバーサルベッドにしていく方向だと伺っていたので、今回の場合はどうなのでしょうか、確認させてください。","respondent":"溝口公園課長","answer":"やはり公園は開放している施設ですので、どういう形で使われるのか。様子を見ながら、また何かありましたらしながわ区民公園の管理事務所に行っていただければ対応できるようになっておりますので。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"１カ所あるからということでなく、だれでもトイレの設置の時には、ベッドはユニバーサルベッドの方向でぜひ考えてほしいと求めました。そういうことがあれば、障害者を含めて多くの人がこういうところに遊びに来るわけですから、今後の方向として考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-08","title":"第７１号議案 浜川公園改修工事請負契約","agenda":"第７１号議案 浜川公園改修工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"緑が植わっているのですけれども、ちょっと死角になるところなのかなと私は思ったので、お伺いします。それから、そういう死角があるということは、やはり公園ですから、防犯カメラ設置の考えはこの公園にあるのかないのか、わかる範囲でお願いします。","respondent":"溝口公園課長","answer":"従前は脇にネットが４本張ってあって、さらに天幕をつけて、キャッチボール場を整備していきたいと考えているものです。今後公園内での防犯カメラの設置を進めているところですので、当然改修に合わせて、防犯カメラについても整備していきたいと考えているところです。","id":"exchange-044"},{"speaker":"いながわ委員","kind":"質問","question":"低木・高木に関しては、死角がないようにしたほうがいいのではないかという思いで質問させていただきました。もちろんわからないですけれども、そのキャッチボール場に設置するネットに関しても、防犯カメラも含めて全部入っているという認識でいいのか尋ねました。","respondent":"溝口公園課長","answer":"防犯カメラについては、今全体含めて公園の中での整備というのを考えておりますので、そういった中で整備をしていきたいと。もしかすると工事期間中、少し長くなりますので、その中でうまくほかの工事を入れて、防犯カメラの設置は考えていきたいと考えているところです。","id":"exchange-045"}]},{"id":"topic-09","title":"日程(8)、第６１号議案になります。第６１号議案 芳水小学校第２期校舎改築その他工事請負契約","agenda":"日程(8)、第６１号議案になります。第６１号議案 芳水小学校第２期校舎改築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"校庭の全体が人工芝となるのでしょうか。それから、人工芝は、質と価格がいろいろあると思うのですけれども、どのような判断で、どのレベルの人工芝を採用するのか説明を求めました。","respondent":"小林施設整備課長","answer":"人工芝の質は、グレード的には中ぐらい。各学校いろいろありますけれども、各学校と一緒に質を合わせてやっていますので、ここだけ高いものにはなりません。","id":"exchange-046"},{"speaker":"吉田委員","kind":"質問","question":"そういうことに対しての何か反省点というか、そういう声が活かされたとかということはないのでしょうか。あくまで同等のものでという判断をされたと理解でよろしいか尋ねました。","respondent":"小林施設整備課長","answer":"さきほど言ったように平均な質のものですけれども、当然技術革新ではありませんけれども、人工芝もその都度よくなっております。革新のためにいろいろな方法をとっていますので、その点につきましては日々変化しており、よくなっているということです。","id":"exchange-047"},{"speaker":"吉田委員","kind":"質問・要望","question":"少し安心をいたしましたが、やはり校庭を使うのは子どもたちなので、その後の使い方、契約ですからお値段のことが考慮されるのは当然なのですけれども、その辺はぜひ今後も配慮を続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"３２ページの給排水衛生設備工事で、どういう形で雨水、太陽熱が利用されるのか教えてください。それと、３５ページのほうの太陽光発電設備は何Ｋｗぐらいで、どの部分に使われるのかを説明を求めました。","respondent":"小林施設整備課長","answer":"次に、太陽光の熱給湯関係は２４m2設置する予定です。これにつきましては、各教室関係の照明の補助として使用する予定です。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークとしては大変推進したほうがいいと考えますのでよかったと思うのですけれども、２５m3というとどれぐらいなのですか。参考のために申し訳ないのですけれども、説明を求めました。","respondent":"小林施設整備課長","answer":"２５m3は、基本的には一般の教室で使えるかなというようなことだと思います。水道のほうに換えるということになるので、いわゆるどのくらい使えるのかというご質問になると、そのような感じです。","id":"exchange-050"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２６ページの本体の新校舎建築工事なのですけれども、今既存の学校の構造は、今度は新しく構造体が鉄骨造になっているというところがあるのですね。それはなぜＲＣ造からＳ造になったのかということをまずお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"地元の方とも以前から打ち合わせとかそういうのをやっているのですけれども、なるべく台数を少なくする。鉄骨、それを現場の小学校のほうに入れてそこで組み立てるというのが、台数を減らす唯一の方法であるので採用したものです。","id":"exchange-051"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"その辺のところもご留意、ご注意していただいてやっていただきたいです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"いながわ委員","kind":"質問・要望","question":"賛成でありますが、この今の議案で全て改修工事とか設備工事という説明が終わりまして、先ほど前段で午前中に私が申し上げたようなこと、工期の問題や職場環境については全てに該当するということをどうかお酌み取りいただきながら、工事を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-10","title":"平成３０年陳情第８号 同性パートナーシップの公的承認","agenda":"平成３０年陳情第８号 同性パートナーシップの公的承認","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"確認したいのですけれども、どう質問していいかもなかなか自分の中では困っているところで、誰もが参画できるようなフィールドをつくっていく。学校側というか生徒がそれを受けた時に、そういう方々もいるんだろうねという話なのか、その雰囲気がわかれば教えてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"対応指針のようなものが出ておりますので、品川区におきましては教育総合支援センターのほうで、実施されていると聞いております。私ども人権啓発課のほうではいろいろな講座等も実施しながら、区民の皆様の理解促進を進めているところです。","id":"exchange-054"},{"speaker":"いながわ委員","kind":"質問・要望","question":"は地域の中小企業の方々も含めて問題意識を共有しつつ、何かやはり調査研究というのが必要なのかなと思うのですが、その辺をどうお考えなのか。ではトイレの問題はどうするのだとか、今すぐどうこうではなくて、どうお考えか説明を求めました。","respondent":"島袋人権啓発課長","answer":"その中で、また、先生方もどのようなことがあったら人権啓発課との連携を進めてまいりたいといったことはお話しさせていただいているところです。","id":"exchange-055"},{"speaker":"いながわ委員","kind":"質問","question":"まだ全然整地されていないところで行ったとしても、おそらく頭でっかちになって終わってしまうのではないかなと。だから、しっかりＬＧＢＴ、しっかりとしたフィールドをつくることが大切なのかなというふうな思いから質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひこの品川区議会でも仕組みが始まるように、皆様には賛成をしていただきたいと初めに述べたいと思います。品川区に１点だけ伺いたいのですけれども、区には導入に向けた協議を検討していただきたいと思うのですけれども、その点はいかがなのか尋ねました。","respondent":"島袋人権啓発課長","answer":"そちらの中で、どうしていってほしいのかというようなのも、やはり策定委員会の中でも議論がいろいろと出てくると考えています。その中で、しっかりと課題を見つけて考えてまいりたいと思っているところです。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のご説明はしっかりと課題を見つけて考えていきたいということですけれども、それはこの導入に向けた協議を開始していくことに前向きに考えているという意味なのか、それとも現状においてはいわゆる課題の整理という意味なのか、もう少しご説明ほしいと求めました。","respondent":"島袋人権啓発課長","answer":"昨年１１月に実施しました調査においてもそうですけれども、まずは区民の皆様の理解が進んでいない、偏見差別があるという考え方も。むしろそのような人権に関する差別をなくしていく品川区であるということを進めてまいりたいと思っているところです。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"導入に向けた協議を開始していきたいという趣旨でのご説明なのか、それともそこにはまだたどり着いていないという意味なのか、そこを伺いたいと思います。","respondent":"榎本総務部長","answer":"要は、どのようにやっていけばいいのかということをまず手掛けていきたいと思います。最終的にこの公的承認というのが一番いいのだというふうになれば、それはその導入に向けた手順をまた踏んでいくという形になるかと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"社会をつくるための必要な取組み」の中で、１番は教育現場での啓発活動など配慮、２番目が社会制度の見直しと書かれております。そこはよく精査が必要かとは思いますけれども、品川区にもこの導入に向けた協議を開始してほしいと求めましたけれども、改めていかがか尋ねました。","respondent":"榎本総務部長","answer":"これだけを進めるというわけにはちょっといかないと考えておりまして、集めながら、まず進んでいきたいと思っています。そういった上で、本当にどの形がいいのかというのはまた研究していかなくてはいけない課題だと捉えています。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"その中で、これだけを進めるわけにはいかないというのがどういう趣旨なのか、改めて伺いたいと思います。そうした中でこの制度が求められているということはぜひ受けとめていただきたいと思うのですけれども、改めて、伺いたいと思います。","respondent":"榎本総務部長","answer":"それも含めて全体の中でちゃんと手順を整えて考えていかないと、渋谷区も制度をつくるまでに３年から５年かけて検討しておりますので、ちゃんとそういった流れをつくった上で進めてまいりたいと考えています。","id":"exchange-061"},{"speaker":"中塚委員","kind":"意見","question":"参加はちょっとというのであればアンケート調査だったり、様々な形で導入に向けた協議を開始してほしいというふうに私は受け取っております。ぜひ総務委員会の皆様には、賛成して、一緒に品川区議会としてもこの制度の背中を押していこうではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今も当然やっていただいているというのはわかっているのですけれども、改めてこれについては研究と調査もやっていただきたいです。改めてこれは議論の場を持って調査研究をしていくべきではないかと考えていますけれども、わかる範囲でいいので教えてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"初めに、本当に実態把握が難しいということと、とても私ども行政のほうにお声が届いていない部分があると。交流の場を設けたりとか、いろいろなことが始まっておりませんので、いろいろなお声を聞いていった上でスタートになるかと思っているところです。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"私は今回一般質問に入れさせていただいたので、何か私個人としては伺うまでもなく、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"子どもたちに関することであれば、「よりそいホットライン」等の電話等で対応させていただいている部分があります。先ほどの７月から始める講座ですが、こちらのほうも教育総合支援センターもしかり、そちらの先生方からのご参加もあるように伺っているところです。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問","question":"性的マイノリティに関するものもハラスメントとするということが今年の４月から始まったということですし、前向きなご答弁いただけたと思うのです。ですから、やはり区議会の中でもその機運醸成をまず取り組もうということで、これはぜひ皆様に賛成を呼びかけたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"須貝委員","kind":"意見","question":"ですけれども、やはりそっとしてほしいとか、そういう方も多数いらっしゃる。その方たちをどうやって守れるのかということが、そして今回のこの方の陳情にあるようなことを一歩一歩慎重に進めていくべきだと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"この鈴木教授のお話を聞く中で求めていることというのは、こういう人がいるということ、まずはおっしゃりたいことなのだと私は受けとめました。一方では触れないでほしいという方も事実いらっしゃいますが、そこの部分をぜひ酌んでほしいと求めましたが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"やはりＬＧＢＴの方は透明人間ではないよ、やはり偏見等を持たない、きちんとした理解をしていただくということが重要かと思います。","id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"理由としては、本来なら継続を求めたかったのですけれども、品川区の現状についての調査と研究も必要と考えております。これはまず現状をあくまで調査をしていただきたいということで、趣旨採択とすることにいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いをしたいと思います。継続でと言いたいところですが、議論を大きく進めていくためにも趣旨採択でということで、ぜひご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"中塚委員","kind":"意見","question":"先ほどそっとしてほしいとか、割とご高齢のゲイのカップルの方と、確かにその方もそっとしてほしいんだとおっしゃっていました。ちょっと余談になりましたが、結論を出すということと、採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"いながわ委員","kind":"意見","question":"非常に品川区は、これからもしっかり、やはりそれぞれがそれぞれの問題というか越えなくてはいけない課題を多分お持ちだと思うのです。我々もそれを考える一つの出発点になるのか、そういう部分にもなろうかと思いますので、趣旨採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"須貝委員","kind":"意見","question":"私も結論を出すということでお願いしたいと思います。先ほど見解を述べさせていただいたとおり、現時点では趣旨採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"吉田委員","kind":"意見","question":"そっとしておいてほしいという方がいらっしゃるのも、そのとおりだと思います。このことに限らずいわゆるマイノリティの方たちは、ぜひ声を上げてくださいと言っても、もうそっとしておいてほしいという方がいらっしゃるのですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"松澤委員","kind":"質問","question":"本日結論を出すということで、皆様方のご意見をお聞きし、また品川区の現状についての調査研究はやはり人権啓発において必要かなということで、趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"採択を主張させていただきましたが、皆さんのご意見を伺う中でこれが全会一致で決まるのであれば、趣旨採択に変更しても結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]},{"id":"topic-11","title":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"自分の質問のところでもいいでしょうか。〔「再質問すれば」との声あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問","question":"公営住宅法ではもう親族要件が外れているのですが、そのほかにも法的解釈で見解が分かれることがあるということなのでしょうか。その辺が理解できなかったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"ほかの常任委員会で、自分の質問に対してフォロー質問をすることにして、次の日に質疑を行うということは正直言うと何回もあったので。〔「ありましたか」との声あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"吉田委員","kind":"質問","question":"国の解釈はもう済んでいるはずだという再質問をいたしましたが、それに対して、改めて同じようなご答弁だったように理解しております。それが公営住宅法の親族要件以外に法の解釈が分かれるものがあるのかどうか、もしあるのでしたら説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2110#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":61615,"voices":374}},{"id":"h30-20180703-6","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"区民委員会","time":"午前１０時００分～午前１１時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"第７回 品川区・ポートランド市 青少年スポーツ交流事業","agenda":"第７回 品川区・ポートランド市 青少年スポーツ交流事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"種目が女子バスケットボールということで、最初は野球だったということなのですけれども、女子バスケットボールになった経緯などあれば伺えればと思います。","respondent":"遠藤協働・国際担当課長","answer":"野球は今まで６回全て続けてきたところなので、本当は昨年やる予定ではあったのですけれども、今年１年ずれ込んだような経緯があります。以上で、そういった形の調整の結果、バスケットボールという形になったものです。","id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですけれども、ポートランド市からの派遣で来る方たちに、うまく交流をしていきましょうねという話があるのですか。どんたくがこの時期はあったり、その辺の情報などを出しながらの交流というところでは、どのような連携をされているのか尋ねました。","respondent":"遠藤協働・国際担当課長","answer":"おおむね３回ほど、あとは、向こうで品川音頭などを踊るというような話は聞いております。は印鑑を彫るというような文化的なプログラムをこちらで用意して、そういうものを日本の文化として説明をするということで考えております。","id":"exchange-002"},{"speaker":"大倉委員","kind":"質問","question":"行った子たち、また来てもらった方たちのアンケートのような、どうだったというようなものをしているのかどうか。例えば、秋葉原がすごい、行ってみたいといったような情報をとってくるようなことを行っているのかどうかを説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"帰国報告会というのを行っておりまして、その中でいろいろと子どもたちから実際に、輪になって皆でいろいろ話を聞くという会があります。今ご意見を伺いましたので、もしアンケートなどをとれる機会があれば、考えてみたいと思います。","id":"exchange-003"},{"speaker":"大倉委員","kind":"提案","question":"まさに直接、日本のイメージというところで聞ける機会でもあるのかなと思います。これからどんどん交流が進んでいって、国際都市品川を目指す中で、１つこういったこともいいのかと思いましたので提案しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"もう１つは、議会からも要望させてもらっていて、対象国は昭和のままのような気がするのですね。なぜここまでそのままなのか、逆に言うと不自然ではないでしょうかと。","respondent":"遠藤協働・国際担当課長","answer":"今までの規模が保てているのかなというふうに思っておりますので、また改めてその数字についても逐一検討しながらやっていこうと考えています。ただ、個別にいろいろなところとの対応、そういうところで徐々に国際交流という面でやるような形でいければと考えております。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"それは何かと言うと、やはりこれがベストなのですかと。時代に即していなかったりするような気がするので、包括的になりますが、その辺のお考えを説明を求めました。","respondent":"遠藤協働・国際担当課長","answer":"１回中止になりかけたこともあり、ポートランド市との付き合いなども含めまして、いろいろと友好協会と一緒に検討していければと考えています。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問・要望","question":"要望で最後。やはりアジア圏を中心とした新規というものは検討すべきと思いますが、それを要望と兼ねてご答弁をお願いします。","respondent":"遠藤協働・国際担当課長","answer":"対象国の見直しも含めてと言うか、もっと広い見方というところでご指摘をいただきましたので、いろいろな観点でこれから考えていければと考えています。","id":"exchange-007"}]},{"id":"topic-02","title":"しながわ文化プログラム推進事業助成金","agenda":"しながわ文化プログラム推進事業助成金","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"なかなかイメージができないところもあるのでお伺いしたいのですけれども、イメージできる形でご説明ほしいと求めました。理由があれば伺いたいと思いますし、あとは区内でこの規模のイベントというのはどのくらいあるのかということで伺いたいと思います。","respondent":"立川文化観光課長","answer":"そういった意味で、いわゆる小ホールぐらいのイベントですと大体２００人以上です。こういったイベントがどれくらいあるのかというのは数字を持ち合わせておりませんので回答を控えします。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"もしほかに何か例があれば伺いたいと思います。はイベントの２００人の規模のところで、多くの文化振興を行っている団体がこの助成を受けられるのかどうかというところを伺いたいと思います。","respondent":"立川文化観光課長","answer":"１,０００人以上のホールになりますと、ですから、この２００人という目安というのは妥当な数字ではないかというところです。ただ、もっと小規模のイベントをやりたいという団体が多数あれば、最低レベルの助成額ですと５０団体が助成対象になると考えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"小ホール、２００人から３００人の規模が妥当ということでしたけれども、それはこの助成の額なども見て妥当ということなのですかね。予算額の中で今５件から５０件ということでしたけれども、この規模のイベントをやっている、広くこれが利用できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"しながわ文化プログラム推進事業負担金になるのかと思うのですけれども、その場合だと２,１００万円の予算がついていたのです。は予算の内訳を聞きたいのと、対象団体に対する審査の方法について伺いたいのですけれども、お願いします。","respondent":"立川文化観光課長","answer":"予算案を調製する段階での内訳というのは、ざっくり申しますと、金額の規模によって大体７件ぐらいの事業は予定していたところです。団体が独自に事業を実施したいという声も、１,０００万円ですが、助成金ということで事業をつくらせていただいたということです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"２０１８年、今年６月に立ち上げた文化何とかというところをもう１回教えてほしいのと。審査員はどのような方がそろっているのかというのを説明を求めました。","respondent":"立川文化観光課長","answer":"振興協議会につきましては、昨年度、今年２月の区民委員会で前課長が説明したところです。文化振興係長、オリンピック・パラリンピック担当の主査、この４名が中心になりまして審査するものです。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"なぜ今このような質問をしたかと言うと、去年９月の補正に出ていた品川区地域資源活性化事業補助制度のときに、補助金のつけ方が、事項別を見ても内訳がわからなかったり、当初予算以上のものが補正でついてしまったりということがあったので、その辺が不安で聞いてみました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡辺委員","kind":"質問","question":"助成金の２分の１の助成の意味合いを教えてほしいと求めました。その辺のお考え、望ましい形と言うのですか、想定も含めて説明を求めました。","respondent":"立川文化観光課長","answer":"もう１点の、最低の補助金額が２０万円ですので、総額４０万円以上の事業を実施するということになりますと２分の１が助成されるということですので。今回、２本立ての考え方をとり入れてしまうと混乱する場合もあるかということで、今回はシンプルな形で始めするというものです。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"意見","question":"本当に企画自体はものすごくすばらしい、タイミングと言い、地域ニーズに合っていると思います。手探りだったり、第一歩目が大事なので、しっかり支えるべき事業だと思いますので、今後の推移を見ながら弾力的に検証してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"その辺を教えてもらいたいのと、例えばこれを１回使ったら来年も使えるのかどうか、金額の考え方ですね。では１回、ああ、本当に継続できますかというところの効果をどのように測定していくのかというところを教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"実際に文化芸術活動を２年以上継続してやっている団体ということなので。事業を実施する側の負担もそれほど高くならずに、また日程の確保等についてもある程度見込めてできるのではないかと考えているところです。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"同じ事業者が、予算額が１,０００万円しかないですよね。その辺を教えていただきたいのと、この助成金のあり方は考えていくということだったので、そこだけお願いします。","respondent":"立川文化観光課長","answer":"継続して助成が受けられるかというのは、今後その辺を勘案して、区のほうでもいろいろ工夫していく必要があるかと考えています。ですから、今後につきましては、実際に申し込まれる団体と予算額の関係については、検討していく必要があるかと考えています。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"しっかりとした効果測定をしていただきたいというところがあります。その辺もしっかり、ずっと続けていくという意味ではいいのかと思いますので、その辺も留意しながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"今までイベント系と言うか文化系と言うか、そういうのに助成を出していたことがあるではないですか。宗教的もしくは政治的な宣伝を疑われるようなことがあったのか、そういうのがあったからこういうことをあえて書いたのか、教えていただけますか。","respondent":"立川文化観光課長","answer":"集会所で人を集めて何かを実施するですので、そういった会合というのが過去になされたことがあったということがあるのだと思うのですね。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"これから何かイベント系の事業に助成するときは、ほかの課のことはわからないと思うのですけれども、これを出していくのですか。「ただし宗教とか政治的な」というのを、文章でこれから出していくような方針にしていくのか尋ねました。","respondent":"立川文化観光課長","answer":"区全体としての答弁は私はできませんけれども、文化観光課所管の事業につきましては、こういった文言は助成金を交付する際には出していくということです。","id":"exchange-020"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"当然、問題はそこで大成功した上で、さらにその後をどうしていくかというのがまた１つの大きなステップになっていくのかなと思うのですね。うまくここのとこころを育てていくと言うのでしょうか、そういうような事業も、この点についても教えてほしいと求めました。","respondent":"立川文化観光課長","answer":"その後の部分ですけれども、文化芸術にかかわっている方々に対して助成していくという考え方を継続していくことを現在考えているところです。地域のイベント等、文化芸術関係の育成にかかわっている方に対する支援ですけれども。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"助成金は同じ団体が次の年も助成金を受けられるとなったときには、２分の１ではなくて何分の何になるということはあるのですか。ないのか尋ねました。","respondent":"立川文化観光課長","answer":"これは２分の１という固定で実施するものです。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"失礼しました。要綱などはこれからということなのか尋ねました。","respondent":"立川文化観光課長","answer":"実際の助成金の交付要綱というのを制定いたしまして進めてまいります。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"対象にならない主な事業というところで、「同好会等」というのがあるのですけれども、なぜこの同好会が対象にならないのかというところを伺いたいのですが、この前に書いてあるカルチャースクールというのは営利のところでそうなのかなとは思うのですけれども、この同好会について伺いたいと思います。","respondent":"立川文化観光課長","answer":"大体、そういったところでお稽古をされていて、そういった団体というのは定期的に発表会などをやったりするわけですね。同好会という名称の教室であったり、そういった団体が行う発表会等については助成はしませんよというふうに言いたいということです。","id":"exchange-024"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"渡辺委員","kind":"意見","question":"移動手段もおそらくスムーズなような気がするし、いろいろな配慮がされているので問題ないと思います。このとおり進めていただければ幸いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"屋外プール開放についてですけれども、この間も言ってきておりますけれども、伊藤学園のプール開放を求めていました。開放してほしいという声もありますので、加えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"動線上にあるプールを指定しているところでございまして、こちらは以前からやっているということで開放を行っているということです。こちらとは性質が違うところでして、現在のところは学校の夏休みの開放というところでは考えておりません。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"このプール開放についても、ぜひ伊藤学園も検討していただきたいのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"もう１つ、それから鈴ヶ森小学校というような形で、周辺にもあります。冨士見台中学校のプールというのは中学校のプールということで水深が１.１メートルから１.５メートルということで、ご理解いただければと思います。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ開放できないのか伺いたいと思います。小学生１００円ということになっておりますけれども、無料にしてほしいと求めましたが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"伊藤学園の夏季のプールですけれども、確か伊藤学園が中止になったときには、夏はとにかく暑くて利用ができないというような話があったかと思います。","id":"exchange-028"},{"speaker":"のだて委員","kind":"質問・要望","question":"今度は普通に水のプールでやるということを求めているわけですけれども、もう少し詳しく教えてほしいと求めました。いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"ロッカー代につきましても、こちらのロッカーもずっと長くもっているものでもございません。実際に買いかえ等が必要ですので、こういったことで実際に歳入とさせていただいているですので、こちらもご理解いただければと思います。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"今、ここにも書かれているように、水着がわりに着用できる紙おむつというのが出ているではないですか。その辺が、確か以前どこかで質問したと思うので、検討されているのかどうか、その辺を伺いたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"茶話会のように集まるサークルもつくっておりますので、児童センターの乳幼児のプールをご利用いただければと思います。こちらも、区のホームページの児童センターの部分にプール開放についてのご案内がそろそろ出ると思いますので、皆様にご周知いただければと思います。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"児童センターのことではなくて、しながわ区民公園の水泳場のことを伺っていて、そうすると今度は小学生以上の子が入れなかったりするのですよね。ちょっとでもプールのほうに近づくと、だめですとなってしまうという声を聞いているので、その部分なのですけれども。","respondent":"池田スポーツ推進課長","answer":"しながわ区民公園のプールは、おむつのとれていないお子様はご遠慮いただいている、これはそのルールでやっておりますので、おむつをつけている方はプールに入れないと、中にも入れないと、そういうふうにご理解いただければと思います。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問","question":"だから、子どもたちが遊泳を気軽に楽しめる機会を提供すると書かれておりますので、区民が遊泳を気軽に楽しめる機会を提供するということで。子どもたちも立派な区民の１人なので、一緒に遊べるような条件にしてほしいと思うのですけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"プールにつきましては、おむつのとれていないお子様ではなく、水泳のパンツをはいていただいて、遊んでいただくということでお願いいたします。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"プール用の紙おむつのパンツをはいていても、このプールサイドでの見学もだめということなのですか。どうなのか尋ねました。","respondent":"池田スポーツ推進課長","answer":"ルールとして、おむつのとれていないお子様はだめというふうなご理解をいただきたいと思います。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"裸でも、プールに入れません」はあるのですけれども、プールサイドには一緒に連れて行くことはできますか。どうか尋ねました。","respondent":"池田スポーツ推進課長","answer":"先ほど委員がおっしゃったように、プールサイドに控えるとか、そういうところでは構わないと思いますが、水に入るということ、これはおむつのとれていないお子様はだめということでお願いしています。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"では、確認です。ただ、水を浴びるような、キノコの形でしたか、水を浴びるところ、あそこでも子どもは浴びられないということか尋ねました。","respondent":"池田スポーツ推進課長","answer":"あくまでも、水がかかるところは遊ぶところですから、そこは当然おむつのとれていないお子さんはご遠慮いただくということです。","id":"exchange-035"},{"speaker":"田中委員","kind":"意見","question":"熱中症対策として、幼児のおむつをはいている子は、その暑いプールサイドでずっといなければいけないのかというところもあるのですね。その部分などはどのように考えておられますかとの意見を述べました。","respondent":"池田スポーツ推進課長","answer":"あくまでも、おむつがとれていない子は、水遊びは中ではできませんというふうにお願いしているところです。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"どうかその子たちも遊べるような、ここで一緒に遊べるような何かしらを検討していただきたいと思うのですが、いかがでしょうか。これから。","respondent":"池田スポーツ推進課長","answer":"現在のところ、紙おむつではプールのほうに入れないということでご理解いただければと考えています。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、関係部署との検討を、ぜひおむつがとれていない子どもがどうしたら一緒に遊べるかということも検討していただきたいと要望します。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのですが、使い方についても制限されているのかどうか教えていただきたいのと、その後の夜間の貸切などはできるのでしょうか。何かうまく面的に連動できたりするのかというところで、今後のそういった夜間の使い方という考え方があれば、教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"もう１つ、夏以外のプールの利用状況ですけれども、以前は、釣堀というものを冬の間やっておりました。これを継続するかどうかについては、継続するかどうかについては、私どものほうではわかりません。","id":"exchange-039"},{"speaker":"大倉委員","kind":"質問・要望","question":"土曜、水曜、日曜日以外というところも含めて、意見として。さまざまなスポーツの振興というところの観点も入れて、夏季以外の活用についても考えていってほしいと求めましたけれども、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"貸切時間につきましては、これから検討するような形になります。ただ、その前の実は７月５日から９日までの間、団体への貸切を行います。","id":"exchange-040"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、夏季以外の使用は公園課ということですが、うまく、目的のところでプールなのでスポーツというところで体を動かす、運動するというところで、何かそういったところの連携も踏まえて、これだけということではなく、いろいろな視点をもって連携をしていってほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"確かに承りました。","id":"exchange-041"},{"speaker":"渡辺委員","kind":"質問","question":"伺いたいのは、統一料金である理由がそれなりにあるのかなと、その辺を教えてもらえればと思います。複数回利用される方の割安感は検討がなされているのかどうか、あるいは今後含みがあるかどうか、その辺を説明を求めました。","respondent":"池田スポーツ推進課長","answer":"利用料金については、貴重品などをお持ちでない方もいらっしゃるかと思いますので、なかなか区民か区民でないかという判断が難しいところです。","id":"exchange-042"},{"speaker":"浅野副委員長","kind":"質問","question":"プールの開放ということでお伺いしたのですけれども、例えば監視員の方とか、そういう方は配置をされているのか。学校プールだとされているとは思うのですけれども、そういう事故防止の観点からどのような体制をとられているのか説明を求めました。","respondent":"池田スポーツ推進課長","answer":"監視員につきましては１日平均６人ずつ配置していますので、午前６人、午後６人という形で配置しております。そのほかに、ほかの部分での切符切りなど、そういったことで人数では多数配置しているようなところでやっております。","id":"exchange-043"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"配置はされているということで、どこにも書いていなかったので、どうされているのかなと思ったので、質問させていただきました。それは大人の人も監視をしているのかなと思うのですけれども、こちらもどのような体制で安全対策に臨まれているのか教えてほしいと求めました。","respondent":"池田スポーツ推進課長","answer":"学校プールにつきましても、地域の方が受付等をやっておりますけれども、実際のプールの中には監視員が２人ほどつくような形で配置しております。","id":"exchange-044"},{"speaker":"大倉委員","kind":"意見","question":"最後に。定期券にしたほうが区民かどうか、そういったことも考えていいのかなと思ったので、意見だけとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/374422?Template=document&Id=2814#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":26638,"voices":114}},{"id":"h30-20180703-7","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"厚生委員会","time":"午前１０時００分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"平成２９年度品川区介護保険制度の運営状況","agenda":"平成２９年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"１１ページの特別会計事業費の右の円グラフの地域支援事業について伺いたいのですが、ここに１４億９,８００万円、約１５億円が地域支援事業。１２ページ、１３ページにある総合事業の実施状況と言われる全部は、地域支援事業から出ていると考えていいのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"１１ページの地域支援事業ですけれども、内訳としましては、地域支援事業は、まず総合事業と包括的事業と任意事業と分かれております。地域包括支援センターに係る委託料等は、その２５％の包括に含まれております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"１２ページ、１３ページの四角で囲ってある、予算が３ページにあるのです。予算額が出ている、出ていないというのは、何か区別があるのかどうなのか伺いたいです。","respondent":"寺嶋高齢者福祉課長","answer":"１３ページに載っております一般介護予防事業ですけれども、これは地域支援事業の中に含まれているもので、総合事業の中の金額に入っている。資料の作成のコンセプト的に、こちらには主だったものを記載しているということで、これまで作成してきた経緯であると認識しております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"地域支援事業の７５％になっているのですけれども、委託費を出していれば、在宅介護支援センターからそういうものは上がってきていないのでしょうか。伺いたいと思います。","respondent":"寺嶋高齢者福祉課長、宮尾高齢者地域支援課長","answer":"地域包括支援センターに委託しているものの中で、件数の表示が必要なものにつきましては、きちんと報告を受けることになっております。業務につきましては、定期的な管理者会等の打ち合わせがありますので… 今日ご提示している運営状況の項目と品川区の福祉の項目との予算額の計上の仕方が必ずしも完全に一致していないところがあるのですが、一部、少し大きなくくりの中で品川区の福祉は予算額を計上させていただいてあります。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２年で時効になるというのは全体で決まっていることなのか、区として設定できる年数なのか教えていただきたい。それと、ペナルティもつけず、差し押さえもしないという姿勢はどういう考え、スタンスでおられるのか伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"公平性を担保する意味では、ある意味、必要な部分もあるという考え方も当然出てくると思います。その段階で制度の説明をきちんとして、最長２年分となるのですけれども、実際に介護が必要になった方に使っていただかないことはありません。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それを引いた数が介護プランと考えていいのかを１点、お聞かせいただきたい。そういうところは、そちらに流れる仕組みになっていると思うのですけれども、そこから民間に回す仕組みがあるのかもお聞かせほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"在宅介護支援センターの数は今は２０で、当然、おそらく介護プランをお願いしていくことがどうしても多くなってくると思います。在宅介護支援センターは基本的に予防を中心にやっていく、受けていただけるところには予防プランもお願いしているのが今の数字です。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"以前は、そういう問題が今どうなっているのかを教えてほしいと求めました。デイケアでリハビリをやりたいという要望はすごく強いと思うのですけれども、そういうところに対しては、区としてはどう考えられているのか尋ねました。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど申し上げたように在宅介護支援センターは２０ですから、キャパ的にも対応できる分が決まっておりますので、まず民間にお願いしていかないと。ＰＴ中心にいろいろリハビリ等についても検討をしておりますので、今後については検討していきたいと思います。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"包括的事業が２５％で、地域包括支援センターがここに入るということですけれども、地域包括支援センターだけで２５％になるのでしょうか。そこの財源の仕組みがどうなっているのかについても教えてほしいと求めました。","respondent":"寺嶋高齢者福祉課長","answer":"これは２０の在宅介護支援センターに地域包括の機能をお願いしているという考え方は、全てで１つの地域包括支援センターというのは再三。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それはいつからなのかも教えていただきたいのが１つです。もっと地域包括、相談にどうぞおいでください、その点もあわせてお聞かせほしいと求めました。","respondent":"大串福祉計画課長、寺嶋高齢者福祉課長","answer":"平成２８年から生活支援体制整備事業ということで、第１層の協議体あるいは第２層の協議体で支え愛の仕組みをやっている。こうしたものに介護保険会計があてられてあります。品川区の１カ所の地域包括に職種は集中しておりまして、本体から行くということで対応しているのですけれども、これは必要になります。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域包括支援センターは３職種がきちんと配置されていないと、保健師をきちんと配置して、地域包括という形にしていただきたい。配置をすることで地域包括支援センターになるのであれば、そうしていただきたいと改めて要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林委員","kind":"確認","question":"ここら辺の数字の分析はどうされているか、お聞きしたいと思うのが１つ。登録しても３分の１の方は活動していないという数字ですが、ここら辺の分析もお聞きしたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"実際活動している方が１,０８５人ということで、年数の経過とともに、実際に活動している方が減っているのは事実としてあろうかと思います。この点は真摯に受けとめて、今後の事業の参考にしてまいりたいと考えています。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"現実を見ると、登録者数に対して３分の２ぐらいだと、逆に登録者数を増やすことが必要になってくるのか。活動者数をもっと増やしたほうがいいという事業の目的とか分析とかをされていれば、参考までにお聞きします。","respondent":"宮尾高齢者地域支援課長","answer":"南大井文化センターに比べると、この事業の会場という点で見ると、これからＰＲの余地があるという分析はしています。それと、当初は積極的に参加していらした方が事業になかなか参加されなくなってくるといったところは課題として認識はさせていただいてあります。","id":"exchange-011"},{"speaker":"若林委員","kind":"意見","question":"今の１２回で４クールという表現は、1)から１３ページにかけて、全てにそういう言い方が当てはまるので、数字を見て私たちも判断する部分もあるので、実態に沿った説明が必要なところがあれば、今から直すのはあれですけれども、今、説明していただければ書き加えますとの意見を述べました。","respondent":"宮尾高齢者地域支援課長","answer":"１０回で、それを２コース設定していたら２０回というような、基本的にはその表現になっていると思うのです。今すぐ、この事業がどうなっているというところまではわかりかねますので、その辺をしっかりと見据えていきたいと考えています。","id":"exchange-012"}]},{"id":"topic-02","title":"平成２９年度品川区障害福祉計画実績","agenda":"平成２９年度品川区障害福祉計画実績","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"私たちがＰＤＣＡサイクルで、実績等は自立支援協議会では報告されているけれども、こういうところには出てきてなかったと思います。今、私たちが資料としていただいている実績、こういう形で自立支援協議会にも、毎年出ていたと考えていいのか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"昨年度は、平成２８年度版の計画の実績ということで、自立支援協議会では報告させていただきました。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"どう見てほしくてつくられたのかを感じたのです。総務省の統計局でも、これは今から直すことは可能なのか、そういう考えはあるのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"まだそのとき、平成２９年度の実績が出ていなかったので載せるのに時間がかかってしまったということで、この後のところでは載せる予定でいます。こちらは自立支援協議会といったところでも、また協議させていただければと考えています。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"対象が広がったというより、きちんと対象を広げたというところでは、こういったことの周知などはどうしていくのかを伺いたい。平成２９年度は１５０、平成３０年が５３２と大きく見込み数が増えているのですが、これはどういったことから上げられたのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"１６ページの見込み数が多いのは、今後、児童発達支援とか放課後等デイサービスの数も非常に伸びるであろうと考えております。それに伴って、また一定期間ごとにモニタリング等も行いますので、このように高い数字で書かせていただいております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"それ以上使いたい方は、お母さんたちからも、もっと放課後等デイサービスの日数を増やしてほしいという声が本当に強く寄せられてきたのです。ですので、月間と年間に分けている理由は何なのかを伺いたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"法内事業となります。日中一時は法外事業なので、それで年間の数を出しています。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"見比べたいと思ったときに、なかなかいかなかったので、何でかと思ったのですけれども、年間でないとこれは出せないものなのか。月間でも直していけるのなら検討をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"飛田障害者施策推進担当課長","answer":"委員のおっしゃるとおりです。月であらわせるところはまた整理しまして、わかりやすくしていきたいと考えております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、次の年にどうつなげるかということになってくると思うので、この実績より計画を見たほうがわかりやすいのです。これを次の年にどうつなげるかというところでは、どこで議論をされて、どれぐらい期間をかけてつくられてきたのかを伺いたいのです。","respondent":"飛田障害者施策推進担当課長","answer":"大きな変更等がありましたら、またそこでも協議して、計画の変更もありうると考えています。いずれにしても、こちらは自立支援協議会で報告をして、また委員のお話をいろいろ聞いていきたいと考えております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問","question":"Ｄ等で評価はされているのですけれども、こういうことでここを頑張ったとか、ここを改善していきたいとか。そうした評価、分析はいつごろされて、この委員会には報告していただけるのかを伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"就労継続支援Ｂ型、今回、計画に上げさせていただきました。そちらに向かって、こちらも進んでいきたいと考えております。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これだと平成２９年からさらに下がってしまうことは計画としてもどうなのかと思っているのですが、その点もお聞かせほしいと求めました。その２つの項目をお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"そういう意味では、区内にも就労継続支援Ｂ型が今後必要になるということはここでもわかることです。１つでも２つでも、そういう利用者の居場所は、近々に用地を何とかしていかなければと考えております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"2)に相談支援事業ということが書かれていて、ここの中でぜひ示していただきたいと思うのですけれども、いかがでしょうか。医療的ケアが必要な障害者の世帯にまで拡大ということもぜひご検討いただけたらと要望をしたいのですけれども、その点についても説明を求めました。","respondent":"飛田障害者施策推進担当課長","answer":"今、１０日のところを国の基準に合わせる変更は、また検討をさせていただければと思います。今後、どうしていけばいいのか、相談、検討させていただければと思います。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"続けて、平成２９年度実績で２人ということなのですが、身体の方なのか精神の方なのかも教えてほしいと求めました。平成３０年度から新たな取組みを進められるという予算であったと思うのですけれども、これの取組みの見通しも、この時点で伺っておきたいと思います。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"地域に行くには課題が多い方が非常に多くて、今すぐ移れる方は今のところ見込みがないのが現状であります。１１ページの短期入所の平成２９年度は７人、今回、下にも実績見込み量は各年度の３月の数値と書かせていただいております。平成３０年度の医療ショートの新たな取組みの進捗状況ですが、荏原病院で２名ということで、医療ショートという形にはなっております。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"何か記述されることが、先ほど都というお話がありましたけれども、区として実績に反映できる手法があるのかどうかは確認しておきたいと思います。そういうお考えがあればお聞かせいただくのと、もう１点、お聞かせほしいと求めました。","respondent":"飛田障害者施策推進担当課長、松山障害者福祉課長","answer":"大体、半分が都が言っているように、３月の実績を載せており、また、半分は平均で出しています。ただ、平均で出すほうがわかりやすいのではないかということで、これも次回の計画を立てるところでは、また検討できればと考えております。こちらは自立支援協議会の部会とは別に開かせていただきまして、そこでの協議内容につきましては、自立支援協議会の全体会で報告を随時する予定です。","id":"exchange-023"},{"speaker":"若林委員","kind":"意見","question":"保健師は当然、保健センターには一定の方がいて、大変お世話になっている実態はよく承知をしております。障害者福祉課にも専門家の配置というのは、今後のマンパワー的な部分が実際にどうしても必要になってくるという意見を申し上げて終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-03","title":"高額療養費の制度見直し","agenda":"高額療養費の制度見直し","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ここの図にある、プラスの部分の引く金額掛ける１％、これも足したのが限度額という形になるのですか。平成３０年８月からの上限額を見ると、一番上だったら２５万２,６００円プラス、掛ける１％を足したものが最終的な限度額となるのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"２５万２,６００円となっておりますが、具体的にもう少し説明いたしますと、医療費が１００万円かかったとします。今の説明ですが、８万１００円プラス７,３３０円になって、全体が８万７,４３０円になります。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"命にかかわる医療制度のセーフティネットとも言える高額療養費、これまでも切り崩されることに怒りと悲鳴が上がっている。こういった怒りと悲鳴が上がっている状況を国にぜひ伝えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"高齢者の方々にも制度の支え手として、年齢を問わず、負担能力に応じて負担をいただくことが必要と考えております。今回の見直しは、こうした観点から、負担能力に応じた負担を求めることとしています。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"細分化をされたということで、そうすると、品川区の国民健康保険に加入している７０歳以上の方が、現役並みＩ、II、III、どれぐらいの割合の方が加入されて、おおよその人数が多分あるのだろうと思うのですが、状況はどういう実態なのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"国保に関しましては、２００件程度です。しかしながら、後期高齢者医療制度に関しましては、４,６００件程度となっております。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"今、ざっと全体の数をお聞きしたのですが、区分に分けるとどれぐらいというのもわかるのか尋ねました。","respondent":"三ッ橋国保医療年金課長","answer":"なかなか区分が難しいところがございまして、区分までははっきりと申し上げられません。全体としての状況になります。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"ざっくり数字はなくても、品川区としては、そういうある一定の所得のある高齢者が多いと見ているのでしょうか。どんなふうに捉えていらっしゃいますか。","respondent":"三ッ橋国保医療年金課長","answer":"今回、所得区分はなかなか把握できません。特に後期高齢者の部分ですが、今回の見直しの制度の給付費が４８０億円の減となるので、全国的に見ますと相当な金額と考えられます。","id":"exchange-029"},{"speaker":"こんの委員","kind":"意見","question":"そうならないための健康、予防、こうした施策が必要になってくる。そこら辺は、細かいご説明なのですが、区の健康施策をどんなふうに捉えていますかとの意見を述べました。","respondent":"三ッ橋国保医療年金課長","answer":"国保医療年金課として考えられることといたしましては、４０歳以上ですけれども、国保全体を考えていくものが大事であろうと考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どういう形で値上げは決められるのか。それはどこでどういうふうに決められるのかを教えてほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"国会で国保法とか健康保険法の定めがございまして、それの改正の見直しという部分が大もとにございまして、その１つが国保の見直しとなっております。そして、第２段階目というふうに、２段階の施策となっております。","id":"exchange-031"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"多分、非課税と一般と現役並みというのはおおよそわかるのではないかと思うのですけれども、そこら辺のところを教えていただきたい。１万８,０００円という外来で、実際問題、どれぐらいあるのかもわかったら教えてほしいと求めました。","respondent":"三ッ橋国保医療年金課長","answer":"平成２９年７月に出されました健康保険法によりまして、その中に国保法施行令の一部の改正、見直しという部分があります。１万８,０００円の水準と申し上げますのは、３％を計算して、その中で直近データに当てはめた金額となっております。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２、３％の方だけが外来の上限額に適用するという考え方ですか。自然増さえも認めない、ぜひ、そこのところは国にも意見として上げていっていただきたいと私は改めて要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"住宅宿泊事業法施行後の状況","agenda":"住宅宿泊事業法施行後の状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"４４件のうちに、今、やられているところもあるので、そこの苦情なのか。法施行前と施行後、どちらの苦情なのかがわかれば教えていただきたいです。","respondent":"鈴木生活衛生課長","answer":"苦情の件数ですが、これは３月１５日に届出の準備期間が開始されてから、６月２６日現在までのものになりますので、法施行前と後がまざっています。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"わかりました。その次の届出の概要のところの建物で共同住宅２９件、一戸建て１５件ということで、住居専用地域内にあるものはあるのか尋ねました。","respondent":"鈴木生活衛生課長","answer":"住宅街もあれば、商店街に近いところもあるので、特定のエリアの偏りはないというところしか把握しておりません。ただ、前提としまして、住宅宿泊事業ですので、基本的には住宅がある場所なので、そういう意味からも、特に偏りがないと考えております。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問","question":"法施行により２００件から３００件の届出が出ると想定していたということですけれども、区内の民泊数は約６００件あったということなのですか。この文章がよくわからないのですけれども、ここの数字はどこから想定されてきて、出してきたのかをお願いいたします。","respondent":"鈴木生活衛生課長","answer":"民泊数の６００件というのは、大手の民泊の仲介サイト等で掲載されている品川区内にある物件が約６００件あったということで、分母であろうと。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"意見","question":"そうすると、これから続々と増えていく感じになっていくと思うのですけれども、違法民泊は把握されていましたか。無届けの事業者に対して指導を行うと今後の対応のところにもあるのですけれども、そういうところは把握されて、何件かわかりますかとの意見を述べました。","respondent":"鈴木生活衛生課長","answer":"住宅宿泊事業法の施行に伴ういろいろな状況の調査は６月１５日までできないということで、グレーという言い方をよくされていました。当然、法に基づく立ち入り検査の権限がありませんので、それまでしか調べることができませんでした。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"参考までにお聞きしたいのですけれども、苦情を聞いた区としては何か対応されて、処理をしたのかという状況を１つお聞きしたい。例えば、オートロックは、結局、入るのに鍵をあける人が中にいない、そういうケースはあるのか。","respondent":"鈴木生活衛生課長","answer":"１点目の苦情の対応ですが、担当者が現地へ赴きまして、まず状況の確認をいたします。住んでいる方にも説明をした上で、そこで可能ということを確認して、届出を受理しております。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"今みたいなところもきちんと届出のときに指導、こういうふうにしてくださいということは言って、なおかつ、その上であった場合には対応する体制という理解でよろしいか尋ねました。","respondent":"鈴木生活衛生課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうすると、区内に６００カ所あって、３００件が相談して、これから届出ることになると、残りの３００件は届出なしの違法民泊になるのでしょうか。そして、届出なしの違法民泊に対しては、区としてはどういう対応をされるのかについても教えてほしいと求めました。","respondent":"鈴木生活衛生課長","answer":"運営ができていないところは住宅宿泊事業法の規制もしくは罰則で対応して、指導なり営業停止、そういう処分を行います。そのどちらも、先ほど申し上げたように、警察と連携しながら対応をするというのが今後の対応の方法になると考えております。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１カ月やってみると、そこの地域が土日しかできないかどうかを区として見るわけですが、違反かどうかというのを地域を見てやるという形なのですか。ぜひ、そういう形でもつかんでほしいと求めましたけれども、その点はどうか尋ねました。","respondent":"鈴木生活衛生課長","answer":"今後、その辺の集計のとり方も工夫をしたいと考えております。土日の把握についても、今、ご質問のように、基本的には月ごとに報告が上がりますので、それで日数と曜日の確認をする形になります。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"半分近くの件数に対しての苦情と見るのか、１件で何件も、何回も、何日も集中しているのか。ここら辺の状況はどんな感じか尋ねました。","respondent":"鈴木生活衛生課長","answer":"説明が不足しておりまして、苦情の２０件は、先ほど申し上げましたように、３月１５日の準備期間からの累計です。事業者もかなり条例とかガイドラインでしっかりと制約なりを守っていただくことがあることを説明申し上げて、届出を受理していますので、今のところ。","id":"exchange-042"},{"speaker":"若林委員","kind":"意見","question":"４４件の何倍も登録されていく状況になると思いますので、引き続き、品川区は民泊を活用していただく。ただ、まちの安全、安心は品川区としては本当に絶対要件ということで、そういう方々にやっていただけるように引き続き進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"鈴木（真）委員","kind":"意見","question":"施行前にクレームがついていた、さっき言ったグレーの状態のときにいろいろなトラブル、問題が起きていたということがあります。そこが今度の申請にどの程度入ってきているのかはわかりますかとの意見を述べました。","respondent":"鈴木生活衛生課長","answer":"たしか２件ほど、以前から苦情があって、区からコンタクトをとっていたところが来ました。件数としては２件になりますけれども、今後、適正な対応をというお願いができたとは思っております。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ただ、自分は今、申請を出していたかどうかがわかっていないから、あまりそこで返事ができなかったので、確認をしました。こういうケースは、ほかはあまりないのかもしれないけれども、その辺は十分注意してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"若林委員","kind":"質問","question":"地域共生社会の実現についてで、障害者を入れた受け入れ体制、障害者を含むということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/731730?Template=document&Id=3512#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":52652,"voices":123}},{"id":"h30-20180703-8","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"建設委員会","time":"午前１０時００分～午後 ２時４２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"第一三共株式会社用地の寄付","agenda":"第一三共株式会社用地の寄付","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"協定の第４条というところで、もう少しどのような内容なのかということを教えていただきたいというのが１点です。基本的に企業ですから、第一三共側がこの地区計画からなのかわかりませんが、そういったものはどういったところがあったのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"乙所有の別添図２の土地は、建物が４月に壊し終わりまして、完了したということで寄付を受けるです。何というのでしょう、特にこの用地を寄付したから第一三共がメリットがあったなどというものではございません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、用途については平成３６年までは治水対策のために使うということなのですけれども、そういうことというのはなかなか難しいのでしょうか。そちらもあわせてお伺いします。","respondent":"稲田都市開発課長、溝口公園課長","answer":"こういう地区計画等々を進める中においてはあるですが、この土地を寄付してメリットを第一三共が受けたというようなことではございません。それから今後の公園整備等々の予定については、まだこれからというところで聞いております。公園内のどこに設置したらいいのか、さまざま検討した結果、前回の６月の委員会で場所を報告させていただいたところです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"子供の森公園は前回の議論の中でも、皆さんに親しまれているので狭くなるのはどうかという意見もあったわけです。だったらなぜ前回、複雑かどうかわかりませんけれども、なぜ同時にこれ報告はしていただけなかったのか尋ねました。","respondent":"たけうち委員長、溝口公園課長","answer":"児童相談所の設置の考え方については、またちょっと所管が違うところもあるかもしれないので。わかる範囲で結構ですのでお答えください。 児童相談所の報告の関係です。所管のほうでもいろいろ検討していく中で、そういったところさまざま探していく中で、その辺についてはご理解いただきたいと考えています。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"ですから、そこの検討というのはどのような形でされているのかということです。ただ、この土地もあるけれどもいろいろな理由があってここになりましたというような説明はできなかったのでしょうかという話です。","respondent":"溝口公園課長","answer":"ただ、やはりいろいろ検討していく中の１つの結果として、６月の委員会でご報告させていただいた、そういったところはご理解いただきたいと思います。説明の報告等、足りない部分があったのかもしれませんけれども、ご理解いただきたいと思っているところです。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"２点お伺いをします。２点目が、こちら受領した土地の状態というのがどうなっているのかというのは、現在の時点でどのように把握されていますか尋ねました。","respondent":"稲田都市開発課長","answer":"寄付でいただいて、その感謝の気持ちというところなのですが、現在、今の段階では感謝状を送るとか、そういうことは考えていないところです。今後、下水の工事、公園の工事等進んでいく中におきましては、それぞれの担当のほうで測量等、調査等をやりながら進められるものです。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと私も全てわかっているわけではないのですけれども、気持ちは示せるといいのかなと考えておりますので、ご検討いただけたらと思います。スムーズに進めていただきますよう、ぜひお願いだけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと１点だけ忘れました。ぜひ可能であればこういったところも買っていく必要があるのではないかと思いますけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"確かにここに民有地があります。ただこれを今後どうするかというのは、現段階では何も今検討していないです。","id":"exchange-007"},{"speaker":"安藤委員","kind":"意見","question":"主に学校などですと、隣に隣接した土地というのは結構購入しているケースが多いと思いますので、こちらも公園の隣ということになりますし、ぜひ情報収集も含めて検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"今回のこの寄付用地については、しばらくは下水の工事のために使うということだったのですけれども、それが終わった後も下水道の施設をずっと置くということになるのか尋ねました。","respondent":"持田河川下水道課長","answer":"この工事、基本的には下水道の工事ですので、構造物は全部地下に入る形になります。そういった立坑、建物を建てるというのは少し難しいのですけれども、それ以外のもののいろいろな使い方はできるような形で仕上げるという予定です。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"今グラウンドでなっていますけれども、今後そうなった場合は公園として、グラウンドも含めて何か一体化するような考え方は出てくるのかどうか伺いたいと思います。","respondent":"溝口公園課長","answer":"今回児童相談所、今回１,５００m2ぐらいの土地がいただけますので、面積的には変わらずに公園としては使えるような形になっております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"心配し過ぎなのかもしれない質問なのですけれども、以前に西五反田のほうの小学校跡地も土壌を掘り起こしたら汚染をされていて、１回全部土を入れ替えたということがあるのですけれども、ここは公園になるので、その辺のしっかりとした事前の調査なり、検査というのはされていますよね。","respondent":"稲田都市開発課長","answer":"何というのでしょう、異常はないというところで現在聞いております。それで、今後それぞれまた事業者が工事をやる中においては、またそういう土質の調査等をやっていかれるものと思います。","id":"exchange-011"}]},{"id":"topic-02","title":"ゆうぽうと跡地の今後の計画","agenda":"ゆうぽうと跡地の今後の計画","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"１点確認だけお願いいたします。何かもう少しわかりましたらご説明いただきたいということと、どのあたり、地元の方の声が反映された形になったのかということを説明を求めました。","respondent":"稲田都市開発課長","answer":"きゅりあんのイベントホール、イメージ的にはきゅりあんのイベントホールを思い浮かべていただければというふうに考えております。日本郵政としましてはホールは造らないというのが基本方針であったというところから入っていきながら、こういう形というところは今話をしています。","id":"exchange-012"},{"speaker":"横山委員","kind":"質問・要望","question":"ホールのほう、区のほうで借りていくという形になったということ、確認をさせていただきました。地元の方、引き続きそのハード面とソフト面と、協力してほかの課とも連携して盛り上げていっていただきたいというふうに要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、それ、この平土間式小ホール自体の話もなくなるという可能性というのはあるのでしょうか。この２点お願いします。","respondent":"稲田都市開発課長","answer":"今後にぎわい施設、いろいろな案が出てくるとは思いますが、現段階では平土間式小ホールを借りるという形で区が関係するというところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、確かに発表会があるものですから、近隣の大崎などの人でもバレエを習っている人とか結構多かったのです。ですから、そうした方々の要望というのは、今回どのように反映されていくのかというのはちょっと教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"延べ床面積が６万６,０００m2というように、階数とか、そういうところにおいてはまだ詳細は決まっていないと聞いております。そういう中におきましては、今後の歴史はまた都全体といいますか、周辺を含めまして、そういう中で考えられていくのではないかと考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"区民が使いやすい、借りやすいような体制、料金も含めてできるようにご努力いただきたいというふうに要望いたします。それと２点目は、まちづくりのビジョンを区が作成しましたが、そちらの変更修正というものがやはり行われていくものなのか説明を求めました。","respondent":"稲田都市開発課長","answer":"それから五反田駅周辺にぎわいゾーン、このゆうぽうとはにぎわい拠点として位置づけられております。日本郵政もこのにぎわい拠点ということを十分認識しておりまして、にぎわいづくりに寄与していきたいというのは郵政のほうも思っているところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"所管が違ったら指摘していただきたいのですが、それからあと２つ目が、駐輪場と駐車場がどうなっていくのか。ですから、ここの地域の全体の実情を示して考えていただけるという方向に持っていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"現段階ではそういうところで進めているです。認識ですが、それは日本郵政とも協議をしながら、適切な駐輪台数が確保できればと考えています。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、近くには五反田文化センターもあります。ここにそういう施設が必要なのかどうかというところも含めて、全体的にちょっと考えてほしいと求めましたが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"それに対しまして、今回日本郵政が計画しておりますのはフラット型というところで、平日、ウィークデーですね。私の考えですけれども、今後また詰めてはいきますけれども、そういうものも頭に置きながらやっていきたいと思っています。","id":"exchange-018"},{"speaker":"松永副委員長","kind":"提案","question":"もう１つ目が、もしまだ詳しい内容が決まっていなければぜひそういった仕切りができるような形にしていただければということを提案します。それについてのご意見も伺いたいと思いますとの意見を述べました。","respondent":"稲田都市開発課長","answer":"それからホールの間仕切り等の関係です。その辺は会議スペースにも使えるということでも考えておりますので、検討、その辺は協議していきたいと考えています。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"１つ品川区において文化芸術の施設がなくなってしまうということは非常に残念なのですけれども、採算が合わないということなのでしょうか。いま一度確認させていただきたいのと、何かこういったことで東京都がかかわってくるということはあるのか尋ねました。","respondent":"稲田都市開発課長","answer":"やはり費用対効果的な、そういうところもあって、方針的にホールはもう持たないというところだというふうに聞いております。今回の新たな平土間式をやる、やらないという中においては、特にそちらの部門との関係はないです。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問・要望","question":"今までいろいろと質問が出ているのですけれども、これ本来日本郵政のもので、議会でいろいろと、このまちづくりビジョンもいろいろとあるので要望は出ているのですが、この要望が、先方のものに対してうちのほうで物申すということで、どの辺まで要求、要望が通るものなのか、ちょっとお聞きします。","respondent":"稲田都市開発課長","answer":"先方にも納得していただきながら、いいまちをつくっていこうというところで、協議を頑張っております。","id":"exchange-021"}]},{"id":"topic-03","title":"広町地区におけるまちづくりの推進に関する協定","agenda":"広町地区におけるまちづくりの推進に関する協定","exchanges":[{"speaker":"横山委員","kind":"質問","question":"１点目が、都市機能集積ゾーンというものが１枚目の右下の図のところに、こちらはどういったものなのでしょうか。あのあたりというのは、この範囲がここに決まったというところの背景、もしございましたら教えていただけたらと思います。","respondent":"稲田都市開発課長","answer":"この検討方針の例ですが、まだ具体的にはその辺の検討が進んでいないですが、そういうものを駅近くに集積したらどうかです。今後まちづくり方針というものを、このまちづくり方針というのは現在のところ、ある程度具体化した形を表現していくというような考えではいます。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"その２０２１年以降の着工ということも、３年後の着工を目指すというふうにしているということで、何かお考えがあるのであれば伺いたいと思います。","respondent":"稲田都市開発課長","answer":"大井町のまちづくり方針、今年度末には方針をつくっていこうかとは考えております。そういうことも含めまして、この協定を結んで、さらに一歩踏み込んで今後協議をやっていこうというふうに考えています。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"提案","question":"現段階ではそう受けとめましたということなのですけれども、今後具体的にさまざまなことを私どもも提案をさせていただいて、また一緒に、もし考えさせていただけるところがあれば考えていきたい、このように考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"それをどういう手法でやるのかというか、区画整理なのか、ちょっとどんな手法を使って考えているのかということを伺いたいというのが１点です。これまで歴史的に大井プレイス構想というような構想もありましたけれども、ああいう流れとの関係というのはどのようになるのか、３点で伺います。","respondent":"稲田都市開発課長","answer":"これは基本的には大井町全体を考えながらつくるまちづくり方針というところになります。今具体的に検討していこうというようなところが中心になると思いますので、大井町全体を見据えた形の方針づくりというところになると思います。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと私もというか、その手法の中にいわゆる再開発というのですか、第一種市街地再開発事業という手法も入るのかということを確認させてください。むしろ私は、その目的の中にはこういったものを入れるべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"都市機能集積ゾーンというふうにこちら書いてありますけれども、これはあくまでも検討方針で、こういう大きなくくりですね。こういうものは検討していこうというふうになっていくものでございまして、そういうものは今後検討されていくのではないかと考えています。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと先ほど伺ったのは、例えば今の北品川五丁目の再開発も、もともと区の総合体育館があったのです。ですから、再開発という手法も検討の中に入るのですか、お聞かせ願いたいと思います。","respondent":"稲田都市開発課長","answer":"検討の中に入るか入らないかという話の中においては、チェック項目ではあるというところではありますけれども、要件があるのです。今回の今考える中では、第一種市街地再開発事業には当てはまらないというのが、我々の今検討している結果です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"本当にひとり歩きして、そういったまちになってしまうのではないかというようなことを非常に危惧しているので伺っていますが、いかがでしょうか。どういった意見集約を考えているのか伺いたいと思います。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、方針づくりにおきましても、区民の皆様等々にはお諮りをしていきたいというふうに考えております。ただ、具体的な手法、どのような形でというのはこれから詰めるところでございまして、まだ決まってはないというところです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"大事だと考えているとおっしゃっていましたので、非常に大事だと私は思うので、手法ですね。何というのですか、結ぶべきではないのではないかというふうに、意見を改めて述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"この行政機能・賑わいゾーンというところで、やはり複合施設、その点いかがでしょうかということが第２点目です。これペデストリアンデッキのようなものを考えられているのでしょうかということが３点目で、以上３点、ご答弁。","respondent":"稲田都市開発課長","answer":"補助２６号線、それから補助１６３号線、現在検討を進めているです。まちの広がりができていくかなという観点から、方針としています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"まだこれからどんどん詰めなければいけない点があると思われますけれども、ぜひ進めていってはいただきたいと考えております。バランスのよいまちづくり、新たな行政機能づくりということをぜひお考えになっていただきたいと考えていますが、この点いかがお考えか尋ねました。","respondent":"稲田都市開発課長","answer":"私どもはまちづくりの観点から、まちづくりを進めていくです。庁舎も大分古くなってきているというところにおきましては、このまちづくりに合わせながら、庁舎のあり方も検討していくところだという状況です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"概要のところに平成２５年度から共同検討を行ってきているということなのですが、５年間どういう検討がなされて、どういう状況で、今回協定書を取り交わしたいというＪＲ東日本からの申し入れがあったということなのですけれども、その経緯というものも含めて説明を求めました。","respondent":"稲田都市開発課長","answer":"平成２５年度から進められているＪＲとの共同検討です。そういう中で検討を行ってきたという状況です。","id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"もちろん公開できないものもあると思うのですが、どういう話し合いになっているのかということの経過報告というものはなされないのでしょうか。なぜなのかということです。","respondent":"稲田都市開発課長","answer":"考え方はそれぞれいろいろある中で、では進めていこうかという協定を結んで、本格的にやっていこうです。これまでの共同検討を踏まえながら、今回基本的な方針、協定を結びたいです。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"やはり区のほうとしてはいろいろな手続を考えたときに、ちょっと早過ぎるのではないかというふうな感覚を持っていないのかどうか。その辺の、そこはすごく乖離があるような気がするのですけれども、その辺の調整をどのようにされているのか、現状をちょっと説明を求めました。","respondent":"稲田都市開発課長","answer":"もっとにぎわいとか、そういうものを考えてもらわないと困りますとか、そういうやりとりをやりながらやってきたというところです。先ほども言いましたけれども、そういう中ではありますけれども、区としてもそれに沿うような形で進められればと現在のところは思っております。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり新幹線が通ってとか、ですから、やはり品川区の一番の大きなメリットをつくるための１つの大きな場所だと思うのです、ここは。みんなでつくっていくという方向に、ぜひ持っていってほしいと思いますので、これは要望として終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永副委員長","kind":"確認","question":"私からは１点だけ確認させてください。今検討段階ということなのですけれども、今の段階で、これは５対５になるのか、それとも半々ではないのか、その辺について伺いたいと思います。","respondent":"稲田都市開発課長","answer":"その点につきましてはまだ検討段階でございまして、今後詰めていくものでございまして、何とも言えないというところです。面積的にはここに示すような割合があるですが、またこの中のどの部分をどうという話にもなってきますし、その辺は今のところこれから詰めていくです。","id":"exchange-036"}]},{"id":"topic-04","title":"集団回収事業における雑がみ回収の実施","agenda":"集団回収事業における雑がみ回収の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その辺ちょっと、あのマークというのは何なのかということをお伺いしたいのが１点です。もう一つは、今回対象を広げるのは歓迎するのですけれども、広げる動機は何だったのか、２点目にお伺いします。","respondent":"工藤品川区清掃事務所長","answer":"もう一つの理由といたしましては、集団回収団体の活性化という支援で、近年新聞等古紙類の回収量が若干落ちてあります。そういった意味で、より一層の集団回収の活性化につなげてまいりたいと、このような考えで今回事業を実施したところです。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそちらも順次資源回収の対象にしていただきたいと思っているのですが、いかがでしょうか。課題など、今どういったものが課題になっているのか、あわせてお伺いできればと思います。","respondent":"工藤品川区清掃事務所長","answer":"今ご質問のプラスチック製品につきましては、まだまだ事業者責任という部分が法律の中で課されていないという現状があります。２３区清掃主管課長会、国に対しまして、事業者責任のもとで処理をしていただきたい旨の要望をしているというのが現状です。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。やはりごみを減らしていくという、引き続きそういった要望もしていただきながら、できるところから回収のほうも研究してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"結局全部の町会で取り組んでいるのでしょうかということが１つ。その中で光沢があるものなど結構入っていると思うのですけれども、それはだめなのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"いろいろと皆さん、地域の中で私どもご説明に行った場合にも悩まれているという方、素朴な疑問、質問をよく受けるです。ただし、そこの部分につきましては新聞と分けまして、このような形でしっかりとわかるような形で伝えてまいりたいというふうに考えているところです。","id":"exchange-040"},{"speaker":"西本委員","kind":"提案","question":"例えば、公園の一角を借りたいとか、集積する場所を少し収集するときに貸してもらえないかなどというような申し入れというのはないのでしょうか。そうなった場合に、やりたいのだけれども場所がないのでといった場合に、では公園の一角を何時間とかという、そういう提案などは可能なのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"極力いろいろな要望につきましては相談に応じてまいりたいと考えています。出されたものを置く場所がなくなってまいるようなところもありますし、そういった相談には応じてまいりたいというふうに考えているところです。","id":"exchange-041"}]},{"id":"topic-05","title":"オリンピック・パラリンピック施設周辺無電柱化事業に伴う道路整備等工事","agenda":"オリンピック・パラリンピック施設周辺無電柱化事業に伴う道路整備等工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"モノレールとあと京急ですか、そういう想定の中で、そういった問題というのはどのように考えているのか伺いたいと思います。メリット面とコスト面と課題について、ちょっと一般論になってしまうのかもしれないのですが、伺いたいと思います。","respondent":"多並道路課長","answer":"今回のここの会場につきましては、区としてもそれに連動して、品川区としても無電柱化を進めていきたいというような考え方があります。あわせて総合的に見た形で、区としても無電柱化を進めていくべきと考えて、今も進めているところです。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"単純に幅員が広がりまして、やはり環境としては非常によくなるという点で、必要なところはやはり順次進めていく必要があると思っているのです。あるいは池上通りと桜新道をつなぐ通りですとか、現在の区の考え方といいますか、課題等も含めてお聞かせほしいと求めました。","respondent":"多並道路課長","answer":"このような国や都の大きな財政支援もあったり、また技術的な支援がありましたので、今年度無電柱化の基本方針の策定に向けてということで。区として進めていく無電柱化を整備して、来年度以降推進計画、具体的な整備の考え方というものをまとめていきたいというのが今の考えです。","id":"exchange-043"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認です。どうせだったらもうちょっと延ばすこともできなかったのかと思うのですが、いかがか尋ねました。","respondent":"多並道路課長","answer":"ここがホッケー会場になるということが決まってから、この無電柱化をそれまでにどうやれば間に合うかということで、いろいろ検討してまいりました。","id":"exchange-044"}]},{"id":"topic-06","title":"しながわ区民公園南側ゾーンおよび水処理施設改修工事","agenda":"しながわ区民公園南側ゾーンおよび水処理施設改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"改修計画に反映されたという点は、どういう点になりますでしょうか。それと、でき得る限り自然の木というのはやはり残していったほうがいいと思うのですが、その辺の配慮のようなものはいかがか尋ねました。","respondent":"溝口公園課長","answer":"もともと今回ご意見いただいたものの中には、説明会の中でご説明した中で、しっかりご理解いただいた中で進めてきているところです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"では１点だけ伺います。入り口の前にはちょっとアーチ状のものがあったりもしたのですが、その説明会等で何かご提示をされたもの、今公表できるものがあれば説明を求めました。","respondent":"溝口公園課長","answer":"より水族館に来たという感覚が持てるようなもの、そういったものもあわせて整備していきたいと考えているところです。オープンスペースを多く設けたりとか、そういった工夫をしながら魅力向上に向けた取り組み、整備をしていきたいというふうに考えているところです。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"意見","question":"ハードだけではなくてソフトの面、そういうところも充実をすることでアプローチの魅力を増すということで、よくわかりました。いつも話していますけれども、発注するところも考えていらっしゃると思うのですが、本当にふさわしいものができ上がることを期待しておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"筒井委員","kind":"確認","question":"勝島の海を３分の２に縮小し、芝生広場を設けるということなのですけれども、これやはり結構大きな変更だと思いますが、ちょっといま一度ご答弁、前の委員会でもあったかもしれませんが、もう一度確認のために、なぜ芝生広場を設けようという理由に至ったのかという点をご説明お願いいたします。","respondent":"溝口公園課長","answer":"今回の勝島の海を３分の２に縮小するというところから少しご説明させていただきたいと思います。災害時には避難できる場所、そうしたところで使えることを考えて、今回の芝生広場の整備というものを考えたものです。","id":"exchange-048"},{"speaker":"筒井委員","kind":"質問","question":"余り設備などをたくさん置けないかもしれないのですけれども、何らかの遊具とか、そういうものは置くことになるのでしょうか。もっときれいになってほしいなと考えていますので、そのさらなる水質改善の進め方とか、何かございましたらお教えください。","respondent":"溝口公園課長","answer":"そういった形で考えておりますので、今回整備します勝島の海を埋め立ててできる芝生広場には、遊具を置くということは考えておりません。今現在開園から３０年以上経過して、または水処理の施設、よりきれいな水質の改善というものが図られるというふうに考えているところです。","id":"exchange-049"},{"speaker":"筒井委員","kind":"質問・要望","question":"この勝島の海というのも、ある意味品川区の水辺活用の１つだと思っていますので、ぜひさらなる促進を図っていってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"１つは水質がかなり改善されるということで、十分に遊べるような状況になるのでしょうかということが１つと、食事環境の改善ですね。やはり食ということをもう少しここの中にも入れていただきたいと思うのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"先ほど説明した水族館口のところのバス停の休息所のところに広場をつくって、キッチンカーをというお話をさせていただいたところです。","id":"exchange-051"}]},{"id":"topic-07","title":"浜川公園改修工事","agenda":"浜川公園改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"１点目ですけれども、基本的には全面閉鎖ということになってしまうのかどうか、ちょっと聞かせていただきたいということが１つです。近隣住民ですとか、あるいは利用者の意見の反映というのはどのようにこの場合行われたのか伺わせてください。","respondent":"溝口公園課長","answer":"浜川公園につきましては区民公園のように広くありませんので、基本的に全面閉鎖した形で工事を進めていきたいというふうに考えているところです。続きまして説明会の件です。","id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"説明会のようなものは、何か基準というものがあるのかということはお伺いしたいということが１つです。集まりなどになかなか来られない、来ていないような利用者の方々の意見というのは、具体的にどのように聞いたのかということを説明を求めました。","respondent":"溝口公園課長","answer":"説明会をやるかやらないかという１つの判断、考え方です。そういったものを説明会の中でご意見を聞きながら進めてきているという経緯がありますので、そういった中で判断して説明会の開催をしています。","id":"exchange-053"},{"speaker":"安藤委員","kind":"意見","question":"やはりさらに愛される公園になるのではないかという観点で、どのように、どういう形で意見を聞いたのかということを聞きたかったのです。町会のほうはその集まりに行ったのかどうかとか、もう一度だけお願いしますとの意見を述べました。","respondent":"溝口公園課長","answer":"そういったものも踏まえて、この４月に入ってからかなりさまざまな方から、キャッチボール場はどうするのかというご意見をいただいているところです。そういったものも踏まえて今回設計を進めてきて、今回のご報告に至ったというのが現状です。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"キャッチボール場なのですが、これは網などがあるものですか。多分子どもたちもたくさん来るだろうと思うのですけれども、その数によってはちょっと少ないかもしれないと感じているのですが、いかがか尋ねました。","respondent":"溝口公園課長","answer":"最終的には３０本ほど、また新たに新植することによって、ほぼ同数ぐらいの木が植えられるような形で今計画をしています。桜についても、引き続き桜の名所として使えるような公園というふうに、使っていただけるような整備を考えているところです。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"かなり質問等、こういうフェンスがあるところというのは、どれぐらい公園としてはあるのか尋ねました。","respondent":"溝口公園課長","answer":"すみません。品川区内２２公園、今回整備します浜川公園、そういったところでキャッチボールが楽しめる公園があります。","id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問","question":"手洗い場というものはどの辺になるのか伺いたいのと、なくなっているのかとは思うのですが、それについても伺います。よく私も通るのですが、この交差点付近のところによく自転車をとめて、その辺も含めてどう対応していくのかということについて伺いたいと思います。","respondent":"溝口公園課長","answer":"今現在の公園の中ではないような形で進めているところですが、喫煙所については考えていきたいというふうに考えているところです。今まで６台分しかとめていられなかったものが、一応１８台とめられるような計画で設計を進めて、今回ご報告させていただいているところです。","id":"exchange-057"}]},{"id":"topic-08","title":"大井町駅前パブリックスペース（公衆便所）設計コンペティション","agenda":"大井町駅前パブリックスペース（公衆便所）設計コンペティション","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"やはり広く明るくしてほしいとは思っているのですけれども、区の感じている現状の課題とあわせて、ご意見があれば伺わせてください。これが日本建築家協会が入るということになるのか、せっかくですから公募区民など入れてはいかがかと思うのですけれども、いかがか尋ねました。","respondent":"溝口公園課長","answer":"そういったものにもしっかり向き合った形での改修計画を立てて、実施に移していきたいというふうに考えているものです。改めて区民の公募等は行いませんが、どういう形で今後整備が進んでいくのか、そういったところを見ていただければと考えているところです。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回トイレということですので、区民を入れるかどうかというのは議論があるかもしれませんけれども、ぜひ今後は検討してほしいと求めました。これまであったのかというのが、あったら教えていただきたいと思うのですけれども、。","respondent":"溝口公園課長","answer":"提案内容について評価して、すぐれたその内容を選定するという形は、行政の中ではなかなかとられているところはないと考えています。ただ、いろいろ自分たちのまちづくりを今後どうしていくのか考えるのに業者を選定したり、多分まだそれほど例がないと聞いているところです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"ぜひこういった試みは今回やるということで、それを歓迎したいと思いますので、経験を踏まえた上でほかにもぜひ広げていってほしいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"西本委員","kind":"質問","question":"スペースですが、これ高さとか、面積というのは、今の現状のままでのということなのでしょうか。まち全体を見たときに何か違うのだというふうになりはしないかなという感じがあるのですけれども、いかがか尋ねました。","respondent":"溝口公園課長","answer":"審査の過程では、選定していく中で選ばれていくものについては、しっかり周辺環境にもマッチしたものができていくというふうに考えているものです。余り突飛なものができたりとか、そういうものはしないだろうというふうに想定しているものです。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"提案","question":"ネーミングライツというところで各会派から今まで提案があったと思うのですが、そのコンペの中でも提案内容の中に、自社の技術とか。そういうものを今回コンペの材料、設計プラスそういうものも提案ということは入らないのか尋ねました。","respondent":"溝口公園課長","answer":"要は設計の中に反映した形での提案をしてくださいというのは１項目入れてありますので、そういった提案が出てくるのかもしれません。そういったものにもつながっていくような取り組みになればと考えて、まずはコンペティションという形での取り組みを始めたところです。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"提案","question":"そういう提案がされるかもしれないしというところで、でも一応デザイン優先というところで、デザイン、機能優先ということで。経費削減というところでそういったところもお考えいただきたい、研究されているということでしたけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"重要な位置にあるトイレだと考えていますが、今回コンペティション方式をこのトイレに採用しようとした理由というのは何でしょうか。ご答弁。","respondent":"溝口公園課長","answer":"そういった大井町にふさわしい、そういったものにつなげていきたいという思いがあって、今回コンペティション方式というものを採用したところです。","id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"ただ、やはり大井町は重要だということが１つの理由だというようなご答弁ありましたけれども、あと大井町全体のまちづくりというものもあります。つくられる方のイメージとかもあるのでしょうけれども、区としてはこうあってほしいなどというイメージというものはあるのか尋ねました。","respondent":"溝口公園課長","answer":"まちづくりマスタープランが大きな方針となって、やはりそういったところをしっかりコンセプトを踏まえてつくっていく。そういったところも踏まえてのデザインになってくると考えておりますので、そういったものを踏まえた提案が出てくると考えているものです。","id":"exchange-065"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのあたりぜひご考慮いただいて、これからデザインを考えていただきたいなと考えております。この値段というのはやはり普通にトイレをつくる建築費と比べて高いものなのかどうか、ちょっとそこを確認したいので、ご答弁。","respondent":"溝口公園課長","answer":"これはもう既に平成３０年度の債務負担行為で予算をとっている金額を載せているという形です。予算要求する際には、そんなに過度に高いものというふうには考えておりませんが、今回の応募要領に記載させていただいたものです。","id":"exchange-066"},{"speaker":"横山委員","kind":"質問・要望","question":"そういったところをキャッチしていただけるような実施要領といいますか、区の希望のリクエストの出し方ということが必要なのかなと私は思っています。","respondent":"溝口公園課長","answer":"委員ご指摘のように、一定の質問期間を設けているものです。皆さんが共通認識を持った中で進めていけるように、それをあわせて設計に反映していけるように進めていきたいと考えております。","id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"その寄せられたご質問をいろいろなほかの応募者の方にシェアしていただいたりとか、設計者の方に区が何を求めているのかというヒントのようなものを質問、そのような形でぜひ進めていただけたらと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-09","title":"しながわ水族館イルカショー等の中止","agenda":"しながわ水族館イルカショー等の中止","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大体イルカの妊娠、出産までの期間というのはどれぐらいが通常なのでしょうか。伺います。","respondent":"溝口公園課長","answer":"今、現在水族館側のほうで想定しているのは、８月の１０日前後を出産予定日といいますか、出産するであろうというところで見込んです。そのぐらいに生まれるだろうというところで想定した中での動きを、今しています。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問","question":"すみません。今の質問に続いてなのですが、８月１０日前後ということで、それはどのぐらいと考えればいいのか尋ねました。","respondent":"溝口公園課長","answer":"まずは１カ月ぐらいはショーですとか、そういったところも中止して、イルカが見えないような形の配慮というものを今回行っていくというものです。","id":"exchange-070"},{"speaker":"西本委員","kind":"質問・要望","question":"十分に様子を見ていただきながら進めていただきたいのですが、せっかく出産ということも含めて、新しい仲間ができるのですけれども、それを何でしょうか、名前をつけるであるとか、何かいろいろなイベントにつながると思うのですが、そういうことは考えておられないのか尋ねました。","respondent":"溝口公園課長","answer":"どういう形でのイベントが組めるのか、それもひとえにまずはやはり無事に生まれて、無事生育しての成果になってくると思います。いろいろ水族館側でも考えているようですけれども、そういったところについては運営事業者とともに考えていきたいというふうに考えているところです。","id":"exchange-071"},{"speaker":"西本委員","kind":"質問","question":"ですから、多分ワクワクする部分の１つだと思うので、今度見に行きたいと楽しみになるところがあると思うのです。今楽しいことがあるというか、ワクワク感というか、それを皆さんに宣伝していけるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-10","title":"防災行政無線設備更新工事","agenda":"防災行政無線設備更新工事","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"お伺いしたいのが、今回３０番から、３１番からですね。大井ふ頭のほうのバースのところに、コンテナも含めてですか、コンテナセンター、こちら設置を新しくされた理由をまず聞かせてください。","respondent":"古巻防災課長","answer":"屋外子局の設置がなくて、新たにこちらに設置をいたしまして、そういった方々に対しての防災情報の周知を図るというような内容になります。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"アナログとデジタルの並行稼働の期間があるというのは、全てデジタルがそろうまでは並行で稼働するということでいいのかどうか。アナログに関しては最後は抜いていくという、そういうイメージなのか、ちょっとそこの構造がよくわからなかったので説明を求めました。","respondent":"古巻防災課長","answer":"それぞれ対応する子局が、並行稼働の考え方は両方、こういった形になるです。親局については１局しかないので、親局のほうでアナログ電波とデジタル電波を両方発せられるような仕組みのもので運用するというような形になります。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問","question":"なぜこういう質問をするかというと、昨年総務委員会で香川県だったか、高松市ですね。可能ならば、今５,０００個配付されている防災ラジオも継続して使えるのではないのかと思うのですが、その辺についてのお考えを説明を求めました。","respondent":"古巻防災課長","answer":"アナログ電波の継続のお話ですけれども、こちらにつきましては、現在の方式のアナログの電波ですと法令に反してしまう。デジタル並行稼働している間に少し対応手段を考えて、検討を進めていきたいと思いますので、よろしくお願いします。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"お考えいただいているということで安心をいたしました。地域のコミュニティＦＭですか、あれも補完するようなお話もありましたが、ぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]},{"id":"topic-11","title":"の４、その他を議題に供します。 初めに(1)の所管質問","agenda":"の４、その他を議題に供します。 初めに(1)の所管質問","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今委員長が言ったとおりなのですが、６月２９日に石田秀男議員から、北品川駅の駅前広場について質問がされました。それぞれどのように具体的に配慮していくというお考えなのか、内容を伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"本計画につきましては、昨年１２月１７、１８日に都市計画案の説明会を行いまして、公告縦覧を行ってあります。中身につきまして、詳しい内容につきましてはまだ検討中です。","id":"exchange-077"},{"speaker":"安藤委員","kind":"確認","question":"改めて案が縦覧に供されて意見書が受け付けられるという形になるのか確認させてください。住民の意見をやはりこの計画案の作成段階でしっかり反映させていくという都市計画法の第１６条に規定されている公聴会、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"説明会をすることによる縦覧、それから意見書の提出、こちらにつきましては、改めてそういう形をとりたいと考えています。この説明会をもちまして、公聴会というよりも改めて説明会の中で議論をさせていただきたいと考えています。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそこはしっかり、本当にこれが必要なのかということも含めて検討してほしいと求めました。ですから、その場で出された意見というものをどのように反映していくお考えなのか、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"区が説明をする義務ということは当然あると思いますし、疑義がある場合についてはそれに対して答えていくという形になろうかと思います。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"最後意見ですけれども、都市計画法の第１６条の国の運用指針では、説明会はやはり説明会ですと。ですからそのような性格があるのだということを書いた上で、国の、公聴会というものを開催していただくような検討を強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"あくつ委員","kind":"確認","question":"長時間にわたって伺いまして、前期は建設委員ではなかったものですから、私どもの会派からも申し上げておりました。この前の一般質問の中で、タイミング的には大丈夫なのかどうか、それを確認させてください。","respondent":"東野まちづくり立体化担当課長","answer":"本計画、駅前広場の計画につきましては、京急本線の連続立体交差事業の関連案件として、都市計画案の説明等々を行っているところです。地域の住民の声が反映できるような計画として、区として精いっぱい取り組んでいきたいと考えています。","id":"exchange-081"},{"speaker":"あくつ委員","kind":"質問・要望","question":"安藤委員の発言がありましたけれども、何というのですか、その分大変なご苦労が区当局にはかかると思います。ぜひぜひ区民の意見を最後までできるだけ聞いていただいて、全ての区民の生活に資するようなものをつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"西本委員","kind":"質問","question":"１点だけ、前回の請願ですか、今回の件を受けて何かありますか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"委員会のほうでも説明させていただきました都市計画の運用指針であるとか、そういったものを上位計画として進めてきたところです。反省といいますより、この進め方につきましては区民と向き合うという区の姿勢を、今後は大事にしていきたいと考えています。","id":"exchange-083"},{"speaker":"西本委員","kind":"質問・要望","question":"その際に区には区の考え方があって、よかれと思ってやっていることだと思います。ぜひとも次回から、いろいろなところに関係してきますので、参考にしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/146532?Template=document&Id=4238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":70975,"voices":233}},{"id":"h30-20180703-9","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"文教委員会","time":"午前１０時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)平成３１年度新入学者の受入枠","agenda":"はじめに、(1)平成３１年度新入学者の受入枠","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ、学区外からの受け入れが困難になって、いわゆる姉弟が同じ学校に行けなくなりました。こういう事態が起きて、そういった事例というのがここ最近どういうような傾向になっているのかというのをまず教えてほしいと求めました。","respondent":"篠田学務課長","answer":"兄弟を優先するような形で対応はしているところではありますけれども、最終的に必ずしもご希望に沿えない場合も発生しているということです。昨年で言いますと、抽選を実施している小学校が１４校発生しているというような状況ですので、なかなか今入りづらい。","id":"exchange-001"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"親御さんは弟がいるので、それも想定して入学時に説明を求めて、実際弟がいざ入学するときには入れなかったという事態が生じてしまったのです。親御さんも１つの安心感が出てくると思うので、これは要望で終わりますが、ぜひその点は考慮していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"渡部委員","kind":"質問","question":"今年はこの制度が来年から変わるかもしれないみたいな注意表示はぜひしてほしいと思うのですがいかがでしょうかというのと、まだ間に合うのであれば。逆にそれが混乱を生むかもしれないと言われるとそれまでになってしまうのですけれども、その辺は考えていますか尋ねました。","respondent":"篠田学務課長","answer":"学事制度審議会での答申を受けて動いた形で、これから制度化していくかという入学部分に関しましては、現在いろいろ検討しています。できるだけ丁寧な記述には努めてまいりたいと思いますけれども、パンフレットのほうは大きく変更することはないようなところで予定しています。","id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"今石田しんご委員の質問を聞いて、まだつくられていないということですから、ぜひその辺は研究していただきたいなと思います。こうしたらどうですかと言いたいのですが、それもないので、研究を進めてくださいということで要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺がまず最初の予想と比べてどうだったのかというのを１点教えていただきたいのと、学級数、小学校も中学校もかなり変動していますよね。多分いろいろな予測に基づいてだと思うのですが、この辺の受入可能数の予測というのがどの辺の根拠から来ているのか、２点説明を求めました。","respondent":"篠田学務課長","answer":"それから、芳水小学校も実際にはこちら当初の受入可能数は３学級だったのですが４学級になっていますので超えています。３年間平均したものをあてはめてみて、その辺のバランスを見ながら、受入可能数を決定しています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"住民基本台帳に基づいて、学級数、児童受入数を決定しているというところで、平成３０年度と平成３１年度は基本的には変わっていないというところ。極力本当に避けていただきたいなと思うのですが、その辺の対策というのは、何か考えられているのか尋ねました。","respondent":"篠田学務課長","answer":"教育委員会としましては、例えば１回ランチルームに転用した教室をまた普通教室に戻すとか、さまざまな工夫をして対応しているところがあります。ただ、その辺はできるだけ工夫はしていますけれども、教育委員会として若干対応に苦慮しているというような状況ではあります。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やめていただきたいなと、実施をされる前に実態をしっかり見て、再考していただきたいなと思います。これは意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"平成２９年度品川区立学校における体罰等の実態把握","agenda":"平成２９年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"子どもをどういうふうにそこに集中して向かわせるかという、日常の授業以外のところでそういう１つ１つ、そういう作業をつくることが求められる。それで、先程、体罰の数を平成２４年から紹介してくれましたけれども、全体の数がどうなっているのかについても改めて教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"平成２７年度が８件、平成２８年度が２件、そして平成２９年度１件というふうになっております。平成２７年度０件、平成２８年度０件、平成２９年度０件となっているところです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういう方向に持っていっていただきたいというふうなことは当然求めたいと思いますし、さっき紹介した先生方の本当に多忙だと、時間がないという。そういうところが非常に増えているのではないかというふうに思っているので、その点についての認識も伺いたいと思います。","respondent":"熊谷指導課長","answer":"そして２点目ですけれども、教育活動や学習活動は必ずＰＤＣＡサイクルを行っていかないと、次の活動につながっていかないというのがあります。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"いい教育活動をしていただく上でもそういう姿勢がまず一番大事なのではないかなと思いますので、そこは強く求めておきたいと思います。それからまたいろいろな見解を聞かせていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"渡部委員","kind":"確認","question":"それはそれで理解、承知するのですけれども、当然１２月に調査委託して、３月いっぱいまでで、１回品川区としてはまとめるのですか。１件１件上がってきたものに対して、東京都にそのまま上げるのではなくて、教育委員会として事例を確認というのか尋ねました。","respondent":"熊谷指導課長","answer":"１点目ですが、１ページの２の(1)学校別報告数がありますけれども、副校長が子どもたちの聞き取りを行います。ちなみにこちらの事案につきましては、全て人事部のほうに上げている事案です。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"逆に。キレているほうがよかったのですけれども、冷静にやられたら失格ではないか尋ねました。","respondent":"熊谷指導課長","answer":"ですので、こちらの２件については区といたしまして、厳しく指導を行ったところです。管理職に対しても厳重注意をしておりまして、また、授業観察等も引き続き現在も行っているところです。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"それはやってほしいと要望もします。家庭がそれぞればらばらですから、その辺しっかりやってもらいたいと思うのですが、最後説明を求めました。","respondent":"熊谷指導課長","answer":"何かが起こったときには、すぐにその日のうちに、遅くとも翌日までに教育委員会に上がってくるような状況です。この事実が上がってきた直後に教育委員会として指導をしているということと、そしてこの翌々日には東京都の人事部に全て上げている事案です。","id":"exchange-013"},{"speaker":"渡部委員","kind":"確認","question":"ありがとうございました。１件、これはあくまでもここの体罰で上がってこない限りそういうのが一切ないということの確認だけさせてください。","respondent":"熊谷指導課長","answer":"体罰につきましては、服務事項になりますので処分になりますが、それ以外は区教育委員会指導ということで終わっているところです。","id":"exchange-014"},{"speaker":"つる委員","kind":"確認","question":"今、渡部委員が確認していただいたところの２ページの３の（２）のところ。もう１回あえて確認ですが、これはこの２件とも品川区の事案例となっているけれども、まずは前提確認してもらえますか。","respondent":"熊谷指導課長","answer":"こちらにつきましては、どちらも品川区の案件でございまして、上の（１）の表の中の不適切な指導、中学校１件。そして暴言等、中学校１件となっているものの、具体的な内容がこちらです。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"そうすると、今の、先ほど渡部委員から質疑していただいたこの該当教員というのでしょうか。教師であるとか校長、そのことについて自分で報告を上げないといいますか、そこのところについてはどういうふうに捉えているのか説明を求めました。","respondent":"熊谷指導課長","answer":"これにつきましては、１ページの申告者別報告数で教員本人からの１件というのが、こちらに該当するものです。保健体育の授業でありましたけれども、あまり深く思っていなかったということが１番の課題だと思いましたので、そのことも含め指導をしたところです。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問","question":"こういう中で、その前提の部分というのが、要するに家庭で教育をすべきところのこと。そこのあたりというのは、今現状どういうふうな課題という観点であるのか、それを改めて説明を求めました。","respondent":"熊谷指導課長","answer":"地域の方とともにどういった支援をしていただくのがいいのか。そういったことも検討していくということが、そして子どもたちを地域と一緒に育てていくということが大事ではないかというふうに思っています。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"一事案としてフォーカスするだけではなく、本当にバードビューという本当に広い視野で対応していくということが大事なのかなと。それこそ、その前提の中で子どもたちが目の前の眼前の事実に対してはどう乗り越えて、激励をしていただけるような形にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"その点はどういうふうに解決をしているのかというのを１点教えていただきたいのと、先生は今、指導方法についてすごく悩んでいると思うのです。その２点説明を求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"まず不適切な指導については、保健体育の柔道の時間に５分ぐらいおくれてだらだら入ってきたというのがあります。後段につきましては、教育総合支援センター長より説明いたします。お互いに、大きく怒鳴っても効果はなくて、逆に冷静に言われるほうが子どもにとってはとても効くのだよという話は若手の先生にはよくしております。","id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私は日ごろから教育委員会には強く要望していますが、逆に先生たちを守るというのは、私はこれは教育委員会の仕事だと思うし使命だと思うのです。私は逆に、逆に知りたいなと思うので、もしわかればそこも教えていただければなと思います。","respondent":"大関教育総合支援センター長","answer":"結果的に例えば薬の服用によって抑えられるタイプのお子さんが、衝動的に手が出てしまったというようなケースなどもあったりはします。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"（４）調査方法のところで、質問紙調査および聞き取り調査というのがありますが、事実をしっかりつかんでいくというのは大変なことです。それが把握できてというのは、ここはすごく大事だと思うので、この辺のところはどのぐらい機能されているのかというところを説明を求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"１点目の非該当なのですけれども、具体的な内容が、公園で中学生らしい人がけんかをしているのを見たというような意見が上がってきております。私が直接聞き取りをするのは教員ですので、これは体罰ではないかと思われる案件については… 自分自身が６件に対して、学校への苦情要望という形が１７件というふうに、逆に悩みを早めに子どもは申し出ている状況があります。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"話が聞けるということはすごく大事なことなので、先ほどカウンセラーに聞いてほしいとか、なかなかこのごろ相談件数が多いのではないでしょうか。ここが今結構かなめかなと考えていますので、ぜひ充実をさせてほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"それ以外に本区としては、区費でカウンセラーが２週に一遍になりますが、各学校巡回しております。直接学校に出向いていって、子どもたちの話を聞いたりして、かなり他区よりも丁寧に子どもの声は拾っているという実態があります。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、そのあたりのことが１点と、もし区であれば。もしそういったことがわかればそのことについて、傾向とそれに対する対応といいますか、お尋ねします。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"でも、ではどう対応するかというのを考えることが重要だというふうに、研修等では専門家も含めて研修内容を充実しています。あるいは、ではどういうふうに対応すべきかということについては… そういった事例をもとに研修をしながら、自分のこととして考える機会を年３回設けているところです。ですので、そういったことを踏まえながら、毎回指導していくことが大事ではないかなというふうに捉えております。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、学校ごとのスタンダード。学校の適性に合わせたことを定めて、そういった面はそれを進めていっていただきたいと思うのですが、その点について。","respondent":"大関教育総合支援センター長","answer":"さらに学校生活を充実させるためには、どういった内容の見直しが必要であるかなどは検討しています。もし見直す際は相談をしながら、地域・保護者の協力を得ながら、各学校が見直していくものかと考えております。","id":"exchange-024"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"それに関してはどういう対策をとっているのか、質問です。いけませんねだけでは当然済まないと思うので。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"児童・生徒に対して対応するべきかは検討して、理由がある場合は教育委員会も、学校をしっかりとバックアップしております。それは家庭と話し合った上でですけれども、そういった部分は実際に生活指導として行っているところがあります。 日ごろから職員室の状況ですとか、また学校の中で毎日巡回していますので、そういう中で子どもと教員とのやりとり。そういったことをしっかり把握しながら事前に防ぐように支援していくことが重要だというふうに考えております。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことで仕事をしてきているわけですから、自分が授業をしたときに、あの子はなかなか関心を持ってくれないなとか。ですから、あるいは職員会議での１つのテーマにしたやりとりだとか、どこまで学校の中で保障されているのかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"品川区立学校 運動部活動の在り方に関する方針","agenda":"品川区立学校 運動部活動の在り方に関する方針","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"部活のことは子どもたちの１日の生活に占める時間としても、あと教員の方々の負担というところの両面でいろいろ問題になっていると思います。私は、４ページのところに具体的に示されている中身をぜひ実践をしていっていただきたいなと思っているのですが、その辺はいかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"部活動指導員という新たな支援者を、一遍に全てがというのは難しいとは思いますが、徐々に行っていこうかと思います。もう進んできているような実態があります。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"体が壊れてしまっては困るので、１つには本当に健康面についての留意点も十分していただきたいなと思っています。部活動の割合がすごく占めていると思うので、ぜひそういった部活動指導員の充実というところに期待をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"伺いたいのは、どういうふうにその辺の専門的な知識を得るようになるのか、そしていろいろと指導も受けながら頑張っているではないですか。(2)番の地域との連携等の一番上にありますが、これはどういうことを指しているのか、その辺について伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"今後は、区の教育委員会が直接主催の形で、部活動指導者研修会という形をしっかりと位置づけてまいりたいと考えております。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"少し質問なのですが、例えばスポーツによっていろいろと、体の成長によって出る不具合というのは違うではないですか。そういうものは当然話があり、個別に質疑も含めてやるチャンスはあるのだと思うのですけれども、そういうふうに捉えていいのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"そういったところと連携を含めながら、さまざまな学びの機会という部分は情報提供してまいりたいと思います。学校の部活動の指導者として、服務も含めまして、先ほどの話題にもありました体罰防止も含めました観点での指導内容も必要かと考えています。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"不勉強なのですけれども、そもそも中学校。小学校はないと思いますけれども、中学校の部活で合宿というのはあるのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"合宿的な扱いになろうかと思いますが、何かの強化のためにずっと努めるとかという部分、十分内容を検討しながら考えていく必要があろうかと思います。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"そうすると、要は４ページの適切な休養日等の設定に関連してなのですけれども、ここで平日は２時間。それから長期休業中は３時間程度とある中で、元プロ野球選手が野球は２時間はなかなか短いよねという意見もある中で、その辺の状況を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"方針として示したとおり、長期休業期間中も３時間というものを、原則として考えています。球をとって、ランニングをしてというような部分はなかなか、やはり見直す時代になってきているというふうに認識しています。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"わかりました。どういうもので規定されているのかということと、違うものがあればそれはその辺のことに関して、参考までに説明を求めました。","respondent":"大関教育総合支援センター長","answer":"子どもたちの安全管理にかかわる重要な内容として、部活動指導員も教員も含めまして、しっかりとそこは指導を行いたいと考えています。あるいは小学生ももう５年生以上は必ず学ぶということで、これは、もれなく部活動に携わる人間には学ぶ機会を設けていきたいと考えています。","id":"exchange-033"},{"speaker":"つる委員","kind":"確認","question":"そういう理解でいいですか。その確認だけ。","respondent":"大関教育総合支援センター長","answer":"もう、運動にかかわる指導内容の中に、しっかりと当然心肺蘇生法とか、あるいは応急処置という部分は、学ぶ内容となっておりますので、文言では出てきておりませんが、もう必ず学ばせてまいりたいと思います。","id":"exchange-034"}]},{"id":"topic-04","title":"子ども若者応援フリースペース事業の拡充","agenda":"子ども若者応援フリースペース事業の拡充","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺を教えていただきたいのと、どこがどういうふうに責任を持ってやっていくのか、あと予算はどの程度ここに使われることになるのか説明を求めました。","respondent":"高山子ども育成課長","answer":"ひきこもり等の学習支援をされているような団体が、この事業についてはより充実したものとしていっていただきたいというふうに考えております。最後、予算につきましては、今年度は初度調弁等の予算も必要であった関係で、１,７００万円ほど計上させていただいるものです。","id":"exchange-035"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平塚橋ゆうゆうプラザにも近いところなので、子どもたちがなれている地域で通えるということは、とてもいいことだなと思っています。そういった声もこの８つのＮＰＯ団体の皆さんにぜひどこかで一度聞かせていただきたいなと思いますが、いかがか尋ねました。","respondent":"高山子ども育成課長","answer":"この施設の運営が安定したところで、ぜひ文教委員会の委員の皆様にも現地を視察していただきたいと話しております。その中で、担っていただいている団体の方との意見交換などもできればというふうに考えております。","id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"自分の存在を確認できる。そこの１点だけ伺いたいと思います。","respondent":"高山子ども育成課長","answer":"現段階では３日程度ではあるけれども、見込みはあるのかという点につきましては、今般予算の関係で３日ということ。それから、ぜひこの日数につきましては、いわゆる常設というにふさわしいような日数まで拡大していきたいというふうに考えているところです。","id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点が、周知の方法とはどういうふうにされているのかという話。その点どのように周知されているのか教えていただきたいのと、静かにしているところで、工夫されているのかどうかだけ教えていただけると。","respondent":"高山子ども育成課長","answer":"中学校、この夏休みの前にこういった新たな拠点が誕生することについて、より多くの方に知っていただくような形で周知に努めてまいります。そういう意味では、この２年間の運営の報告の中では聞いたことはございませんので、特段支障がないものと考えております。","id":"exchange-038"},{"speaker":"石田（し）委員","kind":"質問","question":"もう１点だけお伺いしたいのですが、以前ゆうゆうプラザでやられていたときには、４０代ぐらいの方も参加されていたような話も聞くのですが、その辺が違いがあるのかなと思うのですが、いわゆる児童センターとここのフリースペースの違いというのが何なのかを説明を求めました。","respondent":"高山子ども育成課長","answer":"根拠は基本的には子ども・若者育成支援推進法という法律の第１３条で定める総合相談窓口。そういったことを想定するものです。","id":"exchange-039"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"この日程の中に大阪市が入っていて、しかもこの市役所の位置が北区となっていて、前回も地震で、震度６弱と一番大きい揺れがあったエリアなのかなと思うのですけれども、その辺については、先方と何か話はされているのかどうかだけ教えてほしい。","respondent":"塚本委員長","answer":"一応９月の上旬であれば何とか対応できるのではないかとご回答をいただいているところでございまして、９月上旬の受け入れというところでは、その時点で進めさせていただければと思っているところです。","id":"exchange-040"},{"speaker":"南委員","kind":"質問","question":"人権教育はそれなりにあっていいのかなと思う項目だとは思うのですが、兵庫県を選ばれた委員長、副委員長のところの趣旨。基本的な考え方といいますか、そこはどういうところなのか伺っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"南委員","kind":"確認","question":"わかりました。では、ＬＧＢＴとかいじめなどの新たな課題に対応したというそういうところを基本的なテーマにするという確認でいいか尋ねました。","respondent":"塚本委員長","answer":"ここに性的マイノリティーやいじめなど新たな課題に対応したというところが書いてあります。","id":"exchange-042"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ですから、特に夏休みで子どもが学校に通っていない時期になりますが、ぜひ進めていただきたいと。それを教えていただきたいです。","respondent":"有馬庶務課長","answer":"今設置しては不適合になりますので、ブロックの段で言えば１１段ですよということを示して、そういう視点で見ていきましょうと。さわって何かやるわけにもいきませんけれども、そういったところもあわせて見てくださいねということで、学校にお願いしています。","id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"今、課長がおっしゃったように、個人の所有のところが多いわけですから、そういうことは当然と思うのですけれども、そういう皆さんのご協力とご理解。そういう働きかけといいますか、どういうふうに捉えてどういうふうに動くかというのは教育委員会の見解として聞いておきたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"確認","question":"それから確認なのですけれども、２.２メートルの高さを超える、例えば大阪の地震で落下したああいう構造のものはないということの理解でよいのですよね。","respondent":"有馬庶務課長","answer":"それが鈴ケ森小学校で、しかも区道に面しているということですので、これは早急に対応しようということで、今回工事に着手したということです。あくまで通学路で学校から情報があれば、こういったところもありますよという情報提供ということで、今のところ考えております。","id":"exchange-045"},{"speaker":"南委員","kind":"確認","question":"私も確認しておかなくてはと思いながら、しないままここに臨んでしまっているのですが、鈴ケ森小学校がどうだったかなというのが気になったところなので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"私も調べきれていなくて、今はブロック塀についての確認ということで、横に細長いものが幾つか枠を組んでいるコンクリートパネルがありますよね。そういったものについての耐震性だとかという確認というのは、今回のこれとあわせて確認などされているのか尋ねました。","respondent":"有馬庶務課長","answer":"それ以外に今言ったようないわゆる万年塀と昔は言っていたものが相当数まだあるというのもわかっていますので、これにつきましては、これからです。","id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"あらゆる危険、子どもたちの周りにあるハード的な危険もしっかりと除去できるような施策をぜひ積極的にやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/971992?Template=document&Id=4946#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":50548,"voices":141}},{"id":"h30-20180703-5","meetingId":"h30-cm07","date":"2018年7月3日","dateIso":"2018-07-03","committee":"総務委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、平成３０年度品川区一般会計補正予算の審査結果","agenda":"説明に入る前に、平成３０年度品川区一般会計補正予算の審査結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"個別具体的なことはこの場では求められないので、多少変わっているのかどうなのかというのが一点と、どうしたのですかと言ったら。何となく当初予算の中に入れ込んでいくこともできたのかなと思いましたので、質問します。","respondent":"品川財政課長","answer":"補正予算でさらに５００台を追加するというものです。この背景には、このような背景のところから今回補正予算で新たに５００台を追加して進めていくものです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１月に入ってからでこぼこしている、１月だと３カ月ぐらい待って４月、５月になるわけですね。どんどん積極的にそういう部分に関してはやっていただいた方がいいのかなと思うのですが、その辺についてちょっとお願いします。","respondent":"品川財政課長","answer":"区の行っている事業で補助金の関係で年度末になるとできないという事業は幾つかあるかと思います。こういったところは、そういう解決策がないかは全庁的にも少し考えていかなければいけないところではないかと考えております。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ほかの自治体だとすごく待たされるのだけれども品川区は予算も含めてしっかりと地域のために執行しているよねと言われるような行政になっていただきたいなという思いがありますので、しっかりと予算を補正でつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"議会運営委員会、本会議で確認され総務委員会に付託されているわけですが、必要な質疑を補足していくということが必要なのではないかと思うのです。区の方向性が決まり緊急のもののうち、どれに当たるのか、簡単に言うと補正として計上した理由は何か伺いたいと思います。","respondent":"品川財政課長","answer":"これに関しましては、区役所の高齢福祉課と障害者福祉課が連携して事業を行うというものです。区のほうでもこの課題の解消に向けていろいろ検討を進めていったところでございまして、今回の補正予算に計上しているというものです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それに対して、議会への報告という点を改めて振り返ってどう思われているのか伺いたいと思います。そこも伺いたいと思います。","respondent":"品川財政課長","answer":"こういう相談件数の多いという統計上のものからやはり相談件数の部分の解消をどうにかできないかというところで検討をしていたという経過があります。そういった部分を総合的にまずは検討してみるという委託経費として今回計上しているものです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"在宅介護支援センターも言わば手いっぱいの中で新たに加えるという提案が本当にできるのか、もっと言ったらこれがよいことなのか。最後にその点、いかがか尋ねました。","respondent":"品川財政課長","answer":"あくまで検討段階というところで出している予算ですので、こちらをまず検討してみて一定の方向性、やり方とかも出てくるかと思います。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"あくまで検討経費だというお話ですけれども、プレス発表資料には高齢者・障害者の包括支援相談体制として形が示されているわけですよね。そういう意味ではしっかりと議会への報告を行い議論を深めながら予算の審議をするということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"私の態度を、ぜひ教えていただきたいというのが１点と、６月２１日の日経新聞に既に品川区でもう決定したかのような記事になって出ているわけです。この補正の審議はどういう重みがあってどういう意義があるのか、改めて伺いたいと思いますので、その点をお願いします。","respondent":"桑村副区長","answer":"それともう一つはこの障害者包括支援相談体制の構築検討という中身と３つ重なっているのだろうと思うのです。もちろん一つのことを考えなければ検討できませんので、区とすれば今の在宅介護支援センターを使って、非常にきめ細やかな対応ができるのではないか。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"ということは、今回の議決対象はあくまで高齢者・障害者の包括的支援体制整備に係る検討までということで理解してよろしいでしょうか。もう一度、確認させてください。","respondent":"桑村副区長","answer":"そのとおりです。よろしくお願いします。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"誰に尋ねたらいいのだろう、我々今後どうなるのだろうという疑問、そういう質問をたくさん受けます。やはり末端は区のほうで、その大もとはやはり国、区からももっと強くお願いしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"１８款の繰越金で補正前が３０億円でずっと前、過去をたどると大体２４億円という年が多くて今回の当初予算では３０億円になっている。個別には問い合わせさせていただいたのですが、もう一度ご説明いただけるとありがたいのですが、。","respondent":"品川財政課長","answer":"こちら繰越金については、基本的には前年度の残額を持ってきているというものです。前年度の残額を全て当初予算に持っていっているというのではなく、一部を持ってきて、あとは補正予算等で使っていくという流れでやってあります。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"そこまでは大体わかるのですが、この年度の途中の、今は６月補正で今度９月補正と、そういうふうに順番に補正が出てくるということが、よく理解できないので、その辺を教えていただけますか。","respondent":"品川財政課長","answer":"必ず予算というのは歳出があれば歳入もどこかで持ってこなければいけないということになります。その歳入の部分をどこから持ってくるかというところで繰越金というものを使っていくものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"意見","question":"議会でも相談体制を充実することは必要なことだと考えていますけれども、これが実際によくなるという確信がこの状態では不明だという点です。さらにはトイレの改修など、評価できる点もありますので、総合的には賛成ということになりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"増やすようにという要望してまいりましたので、いずれ高齢者と障害者が一緒に相談できるというのはまさに目指す方向だと思います。ただ、一般質問でご答弁いただきましたけれども、その辺についてはさらに進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"高知県との連携","agenda":"高知県との連携","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"何点かお伺いしていくので、一括して質問いたします。私たちが所在するところは東日本であって、高知県はいわば西日本になるのでプレートが違うわけですから、その辺をお伺いします。","respondent":"柏原企画調整課長","answer":"今後の連携の形といいますか継続性といったところだと思いますけれども、継続的な事業連携であったり、連携の形をとっていきたいです。できる事業等々ぜひ具体的なものがあるときには予算化をしながらお示しをして進めていきたいと思ってあります。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"旅行会社がコーディネートしてこういう連携をしているからどうですかという案内をいただいたというのもあるので、そういうところをもっと、子供たち。そうしないと、それも所管が違うからそこへ一回一回確認していかないとわからない状況であるというのは事実かもしれないですけれども。","respondent":"柏原企画調整課長","answer":"では次にどういう展開がいいのだろうかと、お互い話し合い、考えながら民の力を含めながら進めていくということがこの進め方であろうと思います。ですので、うまい形で継続できるような方向で進めていきたいというものです。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"こういう事業をやっているとどこかで恐らく、そういう場合行政はなかなかやろうと思ってもできない部分があろうかと思います。そういったところとしっかり連携をとってやってほしいと求めましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問","question":"交流していますとただ旗を揚げるのではなくて、やはりそれに伴う事業、活動というのを考えれば予算が伴うのです。こういうふうに連携自治体をどんどん増やしていっていいのでしょうかと思うのですが、これについてご意見を説明を求めました。","respondent":"柏原企画調整課長","answer":"お互いの持っている資源といいますか長所というものをうまく活かしながらというのがベースといいますか考え方であります。広域連携というところが少し動き出していますので、やみくもに増やしていくということではないということでご理解いただければと思います。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"学生さんまではいいのかもしれないのですけれども、坂本龍馬という名前を前面に出していますが、大丈夫なのですか。要は、歴史的な交流というのはつながっていくのでしょうかと疑問に思うのですが、その辺についてはどのようにお考えか尋ねました。","respondent":"柏原企画調整課長","answer":"坂本龍馬をきっかけに品川区の方と高知の方々につながりができる、これは事実ですので、こういったゆかりのある方ということでお示しをしています。","id":"exchange-019"}]},{"id":"topic-03","title":"五反田防災桟橋整備工事請負契約","agenda":"五反田防災桟橋整備工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"一点だけ伺いたいんですけれども、目黒川は私の小さいころからよく氾濫をしていて、氾濫に対してもこの桟橋は耐えられるのか。この桟橋がどういうことになるのか、そこだけ教えていただけますか。","respondent":"立木経理課長","answer":"細かい部分までわかりませんですが、恐らくそういった部分、目黒川の特性というのも加味した上で設計のほうはなされていると考えています。委員ご指摘の点は所管のほうに伝えします。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"要するに工事件名は防災桟橋という表現ですが、やはり防災桟橋にすると都や国から補助金が出るとかでないとかという話になるのか。この「防災」という名称を取ってしまうと国や都からの補助金が、観光の要素だと余り出ないとか、そういう意味合いなのか尋ねました。","respondent":"立木経理課長、桑村副区長","answer":"こちらの工事の関係なのですが、一応水辺の活用です。平成３０年度はこちらになっているのですが、その辺は申しわけございません、ちょっと私のほうからは。今は防災桟橋という形の防災上役に立つ、そういう桟橋しか今のところ東京都とすると許可する方針にはないということです。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問","question":"要するに河川の管轄は東京都ですから設置する防災桟橋、防災桟橋ですからそういう事業はだめですよ的なことというのはもしかしたら例えば何かの事故。そういうことがないという副区長のご答弁がありますので、ありがとうございました。","respondent":"桑村副区長","answer":"普段からお互い協議して進めていく、また東京都のほうもいわゆるこういう舟運を進めていくというのは一方では河川の管理とは別に港を含めていろいろやっていこうということが都全体の方針ですので、進めさせていただきたいと思います。","id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今回の契約が１億５,０００万円ということで、約４,０００万円ぐらい安い金額になったと思うのですけれども、金額が１億５,０００万円になったという理由を教えてほしいと求めました。","respondent":"立木経理課長","answer":"落札率が９８.７％ということで、恐らく当初予算で見込んだ中で予定価格を積み上げていく中でこれぐらいの落差が生じたのではないかと思われます。細かいところまでは私からは申し訳ございませんがわかりません。","id":"exchange-023"},{"speaker":"高橋（伸）委員","kind":"意見","question":"４,０００万円の開きというのは工事の施工とか、わかる範囲でいいのですけれども、例えば構造物の撤去とか構造体の撤去に高額な費用がかかるところ、実は撤去費が少し軽減できたとか、４,０００万円という金額の開きの理由がわかればいいのですけれどもとの意見を述べました。","respondent":"桑村副区長","answer":"一番多分いい方法をとった、いい方法というのは、金額的にも安くて安全性のある方法をとらせていただいたのだと思います。予算上は申しわけないですが少し大き目の金額を出させていただいてこの案に決まったのだと思います。","id":"exchange-024"}]},{"id":"topic-04","title":"戸越小学校校庭整備工事請負契約","agenda":"戸越小学校校庭整備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"戸越小学校は築年数も大分たっているではないですか。恐らく改築計画が順次進んでいると思うのですが、逆に戸越小学校の改築計画は当面の間ないというふうに考えてもいいか尋ねました。","respondent":"立木経理課長","answer":"一応老朽化の部分で必要なところには補修をしていかないとお子様の安全等にも関わってくることですので、一応校庭整備等の管理上そういったところを改善するというところで行っていると聞いてあります。","id":"exchange-025"}]},{"id":"topic-05","title":"です。荏原平塚学園校庭整備工事請負契約","agenda":"です。荏原平塚学園校庭整備工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"入札一覧のところに会社名がずらっとあって、予定価格が１億６,４９２万６,０００円と出ているではないですか。１年に１回の夏休みですから、夏は夏でクラブ活動が盛んだと思うのですけれども、子どもたちはグラウンドを使えないわけですよね。","respondent":"立木経理課長","answer":"ですので、事業者はその予定価格を見ること、知ることができます。予定価格とは別に最低制限価格、このラインを下回った場合には失格という形をとらせていただく制度を持ってあります。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"２,０００万円安いので、その額が本当に建設会社としてウインになっているのかなという疑問があったので質問させていただきました。そこは経営ですから品川区は関係ないですよという話になってしまうかもしれないですけれども、質問させていただきました。","respondent":"立木経理課長","answer":"入札の部分は今いただきましたお話に関しましてはしっかりと受けとめまして、今後の参考にさせていただきたいと思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"どうしてもほかの工事は３社、その中で辞退者があるという話ですから、そちらのほうも努力していただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-06","title":"品川区長選挙および品川区議会議員補欠選挙における執行計画","agenda":"品川区長選挙および品川区議会議員補欠選挙における執行計画","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"質問を２点と要望を１点したいのですが、まず要望からさせてください。うちの会派からもいろいろ質問、要望させていただいた中で、その辺をどうお考えかというのがまず１つ目の質問です。","respondent":"秋山選挙管理委員会事務局長","answer":"公報の件ですけれども、１日で配れないかですが、今のところ今回もシルバー人材センターを用いて配る予定で考えているものです。そういうことがないようにこちらも十分注意してまいりたいと考えています。","id":"exchange-029"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いろいろ想像力というか発想の転換をしていただいて、投票率向上に向けて頑張っていただきたいとお願いしたいです。ご答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"アトレは日にちも違うけれども１０時から。これは私としては余り定着していないなという思いがあるので、さまざま混乱のないように入場整理をしてほしいと求めましたが、いかがか尋ねました。","respondent":"秋山選挙管理委員会事務局長","answer":"物理的な制約というのがアトレにはございまして、アトレの開店時間は選挙のために早められないということですので、１０時からとなっているです。それから事前の選挙公報だけではなくて、広報しながわ等のＰＲ等についても時間も含めて周知をさせていただいているところです。","id":"exchange-031"}]},{"id":"topic-07","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"高齢者虐待、児童虐待については、所管がちょっと違うのかなと思っていますが、そこにも入ってしまっていいのか尋ねました。","respondent":"伊藤委員長","answer":"なお、実施時期については、今後の議案や報告事項等の案件との関係もありますので、時期を見ながら対応していきたいと考えています。理事者の方々にもいろいろな資料をお願いするかと思いますが、どうぞよろしくお願いをいたします。","id":"exchange-032"}]},{"id":"topic-08","title":"その他を伺います。 まず(1)所管質問","agenda":"その他を伺います。 まず(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"公営住宅法の親族要件についてはもう既に外れていると思いますので、それ以外に法の解釈が分かれるというところがあるのであれば、その点についてお答えほしいと求めました。","respondent":"島袋人権啓発課長","answer":"同性カップルは親族関係が確認できないことから入居を認めておりません。この件に関しましては慎重に議論をしていく事柄であると考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"その両方のマイノリティーの立場の方たちの中で同性であるということで差別を受けることになりはしないのか。その辺について、人権尊重都市としての考え方をどのように今お考えなのか説明を求めました。","respondent":"島袋人権啓発課長","answer":"２３区内におきましてもまだまだパートナー制度を実施している自治体は３自治体になるのか、中野区が実施するというところなのですけれども。人権尊重都市品川宣言、あるいは地域の皆様に知っていただくことがまず人権啓発課の一つの課題だと考えているところです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"意見","question":"ただ、やはりそれぞれ自治体としても判断していくことがあっていいのではないかと考えています。ぜひ前向きな方向で今後検討していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ同性カップルの区営住宅への入居を認めていただきたいと私も強く要望したいと思います。１件だけ伺いたいのですけれども、「現に同居している、「現に同居している」だけではだめなのか尋ねました。","respondent":"島袋人権啓発課長","answer":"実際同性カップルなのか他人との同居なのか、シェアとして入ってくるのかもわからないとかそういった部分もあると聞いておりますので、まさしくどのような状況なのかというのをこれからの課題として考えていく項目だと思っているところです。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"それに対しては行政も不十分さはあるものの夫婦としての実態を認めさまざまな行政サービスの対象にしている状況もあります。生活の実態も認めているわけですから、今後よく私のほうでも調査・研究を進めていきたいと、意見として述べさせていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"有資格者の職員がやったものなのかどうか、どういう資格を持っている方がチェックをされたのかどうか、そこを伺いたいと思います。資料に基づいて４の今後の対応についてで1)の施設、2)の施設、3)の１４施設というのはそれぞれどこなのか伺いたいと思います。","respondent":"小林施設整備課長","answer":"平成２８年の調査の件につきましてお答えしますが、それと一緒に同伴している免許をこれから取ろうという若者が一緒に現場を調査をしております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"残りの１４施設については改修の見通しというか計画が決まった際は丁寧に説明をしていただきたいと要望だけしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"いながわ委員","kind":"質問・要望","question":"多分所管には生垣助成、あえてそのときには所管に確認はしなかったのですけれども、こうしてすぐ対応したということを評価するところであります。フェンスを推進するような施策を展開していただきたいなと思いますので、これは意見として申し伝えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、ぜひ注意、警告等をするような何か対策をしてほしいと求めました。これは要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"吉田委員","kind":"意見","question":"情報を隠すことが不安を抑えることになるのかなというのはあります。これは意見としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/147246?Template=document&Id=2112#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":40400,"voices":122}},{"id":"h30-20180704-14","meetingId":"h30-cm07","date":"2018年7月4日","dateIso":"2018-07-04","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ０時４０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"控除額は住民税、所得割額の２割が限度ということなのですけれども、最大の２割まで控除されている方は結構多いのではないかと思っています。それが結果として、２割まで控除されている方がどれぐらいいらっしゃるのかわかればお伺いしたいと思います。","respondent":"伊東税務課長","answer":"本当に考えてやっている方はその辺をチェックして、２,０００円を引いた分が、丸々控除されるのが望ましいと多分考えると思います。高額納税者の方は金額がぐっと上がっていきますから、それ以外の方は自分の限度額というのはある程度把握した上でやっているのかなと思われます。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"２３区共同で偏在税制是正措置に対して断固反対することを緊急声明として発表したということですが、「断固反対し、見直しを引き続き要望していく。それとも地方の自治体を応援するという意味なのか、そこをお伺いしたいというのが４つ目です。","respondent":"伊東税務課長、品川財政課長、柏原企画調整課長","answer":"現に都市部の連携の中で、さまざまな機会を捉えて、細かな部分で要望は出しています。１つは今年から地域振興寄付への受け入れを開始したというお話をしま… 上限額２割の部分を１割に戻してくれとか、ワンストップなので、所得税分が住民税として支払わなければいけない部分があると思います。それから… 具体的には、例えば、いろいろな地域とイベント、事業の連携や、いろいろな協定を結んで交流を図っていこうというところがあります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"今言ったような課題の解決に当たって、特別区全国連携プロジェクト以外に何かやるべきことといいますか、やれることはないのでしょうか。そこら辺のお考えがあれば、伺わせてください。","respondent":"柏原企画調整課長","answer":"特別区全国連携プロジェクトは１つのやり方ということで、人の交流や動きが出てきたり、この特別区全国連携プロジェクトです。特別区としてどういうことがやれるのかというのは、これからも共同して研究しながら、進めていくという姿勢です。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、品川区がどうこうするというよりは、国の姿勢が変わらない限り、直りようがないのではないですか。２位がマウスコンピューター、都市にはいろいろな電機メーカーがあるわけですから、こういう返礼品を出しますとやっていくべきではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺っていきたいと思います。区内に所在する企業の物品やサービスを返礼品として考えているかと思うのですけれども、まず、その確認をお願いいたします。","respondent":"伊東税務課長","answer":"品川区にゆかりのあるというか、関連しているものということで、しながわ土産に代表されるものです。それと細かく言えば、品川区史とか、競馬場のチケットとか、水族館のチケットというところで、区に関係しているものを選定させていただいています。","id":"exchange-005"},{"speaker":"横山委員","kind":"質問","question":"先ほどほかの委員の議論の中でも、特別区全国連携プロジェクトの話もありました。今後、そのあたりとの関係性というか、今後のあり方についてどのように考えていらっしゃるのかをお聞きしたいと思います。","respondent":"伊東税務課長、柏原企画調整課長","answer":"連携といいますか、区域内で生産されたものとかということが言われておりますので、当面はその中で考えていかなければいけないかと考えています。全国との連携という考えからいいますと、返礼品とするときに相手方の地方とどう関係があって打ち出せるかというところの工夫の仕方なのだと思います。","id":"exchange-006"},{"speaker":"横山委員","kind":"確認","question":"国の理念の確認なのですけれども、資料でも３つの意義が書いてあります。品川区としては、その使われ方を考えるきっかけとなるような取り組みや周知のあり方、そのあたりは今後どのように考えていらっしゃいますか尋ねました。","respondent":"伊東税務課長","answer":"使い道が明確にできるような事業等があれば、そういうものに対してもふるさと納税で納めていただくことを考えていこうかと考えています。ある程度品川区を見てもらう、そういう事業はなかなか難しいところですけれども、そういうことが言えるのではないかと思っているところです。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"まずは品川区として、制度をしっかりと理解していただく努力をしていただきたいと私から強く要望させてほしいと求めました。品川区がどういう影響を受けるのか、しっかりと品川区としても周知をお願いしたいと思うのですけれども、そのあたりの区のお考えを説明を求めました。","respondent":"伊東税務課長","answer":"総務省のホームページは、先ほど説明したところがそのまま書いてありまして、こういう趣旨で制度ができているというのは出ているところです。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"他自治体への流出額が大きいので、それを応援するのに、品川区民が品川区にふるさと納税をするというのはできるのでしょうか。区民の方で、こういう流出の課題を捉えて、品川区のために何かしたいと思われる方がいらしたときに、どういうことをご案内できるのか尋ねました。","respondent":"伊東税務課長","answer":"現状で区民が区にふるさと納税をするというのは、この制度の趣旨からすると、ちょっと違うのかと。ただ、制度的にはでき、他自治体に寄附するのと全く同じ扱いになります。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"事業というところでしょうか、多分今まだそれも検討したり、品川区らしい今後のあり方をぜひ前向きに検討してほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こんの委員","kind":"確認","question":"今後の取り組みというところで確認というか、どのようにお考えなのかをお聞きしたいと思います。品川区を応援したくなる新規事業はどういうものなのか、どのようなお考えで捉えていらっしゃるのか尋ねました。","respondent":"伊東税務課長","answer":"１つ思っていたのは、今年から地域振興寄付を入れてきているわけですけれども、それぞれある目的のための基金があります。その辺もしっかり考えておかないと、事業ができないということもありますので、それはよくよく検討した上でないといけないのかなと思っています。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"皆さんがどういうことで、品川区を応援したいと思っているのかというのを、アンテナを張って事業を見ていくことが１つあるかなと思います。その点、ぜひ頑張ってほしいと求めましたが、企画調整課はいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"いろいろ検討する中で、平成３０年度の予算編成をする中でも、内部的にはいろいろ検討してきた経過はあります。日々検討していますけれども、改めてご意見をいただく中で、検討を深めていきたいと思っています。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこで、品川区の考え方をもう一度確認させていただきたい。いろいろなご意見を出する中で、大きな視点として、現状で区は流出抑制をどういうふうに考えているかというところを説明を求めました。","respondent":"中山企画部長","answer":"区としては、非常に危機感を抱き、何とか是正しなければいけないという認識は持っているところでありますので流出を抑えたいという思いはあります。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"１人、２人、飛びつく人がいるかもしれないわけです。今プラネタリウムがあるところも少ないですから、あいている時間などあるでしょうから、それは意見としてお話しします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"木村委員","kind":"意見","question":"今皆さんの意見を聞きながら、何となく思ったのですけれども、これは多分皆さんと同じような考えだろうと思います。そういうことは考えられるかどうか、説明を求めました。","respondent":"柏原企画調整課長","answer":"目的といいますか、どう使われるかをはっきりさせるというか、わかりやすくするのは必要なことだと思います。パターンがありますので、区でももう少し深い議論が必要と思っており、検討を深めていきたいと思ってあります。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"そして特別区全国連携プロジェクト、この３点なのですけれども、品川区としてはどのように捉えていらっしゃるのか。その３点の施策の中で、品川区がどういう道を選択されていくのかという現状の考え方というか、捉え方を説明を求めました。","respondent":"柏原企画調整課長","answer":"特別区全国連携プロジェクトに関しましては、先ほどもお話をさせていただいたとおりです。直結的にふるさと納税とどうつなげるかというのはもう少し内部でも検討が必要かなと思いますけれども、そのつなげ方、発信の仕方は。","id":"exchange-016"},{"speaker":"横山委員","kind":"意見","question":"関係者の方々、皆様の議論、研究を深めていただいて、何かいい方法を見出していただけたらと思います。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"１５億円、１６億円をそのまま見過ごしているのですかと。ますます増えていっていますが、とめないのですかとやはり訴えたくなってしまうではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/237826?Template=document&Id=6052#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":20504,"voices":46}}]);
